// Returns BenefitService-compatible modifier descriptors contributed by a City's Arcane Academy
function getCityAcademyBenefitEffects(city) {
  const lvl = (city && city.buildings && city.buildings.arcane_academy) ? Number(city.buildings.arcane_academy) : 0;
  if (lvl <= 0) return [];
  return [
    {
      sourceType: 'city_building',
      sourceId: 'arcane_academy',
      sourceLevel: lvl,
      effectType: 'accrual_modifier',
      target: 'rp_general',
      op: 'additive',
      value: 0.25 * lvl
    },
    {
      sourceType: 'city_building',
      sourceId: 'arcane_academy',
      sourceLevel: lvl,
      effectType: 'research_speed_modifier',
      target: 'personal',
      op: 'additive',
      value: 0.10 * lvl
    }
  ];
}

// Check per-button prerequisite (e.g. facilities.shop.minLevel)
function isFacilityButtonUnlocked(facConfig, buildingLevel) {
  if (!facConfig) return { unlocked: false, minLevel: 1 };
  const minLvl = (typeof facConfig === 'object' && typeof facConfig.minLevel === 'number') ? facConfig.minLevel : 1;
  return { unlocked: Number(buildingLevel || 1) >= minLvl, minLevel: minLvl };
}

// Generate full level-by-level configuration table (cost, build time, benefits) for any building
function getBuildingLevelsTable(buildingId) {
  const bDef = CITY_BUILDINGS_CATALOG[buildingId];
  if (!bDef) return [];
  const maxLvl = bDef.maxLevel || 5;
  const rows = [];
  for (let lv = 1; lv <= maxLvl; lv++) {
    const cost = computeBuildingUpgradeCost(buildingId, lv);
    const durationMs = computeBuildingDurationMs(buildingId, lv);
    const benefits = [];
    if (bDef.productionPerTick) {
      Object.entries(bDef.productionPerTick).forEach(function(e) {
        if (e[1] > 0) benefits.push('+' + (e[1] * lv) + ' ' + e[0] + '/tick');
      });
    }
    if (bDef.providesPopulation) benefits.push('+' + (bDef.providesPopulation * lv) + ' Max Pop');
    if (bDef.storageBonus) {
      Object.entries(bDef.storageBonus).forEach(function(e) {
        benefits.push('+' + (e[1] * lv) + ' ' + e[0] + ' Cap');
      });
    }
    if (bDef.troopCapacityBonus) benefits.push('+' + (bDef.troopCapacityBonus * lv) + ' Troops');
    if (buildingId === 'garrison') benefits.push('Party Size: ' + (1 + lv));
    if (buildingId === 'warehouse') benefits.push('+' + (50 * lv) + ' Vault Slots');
    if (buildingId === 'arcane_academy') benefits.push('+' + (25 * lv) + '% Gen RP, +' + (10 * lv) + '% Res Speed');
    if (buildingId === 'market_post' && lv > 1) benefits.push('+' + ((lv - 1) * 5) + '% Sell Yield');
    if (bDef.facilities && bDef.facilities.recruitment && Array.isArray(bDef.facilities.recruitment.classes)) {
      const unlockedHere = bDef.facilities.recruitment.classes
        .filter(function(c) { return (c.minLevel || 1) === lv; })
        .map(function(c) { return 'Recruit ' + c.classId; });
      if (unlockedHere.length > 0) benefits.push(unlockedHere.join(', '));
    }
    if (bDef.facilities) {
      Object.keys(bDef.facilities).forEach(function(fk) {
        const fc = bDef.facilities[fk];
        if (fc && typeof fc === 'object' && fc.minLevel === lv && lv > 1) {
          benefits.push('Unlocks ' + fk);
        }
      });
    }
    rows.push({
      level: lv,
      cost: cost,
      durationMs: durationMs,
      benefits: benefits.length > 0 ? benefits.join(' • ') : 'Tier ' + lv + ' Operations'
    });
  }
  return rows;
}

// ============================================================================
// SHARED BLACKSMITH FORGE RECIPE & TEMPERING PREVIEW RULES (IS-01)
// Single source of truth consumed by BOTH commandBus.js and wargameUiSync.js.
// ============================================================================
const BLACKSMITH_FORGE_SLOTS = ['weapon', 'armor', 'helm', 'boots', 'accessory', 'pickaxe'];

function getBlacksmithForgeRecipePreview(slot, blacksmithLevel) {
  const sl = BLACKSMITH_FORGE_SLOTS.indexOf(slot) !== -1 ? slot : 'weapon';
  const bsLvl = Math.max(1, Math.round(Number(blacksmithLevel) || 1));
  const ingotCost = 3 + bsLvl;
  const goldCost = 20 + bsLvl * 10;
  const rarity = bsLvl >= 3 ? 'epic' : (bsLvl >= 2 ? 'rare' : 'uncommon');
  const maxSockets = sl === 'pickaxe' ? 0 : (bsLvl >= 3 ? 2 : (bsLvl >= 2 ? 1 : 0));
  const tierName = bsLvl >= 3 ? 'Star-Forged' : (bsLvl >= 2 ? 'Tempered' : 'Forged');
  const slotNames = {
    weapon: 'Greatsword',
    armor: 'Plate Cuirass',
    helm: 'Greathelm',
    boots: 'War Greaves',
    accessory: 'Runic Signet',
    pickaxe: 'Mithril Pickaxe'
  };

  const atk = sl === 'weapon' ? (10 + bsLvl * 4) : (sl === 'accessory' ? (3 + bsLvl * 2) : 0);
  const def = (sl === 'armor' || sl === 'helm' || sl === 'boots') ? (5 + bsLvl * 3) : (sl === 'accessory' ? (2 + bsLvl) : 0);
  const maxHp = sl === 'armor' ? (10 + bsLvl * 6) : 0;
  const tier = sl === 'pickaxe' ? Math.min(4, 1 + bsLvl) : undefined;
  const maxDur = sl === 'pickaxe' ? (30 + bsLvl * 10) : undefined;
  const value = 45 + bsLvl * 30;

  return {
    slot: sl,
    blacksmithLevel: bsLvl,
    name: tierName + ' ' + slotNames[sl],
    rarity: rarity,
    deterministic: true,
    ingotCost: ingotCost,
    goldCost: goldCost,
    destination: 'City Vault Storage',
    atk: atk,
    def: def,
    maxHp: maxHp,
    tier: tier,
    maxDur: maxDur,
    curDur: maxDur,
    maxSockets: maxSockets,
    value: value
  };
}

function getBlacksmithTemperPreview(item) {
  if (!item || typeof item !== 'object') {
    return { eligible: false, reason: 'No item selected.' };
  }
  const curRank = item.temperRank || 0;
  const maxRank = 3;
  const ingotCost = 2;
  const goldCost = 20;

  if (item.slot === 'pickaxe') {
    return {
      eligible: false,
      reason: 'Pickaxes are non-combat tools and cannot be tempered.',
      curRank: curRank,
      maxRank: maxRank,
      ingotCost: ingotCost,
      goldCost: goldCost
    };
  }
  if (curRank >= maxRank) {
    return {
      eligible: false,
      reason: 'Maximum Temper Rank (+3) reached.',
      curRank: curRank,
      maxRank: maxRank,
      ingotCost: ingotCost,
      goldCost: goldCost
    };
  }

  const statKey = (item.slot === 'weapon' || item.slot === 'accessory') ? 'atk' : 'def';
  const statLabel = statKey === 'atk' ? 'ATK' : 'DEF';
  const delta = 2;
  const currentStat = item[statKey] || 0;
  const nextStat = currentStat + delta;
  const valueDelta = 25;

  return {
    eligible: true,
    reason: null,
    curRank: curRank,
    nextRank: curRank + 1,
    maxRank: maxRank,
    ingotCost: ingotCost,
    goldCost: goldCost,
    statKey: statKey,
    statLabel: statLabel,
    delta: delta,
    currentStat: currentStat,
    nextStat: nextStat,
    valueDelta: valueDelta
  };
}

// Conservative authoritative city-presence check for hero-owned workshop actions.
// Returns true if hero is stationed at city (garrisoned with no overworld unit, OR party unit is alive,
// not in_dungeon, and standing at (city.x, city.y)). Away or delving heroes return false.
function isHeroPresentAtCity(world, city, hero) {
  if (!world || !city || !hero) return false;
  const ow = world.overworld;
  const units = (ow && Array.isArray(ow.units)) ? ow.units : [];
  const partyUnit = units.find(function(u) {
    if (!u || !u.alive) return false;
    if (u.leaderHeroId === hero.id) return true;
    return Array.isArray(u.heroIds) && u.heroIds.indexOf(hero.id) !== -1;
  }) || null;

  if (!partyUnit) {
    return true; // Garrisoned / unassigned hero stationed at city
  }
  if (partyUnit.status === 'in_dungeon') {
    return false;
  }
  return partyUnit.x === city.x && partyUnit.y === city.y;
}

