// TimedQueueManager — Real-Time Unit Marching, City Construction Queues & Resource Production Tickers













function scheduleNextMarchStep(unit, state, scheduler) {
  if (!unit || !unit.marchPlan || !Array.isArray(unit.marchPlan.remainingPath) || unit.marchPlan.remainingPath.length === 0) {
    return null;
  }

  const simTimeMs = state.world.clock.simTimeMs;
  const nextStep = unit.marchPlan.remainingPath[0];
  let stepDur = Math.max(250, nextStep.stepDurationMs || 3000);
  // Scout Forced Pace individual unit travel efficiency bonus (no group/army-wide boost)
  if (unit.unitType !== 'army' && typeof unit.forcedPaceUntilSimTimeMs === 'number' && unit.forcedPaceUntilSimTimeMs > simTimeMs) {
    const bonus = typeof unit.forcedPaceSpeedBonus === 'number' ? unit.forcedPaceSpeedBonus : 0.25;
    stepDur = Math.max(250, Math.round(stepDur * (1 - bonus)));
  }

  const job = scheduler.scheduleJob({
    jobId: 'march_' + unit.id + '_' + simTimeMs + '_' + Math.floor(Math.random() * 10000),
    jobType: 'UNIT_MARCH_STEP',
    ownerId: unit.id,
    startSimTimeMs: simTimeMs,
    dueSimTimeMs: simTimeMs + stepDur,
    payload: {
      unitId: unit.id,
      fromX: unit.x,
      fromY: unit.y,
      toX: nextStep.x,
      toY: nextStep.y
    }
  });

  unit.status = (unit.unitType === 'army' && unit.marchPlan.intent === 'return_home') ? 'returning' : 'marching';
  unit.marchPlan.activeJobId = job.jobId;
  unit.marchPlan.stepStartSimTimeMs = simTimeMs;
  unit.marchPlan.stepDueSimTimeMs = simTimeMs + stepDur;
  unit.marchPlan.fromX = unit.x;
  unit.marchPlan.fromY = unit.y;
  unit.marchPlan.toX = nextStep.x;
  unit.marchPlan.toY = nextStep.y;

  return job;
}

function checkAndDiscoverDungeonsInVision(ow, simTimeMs, eventStream) {
  if (!ow || !Array.isArray(ow.pois) || !Array.isArray(ow.explored)) return [];
  const newlyDiscovered = [];
  for (let i = 0; i < ow.pois.length; i++) {
    const poi = ow.pois[i];
    if (poi.type !== 'dungeon_entrance' || poi.discovered) continue;
    if (ow.explored[poi.y] && ow.explored[poi.y][poi.x]) {
      poi.discovered = true;
      newlyDiscovered.push(poi);
      if (eventStream) {
        eventStream.publish(STREAM_TOPICS.DUNGEON_DISCOVERED, {
          poiId: poi.id,
          dungeonId: poi.dungeonId,
          profileId: poi.profileId,
          dungeonName: poi.name,
          x: poi.x,
          y: poi.y
        }, simTimeMs);
      }
    }
  }
  return newlyDiscovered;
}

function depositUnitCargoAtCity(unit, city, state, simTimeMs, eventStream) {
  if (!unit || !unit.cargo || !city || !city.stockpile) return false;
  const c = unit.cargo;
  const gold = c.gold || 0;
  const ore = c.ore || 0;
  const gems = c.gems || 0;
  const gearItems = Array.isArray(c.gearItems) ? c.gearItems : [];
  const gearCount = Math.max(c.gearCount || 0, gearItems.length);
  if (gold <= 0 && ore <= 0 && gems <= 0 && gearCount <= 0) {
    unit.cargo = null;
    return false;
  }

  city.stockpile.gold = (city.stockpile.gold || 0) + gold;
  city.stockpile.ore  = (city.stockpile.ore  || 0) + ore;
  if (gems > 0) {
    if (!city.gems) city.gems = { ruby: 0, emerald: 0, sapphire: 0, topaz: 0, void_diamond: 0 };
    city.gems.ruby = (city.gems.ruby || 0) + gems;
  }

  // Deposit looted dungeon equipment items into the party leader Hero's bagGear!
  if (gearItems.length > 0 && state && state.world && Array.isArray(state.world.heroes)) {
    const leaderHero = state.world.heroes.find(function(h) { return h.id === unit.leaderHeroId; }) || state.world.heroes[0];
    if (leaderHero) {
      if (!Array.isArray(leaderHero.bagGear)) leaderHero.bagGear = [];
      for (let gi = 0; gi < gearItems.length; gi++) {
        leaderHero.bagGear.push(gearItems[gi]);
      }
    }
  }
  unit.cargo = null;
  if (state && state.world && state.world.stats) {
    state.world.stats.expeditionsBanked = (state.world.stats.expeditionsBanked || 0) + 1;
  }

  if (eventStream) {
    eventStream.publish(STREAM_TOPICS.EXPEDITION_BANKED, {
      unitId: unit.id,
      unitName: unit.shortName,
      cityId: city.id,
      cityName: city.name,
      gold: gold,
      ore: ore,
      gems: gems,
      gearCount: gearCount
    }, simTimeMs);
  }
  return true;
}

function resolveOverworldSkirmish(unit, hostile, state, scheduler, simTimeMs, eventStream) {
  if (!unit || !hostile || !hostile.alive) return { victory: true, skipped: true };
  const world = state && state.world;
  const hero = (world && Array.isArray(world.heroes))
    ? world.heroes.find(function(h) { return h.id === unit.leaderHeroId; })
    : null;

  // HR-13: Always read authoritative derived stats from shared heroStats calculator (never stale snapshots)
  const derived = hero ? computeHeroDerivedStats(hero) : null;
  const heroAtk = derived ? derived.atk : ((hero && hero.stats && hero.stats.atk) ? hero.stats.atk : 26);
  const heroDef = derived ? derived.def : ((hero && hero.stats && hero.stats.def) ? hero.stats.def : 12);
  const heroLvl = (hero && hero.level) ? hero.level : 1;
  const effectiveAtk = heroAtk + (heroLvl - 1) * 4;

  const roundsToKill = Math.max(1, Math.ceil((hostile.hp || 60) / Math.max(5, effectiveAtk)));
  const dmgPerRound = Math.max(2, (hostile.power || 18) - Math.floor(heroDef * 0.6));
  const totalDmg = dmgPerRound * Math.max(1, roundsToKill - 1);

  if ((unit.hp || 1) > totalDmg) {
    unit.hp = Math.max(1, unit.hp - totalDmg);
    hostile.alive = false;
    if (world && world.stats) {
      world.stats.skirmishesWon = (world.stats.skirmishesWon || 0) + 1;
    }
    if (hero) {
      hero.xp = (hero.xp || 0) + (hostile.rewardXp || 25);
    }
    if (!unit.cargo) {
      unit.cargo = { gold: 0, ore: 0, gems: 0, gearCount: 0 };
    }
    unit.cargo.gold = (unit.cargo.gold || 0) + (hostile.rewardGold || 20);
    unit.cargo.ore  = (unit.cargo.ore  || 0) + (hostile.rewardOre  || 4);

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.OVERWORLD_SKIRMISH, {
        victory: true,
        unitId: unit.id,
        unitName: unit.shortName,
        hostileId: hostile.id,
        hostileName: hostile.name,
        x: unit.x,
        y: unit.y,
        damageTaken: totalDmg,
        remainingHp: unit.hp,
        maxHp: unit.maxHp,
        rewardGold: hostile.rewardGold || 20,
        rewardOre: hostile.rewardOre || 4,
        rewardXp: hostile.rewardXp || 25
      }, simTimeMs);
    }
    return { victory: true, damageTaken: totalDmg };
  }

  // Defeat in Overworld Skirmish: Non-permanent retreat back to City Guild Hall
  if (unit.marchPlan && unit.marchPlan.activeJobId && scheduler) {
    scheduler.cancelJob(unit.marchPlan.activeJobId);
  }
  const city = getPrimaryCity(state);
  if (city) {
    unit.x = city.x;
    unit.y = city.y;
  }
  unit.status = 'idle';
  unit.marchPlan = null;
  unit.hp = unit.maxHp;
  unit.cargo = null;

  if (eventStream) {
    eventStream.publish(STREAM_TOPICS.OVERWORLD_SKIRMISH, {
      victory: false,
      unitId: unit.id,
      unitName: unit.shortName,
      hostileId: hostile.id,
      hostileName: hostile.name,
      x: hostile.x,
      y: hostile.y,
      damageTaken: totalDmg,
      remainingHp: unit.hp,
      maxHp: unit.maxHp,
      retreatedToCity: city ? city.name : 'Bastion'
    }, simTimeMs);
  }
  return { victory: false };
}

function resolveMarchStepJob(job, state, scheduler, eventStream) {
  if (!state || !state.world || !state.world.overworld) return;
  const ow = state.world.overworld;
  const unitId = job.payload && job.payload.unitId;
  const unit = (ow.units || []).find(function(u) { return u.id === unitId && u.alive; });
  if (!unit || !unit.marchPlan) return;

  const targetX = job.payload.toX;
  const targetY = job.payload.toY;

  unit.x = targetX;
  unit.y = targetY;
  state.world.stats.totalUnitSteps = (state.world.stats.totalUnitSteps || 0) + 1;

  revealOverworldVision(ow, unit.x, unit.y, unit.visionRadius || 4, { simTimeMs: job.dueSimTimeMs, eventStream: eventStream });
  checkAndDiscoverDungeonsInVision(ow, job.dueSimTimeMs, eventStream);

  // Check for Wandering Hostile interception for Hero Parties
  if (unit.unitType === 'hero_party' && Array.isArray(ow.hostiles)) {
    const encountered = ow.hostiles.find(function(h) {
      return h.alive && h.x === unit.x && h.y === unit.y;
    });
    if (encountered) {
      const skirmishRes = resolveOverworldSkirmish(unit, encountered, state, scheduler, job.dueSimTimeMs, eventStream);
      if (!skirmishRes.victory) {
        state._dirty = true;
        saveWargameState(state, scheduler);
        evaluateTaskDAG(state, eventStream);
        return;
      }
    }
  }

  // Check if non-army unit stepped onto a supply cache POI (armies on patrol do not harvest caches in 05B-1)
  if (unit.unitType !== 'army' && Array.isArray(ow.pois)) {
    for (let i = 0; i < ow.pois.length; i++) {
      const poi = ow.pois[i];
      if (!poi.depleted && poi.type === 'resource_cache' && poi.x === unit.x && poi.y === unit.y) {
        poi.depleted = true;
        const yieldRes = poi.yield || { wood: 25, stone: 20 };
        const cityKeys = Object.keys(state.world.cities || {});
        const stock = cityKeys.length > 0
          ? state.world.cities[cityKeys[0]].stockpile
          : state.world.realmStockpile;
        if (yieldRes.wood) stock.wood = (stock.wood || 0) + yieldRes.wood;
        if (yieldRes.stone) stock.stone = (stock.stone || 0) + yieldRes.stone;
        if (yieldRes.food) stock.food = (stock.food || 0) + yieldRes.food;
        state.world.stats.resourcesHarvested = (state.world.stats.resourcesHarvested || 0) + 1;
        if (eventStream) {
          eventStream.publish(STREAM_TOPICS.RESOURCE_HARVESTED, {
            unitId: unit.id,
            unitName: unit.shortName,
            poiName: poi.name,
            yield: yieldRes
          }, job.dueSimTimeMs);
        }
      }
    }
  }

  // Pop the completed step from remainingPath
  if (Array.isArray(unit.marchPlan.remainingPath) && unit.marchPlan.remainingPath.length > 0) {
    unit.marchPlan.remainingPath.shift();
  }

  if (eventStream) {
    eventStream.publish(STREAM_TOPICS.UNIT_MARCH_STEP, {
      unitId: unit.id,
      unitName: unit.shortName,
      x: unit.x,
      y: unit.y,
      remainingSteps: unit.marchPlan.remainingPath ? unit.marchPlan.remainingPath.length : 0
    }, job.dueSimTimeMs);
  }

  // Schedule next step or complete march
  if (unit.marchPlan.remainingPath && unit.marchPlan.remainingPath.length > 0) {
    scheduleNextMarchStep(unit, state, scheduler);
  } else {
    const completedIntent = unit.marchPlan.intent || 'move';
    unit.status = 'idle';
    unit.marchPlan = null;

    if (unit.unitType === 'army') {
      handleArmyArrival(unit, state, scheduler, job.dueSimTimeMs, eventStream);
    } else {
      // If arriving at a friendly City carrying cargo, bank spoils into City Stockpile and restore HP
      const cityKeys = Object.keys(state.world.cities || {});
      for (let cIdx = 0; cIdx < cityKeys.length; cIdx++) {
        const city = state.world.cities[cityKeys[cIdx]];
        if (city && city.x === unit.x && city.y === unit.y) {
          unit.hp = unit.maxHp;
          if (unit.cargo) {
            depositUnitCargoAtCity(unit, city, state, job.dueSimTimeMs, eventStream);
          }
          break;
        }
      }
    }

    state._dirty = true;
    saveWargameState(state, scheduler);
    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.UNIT_MARCH_COMPLETED, {
        unitId: unit.id,
        unitName: unit.shortName,
        x: unit.x,
        y: unit.y,
        intent: completedIntent
      }, job.dueSimTimeMs);
    }
  }

  state._dirty = true;
  evaluateTaskDAG(state, eventStream);
}

function activateNextCityBuildQueueItem(city, state, scheduler) {
  if (!city || !Array.isArray(city.buildQueue) || city.buildQueue.length === 0) return null;

  // Check if the front item is already active
  const front = city.buildQueue[0];
  if (front.status === 'building' || front.status === 'demolishing' || front.status === 'moving') return front;

  const simTimeMs = state.world.clock.simTimeMs;
  const dur = Math.max(500, front.durationMs || 4000);
  const isMove = front.type === 'move';
  const isDemolishOrCleanup = front.type === 'demolish' || front.type === 'cleanup';

  let jobType = 'CITY_BUILDING_COMPLETE';
  let jobPrefix = 'build_';
  if (isMove) {
    jobType = 'CITY_BUILDING_MOVE_COMPLETE';
    jobPrefix = 'move_';
  } else if (isDemolishOrCleanup) {
    jobType = 'CITY_BUILDING_DEMOLISH_COMPLETE';
    jobPrefix = 'demolish_';
  }

  const job = scheduler.scheduleJob({
    jobId: jobPrefix + city.id + '_plot_' + (isMove ? (front.fromPlotIndex + '_' + front.toPlotIndex) : front.plotIndex) + '_' + simTimeMs,
    jobType: jobType,
    ownerId: city.id,
    startSimTimeMs: simTimeMs,
    dueSimTimeMs: simTimeMs + dur,
    payload: isMove ? {
      cityId: city.id,
      queueItemId: front.queueItemId,
      fromPlotIndex: front.fromPlotIndex,
      toPlotIndex: front.toPlotIndex,
      buildingId: front.buildingId,
      level: front.level
    } : {
      cityId: city.id,
      queueItemId: front.queueItemId,
      plotIndex: front.plotIndex,
      buildingId: front.buildingId,
      targetLevel: front.targetLevel,
      actionType: front.type || 'build',
      previousLevel: front.previousLevel || 0,
      salvage: front.salvage || null
    }
  });

  front.status = isMove ? 'moving' : (isDemolishOrCleanup ? 'demolishing' : 'building');
  front.jobId = job.jobId;
  front.startSimTimeMs = simTimeMs;
  front.dueSimTimeMs = simTimeMs + dur;

  if (isMove) {
    const fromPlot = (city.plots || []).find(function(p) { return p.plotIndex === front.fromPlotIndex; });
    const toPlot   = (city.plots || []).find(function(p) { return p.plotIndex === front.toPlotIndex; });
    if (fromPlot) { fromPlot.relocating = true; fromPlot.activeJobId = job.jobId; }
    if (toPlot)   { toPlot.relocating = true; toPlot.activeJobId = job.jobId; }
  } else {
    const plot = (city.plots || []).find(function(p) { return p.plotIndex === front.plotIndex; });
    if (plot) {
      if (isDemolishOrCleanup) {
        plot.demolishing = true;
        plot.underConstruction = false;
      } else {
        plot.underConstruction = true;
        plot.demolishing = false;
      }
      plot.activeJobId = job.jobId;
    }
  }

  return front;
}

function resolveBuildingCompleteJob(job, state, scheduler, eventStream) {
  if (!state || !state.world || !state.world.cities) return;
  const p = job.payload || {};
  const city = state.world.cities[p.cityId];
  if (!city) return;

  const bId = p.buildingId;
  const targetLvl = p.targetLevel || 1;

  if (!city.buildings) city.buildings = {};
  city.buildings[bId] = Math.max(city.buildings[bId] || 0, targetLvl);

  if (bId === 'meeting_hall') {
    city.level = Math.max(city.level || 1, targetLvl);
  }

  const plot = (city.plots || []).find(function(pl) { return pl.plotIndex === p.plotIndex; });
  if (plot) {
    plot.buildingId = bId;
    plot.level = targetLvl;
    plot.underConstruction = false;
    plot.demolishing = false;
    plot.activeJobId = null;
  }

  // Remove completed item from front of buildQueue
  if (Array.isArray(city.buildQueue)) {
    const idx = city.buildQueue.findIndex(function(q) { return q.queueItemId === p.queueItemId || q.jobId === job.jobId; });
    if (idx !== -1) {
      city.buildQueue.splice(idx, 1);
    }
  }

  state.world.stats.buildingsCompleted = (state.world.stats.buildingsCompleted || 0) + 1;

  // If Adventurers Guild Hall is completed, unlock GUILD_UNLOCKED phase and reveal The Starfall Vaults!
  if (bId === 'guild_hall' && targetLvl >= 1) {
    if (state.campaignPhase === CAMPAIGN_PHASES.CITY_ESTABLISHED) {
      state.campaignPhase = CAMPAIGN_PHASES.GUILD_UNLOCKED;
    }
    const ow = state.world.overworld;
    if (ow && Array.isArray(ow.pois)) {
      const starfallPoi = ow.pois.find(function(poi) { return poi.id === 'poi_dungeon_starfall' || poi.type === 'dungeon_entrance'; });
      if (starfallPoi) {
        revealOverworldVision(ow, starfallPoi.x, starfallPoi.y, 2, { simTimeMs: job.dueSimTimeMs, eventStream: eventStream });
        checkAndDiscoverDungeonsInVision(ow, job.dueSimTimeMs, eventStream);
      }
    }
  }

  const bDef = CITY_BUILDINGS_CATALOG[bId];
  if (eventStream) {
    eventStream.publish(STREAM_TOPICS.BUILDING_COMPLETED, {
      cityId: city.id,
      cityName: city.name,
      buildingId: bId,
      buildingName: bDef ? bDef.name : bId,
      level: targetLvl,
      plotIndex: p.plotIndex
    }, job.dueSimTimeMs);
  }

  // Start next queued building in this city if any
  activateNextCityBuildQueueItem(city, state, scheduler);

  state._dirty = true;
  saveWargameState(state, scheduler);
  evaluateTaskDAG(state, eventStream);
}

function resolveBuildingDemolishJob(job, state, scheduler, eventStream) {
  if (!state || !state.world || !state.world.cities) return;
  const p = job.payload || {};
  const city = state.world.cities[p.cityId];
  if (!city) return;

  const plot = (city.plots || []).find(function(pl) { return pl.plotIndex === p.plotIndex; });
  const bId = p.buildingId;
  const isDeliberate = p.actionType === 'demolish';

  if (isDeliberate) {
    // Deliberate demolition: credit salvage materials
    const salvage = p.salvage || { wood: 0, stone: 0, gold: 0, water: 0, ore: 0 };
    city.stockpile.wood  = (city.stockpile.wood  || 0) + (salvage.wood  || 0);
    city.stockpile.stone = (city.stockpile.stone || 0) + (salvage.stone || 0);
    city.stockpile.gold  = (city.stockpile.gold  || 0) + (salvage.gold  || 0);
    if (salvage.water) city.stockpile.water = (city.stockpile.water || 0) + salvage.water;
    if (salvage.ore)   city.stockpile.ore   = (city.stockpile.ore   || 0) + salvage.ore;

    if (plot) {
      plot.buildingId = null;
      plot.level = 0;
    }

    // Recompute highest level for buildingId across remaining plots
    let highestLvl = 0;
    for (let pIdx = 0; pIdx < (city.plots || []).length; pIdx++) {
      const pl = city.plots[pIdx];
      if (pl.buildingId === bId) {
        highestLvl = Math.max(highestLvl, pl.level || 0);
      }
    }
    if (highestLvl > 0) {
      if (city.buildings) city.buildings[bId] = highestLvl;
    } else if (city.buildings) {
      delete city.buildings[bId];
    }
  } else {
    // Site cleanup after cancelled construction
    if (plot) {
      const prevLvl = typeof p.previousLevel === 'number' ? p.previousLevel : 0;
      if (prevLvl <= 0) {
        plot.buildingId = null;
        plot.level = 0;
      } else {
        plot.level = prevLvl;
      }
    }
  }

  if (plot) {
    plot.underConstruction = false;
    plot.demolishing = false;
    plot.activeJobId = null;
  }

  // Remove from buildQueue
  if (Array.isArray(city.buildQueue)) {
    const idx = city.buildQueue.findIndex(function(q) { return q.queueItemId === p.queueItemId || q.jobId === job.jobId; });
    if (idx !== -1) {
      city.buildQueue.splice(idx, 1);
    }
  }

  if (eventStream) {
    eventStream.publish(isDeliberate ? STREAM_TOPICS.BUILDING_DEMOLISHED : STREAM_TOPICS.BUILDING_CANCELLED, {
      cityId: city.id,
      cityName: city.name,
      buildingId: bId,
      plotIndex: p.plotIndex,
      salvage: isDeliberate ? (p.salvage || null) : null
    }, job.dueSimTimeMs);
  }

  activateNextCityBuildQueueItem(city, state, scheduler);

  state._dirty = true;
  saveWargameState(state, scheduler);
  evaluateTaskDAG(state, eventStream);
}

function resolveBuildingMoveJob(job, state, scheduler, eventStream) {
  if (!state || !state.world || !state.world.cities) return;
  const p = job.payload || {};
  const city = state.world.cities[p.cityId];
  if (!city) return;

  const fromPlot = (city.plots || []).find(function(pl) { return pl.plotIndex === p.fromPlotIndex; });
  const toPlot   = (city.plots || []).find(function(pl) { return pl.plotIndex === p.toPlotIndex; });

  const bId = p.buildingId;
  const lvl = p.level || 1;

  if (fromPlot) {
    fromPlot.buildingId = null;
    fromPlot.level = 0;
    fromPlot.relocating = false;
    fromPlot.underConstruction = false;
    fromPlot.demolishing = false;
    fromPlot.activeJobId = null;
  }

  if (toPlot) {
    toPlot.buildingId = bId;
    toPlot.level = lvl;
    toPlot.relocating = false;
    toPlot.underConstruction = false;
    toPlot.demolishing = false;
    toPlot.activeJobId = null;
  }

  // Remove completed move from front of buildQueue
  if (Array.isArray(city.buildQueue)) {
    const idx = city.buildQueue.findIndex(function(q) { return q.queueItemId === p.queueItemId || q.jobId === job.jobId; });
    if (idx !== -1) {
      city.buildQueue.splice(idx, 1);
    }
  }

  // Update selectedPlotIndex if user was inspecting the moved structure
  if (city.selectedPlotIndex === p.fromPlotIndex) {
    city.selectedPlotIndex = p.toPlotIndex;
  }

  if (eventStream) {
    eventStream.publish(STREAM_TOPICS.BUILDING_MOVED, {
      cityId: city.id,
      cityName: city.name,
      buildingId: bId,
      fromPlotIndex: p.fromPlotIndex,
      toPlotIndex: p.toPlotIndex,
      level: lvl
    }, job.dueSimTimeMs);
  }

  activateNextCityBuildQueueItem(city, state, scheduler);

  state._dirty = true;
  saveWargameState(state, scheduler);
  evaluateTaskDAG(state, eventStream);
}

function activateNextCityRecruitQueueItem(city, state, scheduler) {
  if (!city || !Array.isArray(city.recruitmentQueue) || city.recruitmentQueue.length === 0) return null;

  // Check if an item is already active
  const front = city.recruitmentQueue[0];
  if (front.status === 'training') return front;

  const simTimeMs = state.world.clock.simTimeMs;
  const dur = Math.max(1000, front.durationMs || BASE_HERO_RECRUIT_DURATION_MS);

  const job = scheduler.scheduleJob({
    jobId: 'recruit_' + city.id + '_' + front.classId + '_' + simTimeMs,
    jobType: 'HERO_RECRUIT_COMPLETE',
    ownerId: city.id,
    startSimTimeMs: simTimeMs,
    dueSimTimeMs: simTimeMs + dur,
    payload: {
      cityId: city.id,
      queueItemId: front.queueItemId,
      classId: front.classId,
      heroName: front.heroName
    }
  });

  front.status = 'training';
  front.jobId = job.jobId;
  front.startSimTimeMs = simTimeMs;
  front.dueSimTimeMs = simTimeMs + dur;

  return front;
}

function resolveRecruitHeroJob(job, state, scheduler, eventStream) {
  if (!state || !state.world) return;
  const p = job.payload || {};
  const world = state.world;
  const city = (world.cities && world.cities[p.cityId]) || getPrimaryCity(state);
  const ow = world.overworld;

  const classDef = getRecruitableHeroEntry(p.classId);
  if (!classDef) return;

  // HR-14 Issue A: Use a monotonic hero sequence counter so newly recruited heroes
  // and party units NEVER reuse IDs of retired/dismissed heroes.
  let maxExistingSeq = (world.heroes || []).length;
  if (Array.isArray(world.heroes)) {
    for (let hi = 0; hi < world.heroes.length; hi++) {
      const mH = world.heroes[hi] && typeof world.heroes[hi].id === 'string' && world.heroes[hi].id.match(/^hero_(\d+)_/);
      if (mH) maxExistingSeq = Math.max(maxExistingSeq, Number(mH[1]) || 0);
    }
  }
  if (ow && Array.isArray(ow.units)) {
    for (let ui = 0; ui < ow.units.length; ui++) {
      const mU = ow.units[ui] && typeof ow.units[ui].id === 'string' && ow.units[ui].id.match(/^unit_party_(\d+)$/);
      if (mU) maxExistingSeq = Math.max(maxExistingSeq, Number(mU[1]) || 0);
    }
  }
  const prevSeq = (typeof world.nextHeroSeq === 'number' && isFinite(world.nextHeroSeq)) ? world.nextHeroSeq : 0;
  const heroIndex = Math.max(prevSeq, maxExistingSeq) + 1;
  world.nextHeroSeq = heroIndex;
  const heroName = String(p.heroName || (classDef.name + ' #' + heroIndex)).trim();

  // HR-02: Reuse canonical class-specific starterGear definitions from src/data/classes.js
  const canonicalClassDef = CLASSES && CLASSES[classDef.classId] ? CLASSES[classDef.classId] : null;
  const rawStarter = canonicalClassDef && canonicalClassDef.starterGear ? canonicalClassDef.starterGear : null;
  const cloneStarterSlot = function(slotKey) {
    const src = rawStarter && rawStarter[slotKey] ? rawStarter[slotKey] : null;
    if (!src) return null;
    const copy = Object.assign({}, src, {
      uid: 'eq_' + slotKey + '_' + heroIndex + '_' + classDef.classId,
      affixes: Array.isArray(src.affixes) ? src.affixes.slice() : []
    });
    if (slotKey === 'pickaxe') {
      const maxD = copy.maxDur || copy.maxDurability || 28;
      const curD = copy.curDur !== undefined ? copy.curDur : (copy.durability !== undefined ? copy.durability : maxD);
      copy.curDur = curD;
      copy.maxDur = maxD;
      if (copy.durability !== undefined) delete copy.durability;
      if (copy.maxDurability !== undefined) delete copy.maxDurability;
      if (!copy.tier) copy.tier = 1;
    }
    return copy;
  };
  const starterEq = rawStarter
    ? {
        weapon:    cloneStarterSlot('weapon'),
        armor:     cloneStarterSlot('armor'),
        helm:      cloneStarterSlot('helm'),
        boots:     cloneStarterSlot('boots'),
        accessory: cloneStarterSlot('accessory'),
        pickaxe:   cloneStarterSlot('pickaxe')
      }
    : {
        weapon:    { uid: 'eq_w_' + heroIndex, slot: 'weapon',    name: 'Guild Iron Blade',     rarity: 'common', atk: 6, def: 0, value: 25 },
        armor:     { uid: 'eq_a_' + heroIndex, slot: 'armor',     name: 'Vanguard Cuirass',     rarity: 'common', atk: 0, def: 5, value: 25 },
        helm:      { uid: 'eq_h_' + heroIndex, slot: 'helm',      name: 'Scout Steel Helm',     rarity: 'common', atk: 0, def: 2, value: 15 },
        boots:     { uid: 'eq_b_' + heroIndex, slot: 'boots',     name: 'Frontier Greaves',     rarity: 'common', atk: 0, def: 2, value: 15 },
        accessory: null,
        pickaxe:   { uid: 'eq_p_' + heroIndex, slot: 'pickaxe',   name: 'Copper Miner Pickaxe', rarity: 'common', tier: 1, curDur: 25, maxDur: 25, maxDurability: 25, durability: 25, value: 20 }
      };
  const heroObj = normalizePersistentHeroInstance({
    id: 'hero_' + heroIndex + '_' + classDef.classId,
    name: heroName,
    classId: classDef.classId,
    className: classDef.name,
    title: classDef.title,
    icon: classDef.icon,
    color: classDef.color,
    level: 1,
    xp: 0,
    maxXp: DEFAULT_PERSISTENT_HERO_MAX_XP,
    bonusStats: createDefaultBonusStats(),
    knowledge: createDefaultHeroKnowledge(),
    statPoints: 0,
    talentPoints: 0,
    talentsAllocated: {},
    stats: Object.assign({}, classDef.baseStats),
    equipment: starterEq,
    cosmetics: { cloak: null, aura: null, banner_crest: null, weapon_glow: null },
    bagGear: [
      { uid: 'bag_ring_' + heroIndex, slot: 'accessory', name: 'Aethelgard Signet', rarity: 'uncommon', atk: 3, def: 2, value: 45 }
    ],
    ownerPlayerId: getCanonicalPlayerId(state),
    recruitedAtSimMs: job.dueSimTimeMs
  });

  if (!world.heroes) world.heroes = [];
  world.heroes.push(heroObj);
  if (!world.roster) {
    world.roster = { maxHeroes: 3, overallLeaderHeroId: heroObj.id };
  } else if (!world.roster.overallLeaderHeroId) {
    world.roster.overallLeaderHeroId = heroObj.id;
  }
  world.stats.heroesRecruited = (world.stats.heroesRecruited || 0) + 1;

  // Form an Overworld Vanguard Party at the City gates led by this Hero
  const partyArch = UNIT_ARCHETYPES.hero_party;
  const spawnX = city ? city.x : (ow ? ow.spawnX : 0);
  const spawnY = city ? city.y : (ow ? ow.spawnY : 0);

  const partyUnit = {
    id: 'unit_party_' + heroIndex,
    ownerPlayerId: getCanonicalPlayerId(state),
    name: heroObj.name + '\'s Vanguard',
    shortName: heroObj.name,
    unitType: 'hero_party',
    leaderHeroId: heroObj.id,
    heroClassId: heroObj.classId,
    x: spawnX,
    y: spawnY,
    hp: heroObj.stats.hp,
    maxHp: heroObj.stats.hp,
    visionRadius: heroObj.classId === 'ranger' ? 7 : partyArch.visionRadius,
    canFoundCity: false,
    canEnterDungeon: isHeroDungeonEligible(heroObj),
    alive: true,
    status: 'idle',
    cargo: null,
    marchPlan: null
  };

  if (ow) {
    if (!ow.units) ow.units = [];
    ow.units.push(partyUnit);
    // Preserve current selection if the player is already commanding an active unit in the field
    const hasActiveSelected = Boolean(ow.selectedUnitId && ow.units.some(function(u) {
      return u.id === ow.selectedUnitId && u.alive;
    }));
    if (!hasActiveSelected) {
      ow.selectedUnitId = partyUnit.id;
    }
    revealOverworldVision(ow, partyUnit.x, partyUnit.y, partyUnit.visionRadius, { simTimeMs: job.dueSimTimeMs, eventStream: eventStream });
  }

  if (!world.parties) world.parties = [];
  world.parties.push({
    id: partyUnit.id,
    ownerPlayerId: getCanonicalPlayerId(state),
    leaderHeroId: heroObj.id,
    memberIds: [heroObj.id],
    cityId: city ? city.id : null
  });

  // Remove from recruitmentQueue
  if (city && Array.isArray(city.recruitmentQueue)) {
    const idx = city.recruitmentQueue.findIndex(function(q) { return q.queueItemId === p.queueItemId || q.jobId === job.jobId; });
    if (idx !== -1) {
      city.recruitmentQueue.splice(idx, 1);
    }
  }

  if (eventStream) {
    eventStream.publish(STREAM_TOPICS.HERO_RECRUITED, {
      heroId: heroObj.id,
      heroName: heroObj.name,
      classId: heroObj.classId,
      partyUnitId: partyUnit.id
    }, job.dueSimTimeMs);
    eventStream.publish(STREAM_TOPICS.PARTY_FORMED, {
      partyUnitId: partyUnit.id,
      leaderName: heroObj.name,
      x: partyUnit.x,
      y: partyUnit.y
    }, job.dueSimTimeMs);
  }

  if (city) {
    activateNextCityRecruitQueueItem(city, state, scheduler);
  }

  state._dirty = true;
  saveWargameState(state, scheduler);
  evaluateTaskDAG(state, eventStream);
}

function activateNextCityTroopQueueItem(city, state, scheduler) {
  if (!city || !Array.isArray(city.troopTrainingQueue) || city.troopTrainingQueue.length === 0) return null;

  const front = city.troopTrainingQueue[0];
  if (front.status === 'training' || front.status === 'upgrading') return front;

  const troopDef = getTroopDefinition(front.troopDefId);
  const simTimeMs = state.world.clock.simTimeMs;
  const isUpgrade = front.jobKind === 'upgrade';
  const dur = isUpgrade
    ? Math.max(1500, front.durationMsPerUnit || computeTroopUpgradeDurationMs(city, troopDef, front.fromLevel || 1, front.toLevel || 2))
    : Math.max(1500, front.durationMsPerUnit || computeTroopTrainingDurationMs(city, troopDef, front.level || 1));

  const job = scheduler.scheduleJob({
    jobId: (isUpgrade ? 'troop_upg_' : 'troop_') + city.id + '_' + front.troopDefId + '_' + simTimeMs + '_' + Math.floor(Math.random() * 10000),
    jobType: isUpgrade ? 'TROOP_UPGRADE_UNIT_COMPLETE' : 'TROOP_TRAIN_UNIT_COMPLETE',
    ownerId: city.id,
    startSimTimeMs: simTimeMs,
    dueSimTimeMs: simTimeMs + dur,
    payload: {
      cityId: city.id,
      queueItemId: front.queueItemId,
      troopDefId: front.troopDefId
    }
  });

  front.status = isUpgrade ? 'upgrading' : 'training';
  front.jobId = job.jobId;
  front.durationMsPerUnit = dur;
  front.startSimTimeMs = simTimeMs;
  front.dueSimTimeMs = simTimeMs + dur;

  return front;
}

function addBarracksTroopsAtLevel(world, ownerId, cityId, troopDefId, level, count, simTimeMs) {
  const qty = Math.floor(Number(count || 0));
  if (!world || !cityId || !troopDefId || qty <= 0) return null;
  const lvl = Math.max(1, Math.floor(Number(level || 1)));
  if (!Array.isArray(world.troopGroups)) world.troopGroups = [];

  let targetGroup = world.troopGroups.find(function(g) {
    return g &&
      g.ownerPlayerId === ownerId &&
      g.locationType === TROOP_LOCATION_TYPES.BARRACKS &&
      g.locationId === cityId &&
      g.troopDefId === troopDefId &&
      (g.level || 1) === lvl;
  });

  if (targetGroup) {
    targetGroup.count = (targetGroup.count || 0) + qty;
  } else {
    targetGroup = {
      id: 'tg_' + cityId + '_' + troopDefId + '_lv' + lvl + '_' + (simTimeMs || 0) + '_' + Math.floor(Math.random() * 10000),
      ownerPlayerId: ownerId,
      troopDefId: troopDefId,
      count: qty,
      level: lvl,
      xp: 0,
      condition: 100,
      locationType: TROOP_LOCATION_TYPES.BARRACKS,
      locationId: cityId,
      createdAtSimMs: simTimeMs || 0
    };
    world.troopGroups.push(targetGroup);
  }
  return targetGroup;
}

function resolveTroopTrainUnitJob(job, state, scheduler, eventStream) {
  if (!state || !state.world) return;
  const p = job.payload || {};
  const world = state.world;
  const city = (world.cities && world.cities[p.cityId]) || getPrimaryCity(state);
  if (!city || !Array.isArray(city.troopTrainingQueue)) return;

  const idx = city.troopTrainingQueue.findIndex(function(q) {
    return q && q.jobKind !== 'upgrade' && (q.queueItemId === p.queueItemId || q.jobId === job.jobId);
  });
  if (idx === -1) return;

  const item = city.troopTrainingQueue[idx];
  // Idempotency guard: prevent duplicate completion if job is replayed
  if ((item.completedCount || 0) >= (item.quantity || 0)) return;
  if (item.jobId && job.jobId && item.jobId !== job.jobId) return;

  const troopDef = getTroopDefinition(item.troopDefId);
  if (!troopDef) {
    city.troopTrainingQueue.splice(idx, 1);
    activateNextCityTroopQueueItem(city, state, scheduler);
    return;
  }

  const targetLevel = Math.max(1, Math.floor(item.level || 1));
  const ownerId = getCanonicalPlayerId(state);
  const targetGroup = addBarracksTroopsAtLevel(world, ownerId, city.id, troopDef.id, targetLevel, 1, job.dueSimTimeMs);

  item.completedCount = (item.completedCount || 0) + 1;
  if (!world.stats) world.stats = {};
  world.stats.troopsTrained = (world.stats.troopsTrained || 0) + 1;

  if (eventStream) {
    eventStream.publish(STREAM_TOPICS.TROOP_TRAINED, {
      cityId: city.id,
      troopGroupId: targetGroup ? targetGroup.id : null,
      troopDefId: troopDef.id,
      troopName: troopDef.name,
      level: targetLevel,
      completedCount: item.completedCount,
      quantity: item.quantity,
      groupCount: targetGroup ? targetGroup.count : 1
    }, job.dueSimTimeMs);
  }

  if (item.completedCount < item.quantity) {
    const nextDur = computeTroopTrainingDurationMs(city, troopDef, targetLevel);
    const nextJob = scheduler.scheduleJob({
      jobId: 'troop_' + city.id + '_' + troopDef.id + '_' + job.dueSimTimeMs + '_' + Math.floor(Math.random() * 10000),
      jobType: 'TROOP_TRAIN_UNIT_COMPLETE',
      ownerId: city.id,
      startSimTimeMs: job.dueSimTimeMs,
      dueSimTimeMs: job.dueSimTimeMs + nextDur,
      payload: {
        cityId: city.id,
        queueItemId: item.queueItemId,
        troopDefId: troopDef.id
      }
    });
    item.status = 'training';
    item.jobId = nextJob.jobId;
    item.durationMsPerUnit = nextDur;
    item.startSimTimeMs = job.dueSimTimeMs;
    item.dueSimTimeMs = job.dueSimTimeMs + nextDur;
  } else {
    city.troopTrainingQueue.splice(idx, 1);
    activateNextCityTroopQueueItem(city, state, scheduler);
  }

  state._dirty = true;
  saveWargameState(state, scheduler);
  evaluateTaskDAG(state, eventStream);
}

function resolveTroopUpgradeUnitJob(job, state, scheduler, eventStream) {
  if (!state || !state.world) return;
  const p = job.payload || {};
  const world = state.world;
  const city = (world.cities && world.cities[p.cityId]) || getPrimaryCity(state);
  if (!city || !Array.isArray(city.troopTrainingQueue)) return;

  const idx = city.troopTrainingQueue.findIndex(function(q) {
    return q && q.jobKind === 'upgrade' && (q.queueItemId === p.queueItemId || q.jobId === job.jobId);
  });
  if (idx === -1) return;

  const item = city.troopTrainingQueue[idx];
  // Idempotency guard: prevent duplicate troop creation if job fires more than once
  if ((item.completedCount || 0) >= (item.quantity || 0)) return;
  if (item.jobId && job.jobId && item.jobId !== job.jobId) return;

  const troopDef = getTroopDefinition(item.troopDefId);
  if (!troopDef) {
    city.troopTrainingQueue.splice(idx, 1);
    activateNextCityTroopQueueItem(city, state, scheduler);
    return;
  }

  const fromLevel = Math.max(1, Math.floor(item.fromLevel || 1));
  const toLevel = Math.max(fromLevel + 1, Math.floor(item.toLevel || (fromLevel + 1)));
  const ownerId = getCanonicalPlayerId(state);
  const targetGroup = addBarracksTroopsAtLevel(world, ownerId, city.id, troopDef.id, toLevel, 1, job.dueSimTimeMs);

  item.completedCount = (item.completedCount || 0) + 1;

  if (eventStream) {
    eventStream.publish(STREAM_TOPICS.TROOP_UPGRADE_COMPLETED, {
      cityId: city.id,
      troopGroupId: targetGroup ? targetGroup.id : null,
      troopDefId: troopDef.id,
      troopName: troopDef.name,
      fromLevel: fromLevel,
      toLevel: toLevel,
      completedCount: item.completedCount,
      quantity: item.quantity,
      groupCount: targetGroup ? targetGroup.count : 1
    }, job.dueSimTimeMs);
  }

  if (item.completedCount < item.quantity) {
    const nextDur = computeTroopUpgradeDurationMs(city, troopDef, fromLevel, toLevel);
    const nextJob = scheduler.scheduleJob({
      jobId: 'troop_upg_' + city.id + '_' + troopDef.id + '_' + job.dueSimTimeMs + '_' + Math.floor(Math.random() * 10000),
      jobType: 'TROOP_UPGRADE_UNIT_COMPLETE',
      ownerId: city.id,
      startSimTimeMs: job.dueSimTimeMs,
      dueSimTimeMs: job.dueSimTimeMs + nextDur,
      payload: {
        cityId: city.id,
        queueItemId: item.queueItemId,
        troopDefId: troopDef.id
      }
    });
    item.status = 'upgrading';
    item.jobId = nextJob.jobId;
    item.durationMsPerUnit = nextDur;
    item.startSimTimeMs = job.dueSimTimeMs;
    item.dueSimTimeMs = job.dueSimTimeMs + nextDur;
  } else {
    city.troopTrainingQueue.splice(idx, 1);
    activateNextCityTroopQueueItem(city, state, scheduler);
  }

  state._dirty = true;
  saveWargameState(state, scheduler);
  evaluateTaskDAG(state, eventStream);
}

// ---------------------------------------------------------------------------
// Field Army Objective, Return & Idempotent Barracks Reintegration (Task 05B-1)
// ---------------------------------------------------------------------------
function reintegrateArmyIntoBarracks(army, state, simTimeMs, eventStream) {
  if (!army || !state || !state.world) return { ok: false, skipped: true };
  // Strict idempotency guard: already reintegrated or retired armies are a safe no-op
  if (army.reintegrated || !army.alive) {
    return { ok: false, skipped: true, reason: 'already_reintegrated' };
  }

  const world = state.world;
  const homeCity = (world.cities && army.homeCityId) ? world.cities[army.homeCityId] : null;
  if (!homeCity) {
    // Safe recovery policy: if home city is missing/invalid, halt army safely & preserve troops (never delete or reassign arbitrarily)
    army.status = 'idle';
    army.marchPlan = null;
    if (army.objective) {
      army.objective.status = ARMY_OBJECTIVE_STATUS.FAILED;
      army.objective.jobId = null;
      army.objective.failureReason = 'home_city_unavailable';
    }
    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.ARMY_OBJECTIVE_FAILED, {
        armyId: army.id,
        armyName: army.shortName || army.name,
        objectiveType: army.objective ? army.objective.type : ARMY_OBJECTIVE_TYPES.RETURN_HOME,
        reason: 'Home city unavailable; army halted to preserve troops'
      }, simTimeMs);
    }
    return { ok: false, reason: 'home_city_unavailable' };
  }

  const armyGroups = getArmyTroopGroups(world, army.id);
  let totalReturned = 0;
  for (let i = 0; i < armyGroups.length; i++) {
    const g = armyGroups[i];
    const ownerId = g.ownerPlayerId || army.ownerPlayerId || getCanonicalPlayerId(state);
    addBarracksTroopsAtLevel(world, ownerId, homeCity.id, g.troopDefId, g.level || 1, g.count || 0, simTimeMs);
    totalReturned += (g.count || 0);
  }
  // Remove army-located group records now that troops have been transferred to Barracks
  if (Array.isArray(world.troopGroups)) {
    world.troopGroups = world.troopGroups.filter(function(g) {
      return !(g && g.locationType === TROOP_LOCATION_TYPES.ARMY && g.locationId === army.id);
    });
  }

  if (army.cargo) {
    depositUnitCargoAtCity(army, homeCity, state, simTimeMs, eventStream);
  }

  army.reintegrated = true;
  army.alive = false;
  army.status = 'retired';
  army.marchPlan = null;
  if (army.objective) {
    army.objective.status = ARMY_OBJECTIVE_STATUS.COMPLETED;
    army.objective.jobId = null;
  }

  const ow = world.overworld;
  if (ow && ow.selectedUnitId === army.id) {
    const nextAlive = (ow.units || []).find(function(u) { return u && u.alive && u.id !== army.id; });
    ow.selectedUnitId = nextAlive ? nextAlive.id : null;
  }

  if (eventStream) {
    eventStream.publish(STREAM_TOPICS.ARMY_REINTEGRATED, {
      armyId: army.id,
      armyName: army.shortName || army.name,
      homeCityId: homeCity.id,
      homeCityName: homeCity.name,
      troopsReturned: totalReturned
    }, simTimeMs);
  }

  return { ok: true, homeCityId: homeCity.id, troopsReturned: totalReturned };
}

function startArmyReturnHome(army, state, scheduler, simTimeMs, eventStream) {
  if (!army || !army.alive || army.reintegrated || !state || !state.world) {
    return { ok: false, reason: 'invalid_army' };
  }
  const world = state.world;
  const ow = world.overworld;
  const homeCity = (world.cities && army.homeCityId) ? world.cities[army.homeCityId] : null;
  if (!homeCity) {
    army.status = 'idle';
    army.marchPlan = null;
    if (army.objective) {
      army.objective.status = ARMY_OBJECTIVE_STATUS.FAILED;
      army.objective.jobId = null;
      army.objective.failureReason = 'home_city_unavailable';
    }
    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.ARMY_OBJECTIVE_FAILED, {
        armyId: army.id,
        armyName: army.shortName || army.name,
        objectiveType: ARMY_OBJECTIVE_TYPES.RETURN_HOME,
        reason: 'Home city unavailable; army halted to preserve troops'
      }, simTimeMs);
    }
    return { ok: false, reason: 'home_city_unavailable' };
  }

  // Cancel any active march or objective job before starting return
  if (army.marchPlan && army.marchPlan.activeJobId && scheduler) {
    scheduler.cancelJob(army.marchPlan.activeJobId);
  }
  if (army.objective && army.objective.jobId && scheduler) {
    scheduler.cancelJob(army.objective.jobId);
  }

  army.objective = {
    id: 'obj_ret_' + army.id + '_' + simTimeMs,
    type: ARMY_OBJECTIVE_TYPES.RETURN_HOME,
    status: ARMY_OBJECTIVE_STATUS.ACCEPTED,
    targetX: homeCity.x,
    targetY: homeCity.y,
    jobId: null,
    startSimTimeMs: simTimeMs,
    dueSimTimeMs: null
  };

  if (army.x === homeCity.x && army.y === homeCity.y) {
    army.objective.status = ARMY_OBJECTIVE_STATUS.ARRIVED;
    return reintegrateArmyIntoBarracks(army, state, simTimeMs, eventStream);
  }

  const path = findOverworldPath(ow, army.x, army.y, homeCity.x, homeCity.y);
  if (!path || path.length === 0) {
    army.status = 'idle';
    army.marchPlan = null;
    army.objective.status = ARMY_OBJECTIVE_STATUS.FAILED;
    army.objective.failureReason = 'return_path_unreachable';
    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.ARMY_OBJECTIVE_FAILED, {
        armyId: army.id,
        armyName: army.shortName || army.name,
        objectiveType: ARMY_OBJECTIVE_TYPES.RETURN_HOME,
        reason: 'Return path to home city is unreachable'
      }, simTimeMs);
    }
    return { ok: false, reason: 'return_path_unreachable' };
  }

  const totalMs = path.reduce(function(sum, st) { return sum + (st.stepDurationMs || 3000); }, 0);
  army.objective.status = ARMY_OBJECTIVE_STATUS.TRAVELING;
  army.marchPlan = {
    intent: 'return_home',
    targetCityId: homeCity.id,
    targetX: homeCity.x,
    targetY: homeCity.y,
    remainingPath: path,
    totalDurationMs: totalMs,
    activeJobId: null,
    stepStartSimTimeMs: simTimeMs,
    stepDueSimTimeMs: simTimeMs,
    fromX: army.x,
    fromY: army.y,
    toX: path[0].x,
    toY: path[0].y
  };

  scheduleNextMarchStep(army, state, scheduler);

  if (eventStream) {
    eventStream.publish(STREAM_TOPICS.ARMY_RETURNING, {
      armyId: army.id,
      armyName: army.shortName || army.name,
      homeCityId: homeCity.id,
      homeCityName: homeCity.name,
      stepsCount: path.length
    }, simTimeMs);
  }

  return { ok: true, stepsCount: path.length };
}

function applyArmyCombatCasualties(world, armyId, allocations) {
  if (!world || !Array.isArray(world.troopGroups) || !Array.isArray(allocations)) return 0;
  const lossByGroupId = {};
  for (let i = 0; i < allocations.length; i++) {
    const al = allocations[i];
    if (al && al.groupId && al.lost > 0) {
      lossByGroupId[al.groupId] = al.lost;
    }
  }
  let applied = 0;
  const remaining = [];
  for (let i = 0; i < world.troopGroups.length; i++) {
    const g = world.troopGroups[i];
    if (!g) continue;
    if (g.locationType === TROOP_LOCATION_TYPES.ARMY && g.locationId === armyId && lossByGroupId[g.id]) {
      const deduct = Math.min(g.count || 0, lossByGroupId[g.id]);
      g.count = Math.max(0, (g.count || 0) - deduct);
      applied += deduct;
      if (g.count > 0) remaining.push(g);
    } else {
      remaining.push(g);
    }
  }
  world.troopGroups = remaining;
  return applied;
}

// Competing-army lifecycle cleanup (Task 05B-2):
// When one army clears a military target, any other active army still marching toward or engaged
// with that same target cleanly cancels its stale march/objective job, marks the objective failed
// without duplicate combat, and honors its return policy (or idles safely if stayDeployed).
function cleanupCompetingArmiesForClearedTarget(targetId, winningArmyId, state, scheduler, simTimeMs, eventStream) {
  if (!targetId || !state || !state.world || !state.world.overworld) return 0;
  const ow = state.world.overworld;
  const units = Array.isArray(ow.units) ? ow.units : [];
  let cleaned = 0;

  for (let i = 0; i < units.length; i++) {
    const other = units[i];
    if (!other || !other.alive || other.reintegrated || other.unitType !== 'army') continue;
    if (winningArmyId && other.id === winningArmyId) continue;
    if (!other.objective || other.objective.type !== ARMY_OBJECTIVE_TYPES.ENGAGE_TARGET) continue;
    if (other.objective.targetId !== targetId) continue;
    if (other.objective.status === ARMY_OBJECTIVE_STATUS.COMPLETED || other.objective.status === ARMY_OBJECTIVE_STATUS.FAILED) continue;

    if (other.marchPlan && other.marchPlan.activeJobId && scheduler) {
      scheduler.cancelJob(other.marchPlan.activeJobId);
    }
    if (other.objective.jobId && scheduler) {
      scheduler.cancelJob(other.objective.jobId);
    }

    other.marchPlan = null;
    other.status = 'idle';
    other.objective.status = ARMY_OBJECTIVE_STATUS.FAILED;
    other.objective.jobId = null;
    other.objective.failureReason = 'target_already_cleared';
    cleaned++;

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.ARMY_OBJECTIVE_FAILED, {
        armyId: other.id,
        armyName: other.shortName || other.name,
        objectiveType: ARMY_OBJECTIVE_TYPES.ENGAGE_TARGET,
        targetId: targetId,
        reason: 'Military target was already cleared by another army'
      }, simTimeMs);
    }

    if (!other.stayDeployed) {
      startArmyReturnHome(other, state, scheduler, simTimeMs, eventStream);
    }
  }
  return cleaned;
}

function handleArmyArrival(army, state, scheduler, simTimeMs, eventStream) {
  if (!army || !army.alive || army.reintegrated) return;
  if (!army.objective) {
    army.status = 'idle';
    return;
  }

  army.objective.status = ARMY_OBJECTIVE_STATUS.ARRIVED;

  if (army.objective.type === ARMY_OBJECTIVE_TYPES.RETURN_HOME) {
    reintegrateArmyIntoBarracks(army, state, simTimeMs, eventStream);
    return;
  }

  if (army.objective.type === ARMY_OBJECTIVE_TYPES.ENGAGE_TARGET) {
    const ow = state && state.world && state.world.overworld;
    const target = getMilitaryTargetById(ow, army.objective.targetId);
    if (!target || target.status === MILITARY_TARGET_STATUS.CLEARED) {
      army.status = 'idle';
      army.objective.status = ARMY_OBJECTIVE_STATUS.FAILED;
      army.objective.jobId = null;
      army.objective.failureReason = 'target_already_cleared';
      if (eventStream) {
        eventStream.publish(STREAM_TOPICS.ARMY_OBJECTIVE_FAILED, {
          armyId: army.id,
          armyName: army.shortName || army.name,
          objectiveType: ARMY_OBJECTIVE_TYPES.ENGAGE_TARGET,
          targetId: army.objective.targetId || null,
          reason: 'Military target is already cleared'
        }, simTimeMs);
      }
      if (!army.stayDeployed) {
        startArmyReturnHome(army, state, scheduler, simTimeMs, eventStream);
      }
      return;
    }

    const roundDur = Math.max(250, ARMY_COMBAT_ROUND_DURATION_MS || ARMY_COMBAT_DURATION_MS || 3000);
    const battle = createMilitaryBattleState(state.world, army, target, simTimeMs, roundDur);
    const job = scheduler ? scheduler.scheduleJob({
      jobId: 'army_cbt_' + army.id + '_r1_' + simTimeMs + '_' + Math.floor(Math.random() * 10000),
      jobType: 'ARMY_OBJECTIVE_COMPLETE',
      ownerId: army.id,
      startSimTimeMs: simTimeMs,
      dueSimTimeMs: simTimeMs + roundDur,
      payload: {
        armyId: army.id,
        objectiveId: army.objective.id,
        objectiveType: army.objective.type,
        targetId: target.id,
        battleId: battle.battleId,
        expectedRound: 1
      }
    }) : null;

    army.status = 'objective_in_progress';
    army.objective.status = ARMY_OBJECTIVE_STATUS.IN_PROGRESS;
    army.objective.jobId = job ? job.jobId : null;
    army.objective.startSimTimeMs = simTimeMs;
    army.objective.dueSimTimeMs = simTimeMs + roundDur;
    army.objective.battle = battle;

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.ARMY_COMBAT_STARTED, {
        battleId: battle.battleId,
        armyId: army.id,
        armyName: army.shortName || army.name,
        targetId: target.id,
        targetName: target.name,
        enemyPower: target.enemyPower,
        friendlyPower: battle.initialStrengths.friendlyPower,
        friendlyTroops: battle.initialStrengths.friendlyTroops,
        plannedRounds: battle.plannedRounds,
        roundDurationMs: roundDur,
        x: target.x,
        y: target.y,
        durationMs: roundDur
      }, simTimeMs);
    }
    return;
  }

  if (army.objective.type === ARMY_OBJECTIVE_TYPES.PATROL_HEX) {
    const patrolDur = Math.max(250, ARMY_PATROL_DURATION_MS || 3000);
    const job = scheduler ? scheduler.scheduleJob({
      jobId: 'army_obj_' + army.id + '_' + simTimeMs + '_' + Math.floor(Math.random() * 10000),
      jobType: 'ARMY_OBJECTIVE_COMPLETE',
      ownerId: army.id,
      startSimTimeMs: simTimeMs,
      dueSimTimeMs: simTimeMs + patrolDur,
      payload: {
        armyId: army.id,
        objectiveId: army.objective.id,
        objectiveType: army.objective.type
      }
    }) : null;

    army.status = 'objective_in_progress';
    army.objective.status = ARMY_OBJECTIVE_STATUS.IN_PROGRESS;
    army.objective.jobId = job ? job.jobId : null;
    army.objective.startSimTimeMs = simTimeMs;
    army.objective.dueSimTimeMs = simTimeMs + patrolDur;

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.ARMY_OBJECTIVE_STARTED, {
        armyId: army.id,
        armyName: army.shortName || army.name,
        objectiveType: army.objective.type,
        x: army.x,
        y: army.y,
        durationMs: patrolDur
      }, simTimeMs);
    }
    return;
  }

  // Fallback for unrecognized objective types: fail cleanly without auto-returning
  army.status = 'idle';
  army.objective.status = ARMY_OBJECTIVE_STATUS.FAILED;
  army.objective.jobId = null;
}

function resolveArmyObjectiveCompleteJob(job, state, scheduler, eventStream) {
  if (!state || !state.world || !state.world.overworld) return;
  const p = job.payload || {};
  const ow = state.world.overworld;
  const army = (ow.units || []).find(function(u) {
    return u && u.alive && u.unitType === 'army' && u.id === p.armyId;
  });
  if (!army || army.reintegrated || !army.objective) return;
  // Strict idempotency guard: only complete matching in-progress objective job
  if (army.status !== 'objective_in_progress' || army.objective.status !== ARMY_OBJECTIVE_STATUS.IN_PROGRESS) return;
  if (army.objective.jobId && job.jobId && army.objective.jobId !== job.jobId) return;

  if (army.objective.type === ARMY_OBJECTIVE_TYPES.ENGAGE_TARGET) {
    const targetId = army.objective.targetId || p.targetId || null;
    const target = getMilitaryTargetById(ow, targetId);
    if (!target || target.status === MILITARY_TARGET_STATUS.CLEARED) {
      army.objective.status = ARMY_OBJECTIVE_STATUS.FAILED;
      army.objective.jobId = null;
      army.objective.failureReason = 'target_already_cleared';
      army.status = 'idle';
      if (eventStream) {
        eventStream.publish(STREAM_TOPICS.ARMY_OBJECTIVE_FAILED, {
          armyId: army.id,
          armyName: army.shortName || army.name,
          objectiveType: ARMY_OBJECTIVE_TYPES.ENGAGE_TARGET,
          targetId: targetId,
          reason: 'Military target was already cleared'
        }, job.dueSimTimeMs);
      }
      if (!army.stayDeployed) {
        startArmyReturnHome(army, state, scheduler, job.dueSimTimeMs, eventStream);
      }
      state._dirty = true;
      saveWargameState(state, scheduler);
      evaluateTaskDAG(state, eventStream);
      return;
    }

    // Backfill battle state if resuming a pre-CB01 mid-combat save
    if (!army.objective.battle) {
      army.objective.battle = createMilitaryBattleState(
        state.world,
        army,
        target,
        army.objective.startSimTimeMs || job.dueSimTimeMs,
        ARMY_COMBAT_ROUND_DURATION_MS
      );
    }
    const battle = army.objective.battle;

    // Strict per-round idempotency guard: never apply the same round twice
    if (typeof p.expectedRound === 'number' && p.expectedRound !== (battle.currentRound || 0) + 1) {
      return;
    }

    const step = computeNextBattleRoundStep(state.world, army.id, battle, job.dueSimTimeMs);
    if (step.skipped) return;

    // Apply this round's casualties directly to authoritative world.troopGroups[]
    if (step.friendlyLosses > 0) {
      applyArmyCombatCasualties(state.world, army.id, step.allocations);
    }

    const updatedFriendlyPower = computeArmyCombatPower(state.world, army.id);
    battle.currentRound = step.round;
    battle.friendlyTotalLosses = (battle.friendlyTotalLosses || 0) + step.friendlyLosses;
    battle.enemyTotalLosses = (battle.enemyTotalLosses || 0) + step.enemyPowerLost;
    battle.plannedFriendlyLossesRemaining = Math.max(0, (battle.plannedFriendlyLossesRemaining || 0) - step.friendlyLosses);
    battle.plannedEnemyLossesRemaining = Math.max(0, (battle.plannedEnemyLossesRemaining || 0) - step.enemyPowerLost);
    battle.finalStrengths = {
      friendlyTroops: step.friendlyTroopsAfter,
      friendlyPower: updatedFriendlyPower,
      enemyPower: step.enemyPowerAfter
    };

    const roundEntry = {
      round: step.round,
      simTimeMs: job.dueSimTimeMs,
      friendlyLosses: step.friendlyLosses,
      enemyPowerLost: step.enemyPowerLost,
      friendlyTroopsAfter: step.friendlyTroopsAfter,
      friendlyPowerAfter: updatedFriendlyPower,
      enemyPowerAfter: step.enemyPowerAfter,
      casualtyEvents: step.casualtyEvents
    };
    if (!Array.isArray(battle.rounds)) battle.rounds = [];
    battle.rounds.push(roundEntry);
    if (!Array.isArray(battle.casualtyEvents)) battle.casualtyEvents = [];
    for (let ci = 0; ci < step.casualtyEvents.length; ci++) {
      battle.casualtyEvents.push(step.casualtyEvents[ci]);
    }

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.ARMY_COMBAT_ROUND_RESOLVED, {
        battleId: battle.battleId,
        armyId: army.id,
        armyName: army.shortName || army.name,
        targetId: target.id,
        targetName: target.name,
        x: target.x,
        y: target.y,
        round: step.round,
        plannedRounds: battle.plannedRounds,
        friendlyLosses: step.friendlyLosses,
        enemyPowerLost: step.enemyPowerLost,
        friendlyTroopsAfter: step.friendlyTroopsAfter,
        enemyPowerAfter: step.enemyPowerAfter,
        terminal: step.terminal
      }, job.dueSimTimeMs);
    }

    // If battle has not reached a terminal condition, schedule the next discrete round
    if (!step.terminal) {
      const nextRound = battle.currentRound + 1;
      const nextDur = Math.max(250, battle.roundDurationMs || ARMY_COMBAT_ROUND_DURATION_MS || 3000);
      const nextJob = scheduler ? scheduler.scheduleJob({
        jobId: 'army_cbt_' + army.id + '_r' + nextRound + '_' + job.dueSimTimeMs + '_' + Math.floor(Math.random() * 10000),
        jobType: 'ARMY_OBJECTIVE_COMPLETE',
        ownerId: army.id,
        startSimTimeMs: job.dueSimTimeMs,
        dueSimTimeMs: job.dueSimTimeMs + nextDur,
        payload: {
          armyId: army.id,
          objectiveId: army.objective.id,
          objectiveType: army.objective.type,
          targetId: target.id,
          battleId: battle.battleId,
          expectedRound: nextRound
        }
      }) : null;
      army.objective.jobId = nextJob ? nextJob.jobId : null;
      army.objective.startSimTimeMs = job.dueSimTimeMs;
      army.objective.dueSimTimeMs = job.dueSimTimeMs + nextDur;
      state._dirty = true;
      saveWargameState(state, scheduler);
      return;
    }

    // Terminal round reached: finalize battle record & preserve for future reporting (CB-05)
    const isVictory = step.outcome === 'victory';
    battle.endedAtSimMs = job.dueSimTimeMs;
    battle.outcome = step.outcome;
    battle.roundCount = battle.currentRound;
    const unlockedLabels = isVictory && Array.isArray(target.blocksAccess)
      ? target.blocksAccess.map(function(b) { return b.label || b.targetRef; })
      : [];
    battle.rewards = { unlockedLabels: unlockedLabels };

    if (!Array.isArray(state.world.battleHistory)) state.world.battleHistory = [];
    state.world.battleHistory.push({
      battleId: battle.battleId,
      participants: battle.participants,
      location: battle.location,
      targetId: battle.targetId,
      targetName: battle.targetName,
      startedAtSimMs: battle.startedAtSimMs,
      endedAtSimMs: battle.endedAtSimMs,
      roundCount: battle.roundCount,
      rounds: battle.rounds.slice(),
      casualtyEvents: battle.casualtyEvents.slice(),
      initialStrengths: battle.initialStrengths,
      finalStrengths: battle.finalStrengths,
      friendlyTotalLosses: battle.friendlyTotalLosses,
      enemyTotalLosses: battle.enemyTotalLosses,
      outcome: battle.outcome,
      rewards: battle.rewards
    });
    if (state.world.battleHistory.length > 50) {
      state.world.battleHistory.shift();
    }

    const report = {
      battleId: battle.battleId,
      simTimeMs: job.dueSimTimeMs,
      armyId: army.id,
      armyName: army.shortName || army.name,
      targetId: target.id,
      targetName: target.name,
      x: target.x,
      y: target.y,
      roundCount: battle.roundCount,
      victory: isVictory,
      outcome: battle.outcome,
      armyPower: battle.initialStrengths.friendlyPower,
      enemyPower: battle.initialStrengths.enemyPower,
      initialTroops: battle.initialStrengths.friendlyTroops,
      totalLosses: battle.friendlyTotalLosses,
      survivingTroops: battle.finalStrengths.friendlyTroops,
      survivingPower: battle.finalStrengths.friendlyPower,
      enemyInitialPower: battle.initialStrengths.enemyPower,
      enemySurvivingPower: battle.finalStrengths.enemyPower,
      enemyLosses: battle.enemyTotalLosses,
      unlockedLabels: unlockedLabels
    };
    army.lastCombatResult = report;
    state.world.lastMilitaryCombatReport = report;
    army.objective.jobId = null;
    army.status = 'idle';

    if (isVictory) {
      target.status = MILITARY_TARGET_STATUS.CLEARED;
      target.clearedAtSimMs = job.dueSimTimeMs;
      target.clearedByArmyId = army.id;
      army.objective.status = ARMY_OBJECTIVE_STATUS.COMPLETED;

      revealOverworldVision(ow, army.x, army.y, army.visionRadius || 4, { simTimeMs: job.dueSimTimeMs, eventStream: eventStream });

      if (eventStream) {
        eventStream.publish(STREAM_TOPICS.ARMY_COMBAT_RESOLVED, report, job.dueSimTimeMs);
        eventStream.publish(STREAM_TOPICS.MILITARY_TARGET_CLEARED, {
          targetId: target.id,
          targetName: target.name,
          armyId: army.id,
          armyName: army.shortName || army.name,
          unlockedLabels: unlockedLabels,
          x: target.x,
          y: target.y
        }, job.dueSimTimeMs);
      }

      // Clean up any other competing armies still marching to or targeting this now-cleared target
      cleanupCompetingArmiesForClearedTarget(target.id, army.id, state, scheduler, job.dueSimTimeMs, eventStream);

      if (!army.stayDeployed) {
        startArmyReturnHome(army, state, scheduler, job.dueSimTimeMs, eventStream);
      }
    } else {
      army.objective.status = ARMY_OBJECTIVE_STATUS.FAILED;
      army.objective.failureReason = 'combat_defeat';

      if (eventStream) {
        eventStream.publish(STREAM_TOPICS.ARMY_COMBAT_RESOLVED, report, job.dueSimTimeMs);
      }

      // Safe defeat lifecycle: survivors always retreat back to Home City Barracks for reintegration & retry
      startArmyReturnHome(army, state, scheduler, job.dueSimTimeMs, eventStream);
    }

    state._dirty = true;
    saveWargameState(state, scheduler);
    evaluateTaskDAG(state, eventStream);
    return;
  }

  army.objective.status = ARMY_OBJECTIVE_STATUS.COMPLETED;
  army.objective.jobId = null;
  army.status = 'idle';

  revealOverworldVision(ow, army.x, army.y, army.visionRadius || 4, { simTimeMs: job.dueSimTimeMs, eventStream: eventStream });

  if (eventStream) {
    eventStream.publish(STREAM_TOPICS.ARMY_OBJECTIVE_COMPLETED, {
      armyId: army.id,
      armyName: army.shortName || army.name,
      objectiveType: army.objective.type,
      x: army.x,
      y: army.y,
      stayDeployed: Boolean(army.stayDeployed)
    }, job.dueSimTimeMs);
  }

  // Return policy evaluated ONLY on successful objective completion
  if (!army.stayDeployed) {
    startArmyReturnHome(army, state, scheduler, job.dueSimTimeMs, eventStream);
  }

  state._dirty = true;
  saveWargameState(state, scheduler);
  evaluateTaskDAG(state, eventStream);
}

function processResourceProductionTick(state, eventStream) {
  if (!state || !state.world || !state.world.cities) return;
  const cityIds = Object.keys(state.world.cities);
  if (cityIds.length === 0) return;
  let popChanged = false;

  for (let i = 0; i < cityIds.length; i++) {
    const city = state.world.cities[cityIds[i]];
    if (!city || !city.stockpile) continue;

    // 1. Recompute population capacity from Meeting Hall and active Huts
    if (!city.population) {
      city.population = { current: 5, max: 10, growthProgress: 0, starving: false, starveTicks: 0 };
    }
    let maxPop = 10;
    if (Array.isArray(city.plots)) {
      for (let p = 0; p < city.plots.length; p++) {
        const pl = city.plots[p];
        if (pl.buildingId === 'hut' && (pl.level || 0) > 0 && !pl.demolishing) {
          maxPop += (pl.level || 1) * 5;
        }
      }
    }
    city.population.max = maxPop;
    if (typeof city.population.current !== 'number') {
      city.population.current = 5;
    }

    // 2. Subsistence token production: Every city produces +1 food, wood, stone, gold, water baseline per tick
    const gains = { wood: 1, stone: 1, food: 1, gold: 1, water: 1, ore: 0 };

    if (Array.isArray(city.plots) && city.plots.length > 0) {
      // Spatial plot-based production with adjacency bonuses
      for (let p = 0; p < city.plots.length; p++) {
        const plot = city.plots[p];
        const bId = plot.buildingId;
        const lvl = plot.level || 0;
        if (!bId || lvl <= 0 || plot.underConstruction || plot.demolishing || plot.relocating) continue;

        // Skip meeting_hall here because token baseline is already accounted for
        if (bId === 'meeting_hall') continue;

        const bDef = CITY_BUILDINGS_CATALOG[bId];
        if (!bDef || !bDef.productionPerTick) continue;

        // Check for adjacent active Windmills on the 8x8 grid
        let windmillCount = 0;
        const px = plot.x !== undefined ? plot.x : (plot.plotIndex % 8);
        const py = plot.y !== undefined ? plot.y : Math.floor(plot.plotIndex / 8);
        const neighbors = [
          { x: px + 1, y: py },
          { x: px - 1, y: py },
          { x: px, y: py + 1 },
          { x: px, y: py - 1 }
        ];
        for (let n = 0; n < neighbors.length; n++) {
          const nb = neighbors[n];
          if (nb.x >= 0 && nb.x < 8 && nb.y >= 0 && nb.y < 8) {
            const nPlot = city.plots[nb.y * 8 + nb.x];
            if (nPlot && nPlot.buildingId === 'windmill' && (nPlot.level || 0) > 0 && !nPlot.underConstruction && !nPlot.demolishing) {
              windmillCount++;
            }
          }
        }

        const mult = 1.0 + (windmillCount * (WINDMILL_ADJACENCY_BONUS || 0.20));
        const prod = bDef.productionPerTick;
        if (prod.wood)  gains.wood  += Math.round(prod.wood  * lvl * mult);
        if (prod.stone) gains.stone += Math.round(prod.stone * lvl * mult);
        if (prod.food)  gains.food  += Math.round(prod.food  * lvl * mult);
        if (prod.gold)  gains.gold  += Math.round(prod.gold  * lvl * mult);
        if (prod.water) gains.water += Math.round(prod.water * lvl * mult);
        if (prod.ore)   gains.ore   += Math.round(prod.ore   * lvl * mult);
      }
    } else if (city.buildings) {
      // Fallback for legacy state
      const bKeys = Object.keys(city.buildings);
      for (let k = 0; k < bKeys.length; k++) {
        const bId = bKeys[k];
        if (bId === 'meeting_hall') continue;
        const lvl = city.buildings[bId] || 0;
        if (lvl <= 0) continue;
        const bDef = CITY_BUILDINGS_CATALOG[bId];
        if (bDef && bDef.productionPerTick) {
          if (bDef.productionPerTick.wood)  gains.wood  += bDef.productionPerTick.wood * lvl;
          if (bDef.productionPerTick.stone) gains.stone += bDef.productionPerTick.stone * lvl;
          if (bDef.productionPerTick.food)  gains.food  += bDef.productionPerTick.food * lvl;
          if (bDef.productionPerTick.gold)  gains.gold  += bDef.productionPerTick.gold * lvl;
          if (bDef.productionPerTick.water) gains.water += bDef.productionPerTick.water * lvl;
          if (bDef.productionPerTick.ore)   gains.ore   += bDef.productionPerTick.ore * lvl;
        }
      }
    }

    // Add passive production gains up to storage caps (never deleting overflow expedition spoils or task rewards!)
    const caps = computeCityStorageCaps(city);
    function addProductionCapped(cur, gain, cap) {
      const base = cur || 0;
      if (gain <= 0) return base;
      if (base >= cap) return base;
      return Math.min(cap, base + gain);
    }
    city.stockpile.wood  = addProductionCapped(city.stockpile.wood,  gains.wood,  caps.wood  || 200);
    city.stockpile.stone = addProductionCapped(city.stockpile.stone, gains.stone, caps.stone || 200);
    city.stockpile.food  = addProductionCapped(city.stockpile.food,  gains.food,  caps.food  || 200);
    city.stockpile.gold  = addProductionCapped(city.stockpile.gold,  gains.gold,  caps.gold  || 300);
    city.stockpile.water = addProductionCapped(city.stockpile.water, gains.water, caps.water || 200);
    city.stockpile.ore   = addProductionCapped(city.stockpile.ore,   gains.ore,   caps.ore   || 100);

    // 3. Population Sustenance Consumption & Starvation Dynamics
    // Demand scales with population: 1 food and 1 water per 5 citizens
    const foodDemand = Math.max(1, Math.ceil(city.population.current / 5));
    const waterDemand = Math.max(1, Math.ceil(city.population.current / 5));

    if ((city.stockpile.food || 0) >= foodDemand && (city.stockpile.water || 0) >= waterDemand) {
      city.stockpile.food  -= foodDemand;
      city.stockpile.water -= waterDemand;
      city.population.starving = false;
      city.population.starveTicks = 0;

      // Natural Population Growth: advances when food & water are satisfied
      if (city.population.current < city.population.max) {
        city.population.growthProgress = (city.population.growthProgress || 0) + 25;
        if (city.population.growthProgress >= 100) {
          city.population.current += 1;
          city.population.growthProgress = 0;
          popChanged = true;
        }
      }
    } else {
      // Starvation: insufficient food or water!
      city.stockpile.food  = Math.max(0, (city.stockpile.food || 0) - foodDemand);
      city.stockpile.water = Math.max(0, (city.stockpile.water || 0) - waterDemand);
      city.population.starving = true;
      city.population.growthProgress = 0;
      city.population.starveTicks = (city.population.starveTicks || 0) + 1;

      // After 2 consecutive starved ticks, a citizen is lost to famine
      if (city.population.starveTicks >= 2 && city.population.current > 3) {
        city.population.current -= 1;
        city.population.starveTicks = 0;
        popChanged = true;
      }
    }

    if (eventStream && (gains.wood > 0 || gains.stone > 0 || gains.food > 0 || gains.gold > 0 || gains.water > 0 || gains.ore > 0)) {
      eventStream.publish(STREAM_TOPICS.RESOURCE_TICK, {
        cityId: city.id,
        cityName: city.name,
        gains: gains,
        stockpile: {
          wood: city.stockpile.wood,
          stone: city.stockpile.stone,
          food: city.stockpile.food,
          gold: city.stockpile.gold,
          water: city.stockpile.water,
          ore: city.stockpile.ore
        }
      }, state.world.clock.simTimeMs);
    }
  }

  // Immediately re-evaluate Task DAG when population changes (e.g., Frontier Growth to 12)
  if (popChanged) {
    state._dirty = true;
    evaluateTaskDAG(state, eventStream);
  }
}

// Compute live 0..1 interpolation coordinates for smooth real-time unit rendering on the Overworld canvas
function getUnitInterpolatedPosition(unit, currentSimTimeMs) {
  if (!unit) return { x: 0, y: 0, progress: 0 };
  if ((unit.status !== 'marching' && unit.status !== 'returning') || !unit.marchPlan) {
    return { x: unit.x, y: unit.y, progress: 0 };
  }
  const mp = unit.marchPlan;
  const start = mp.stepStartSimTimeMs || 0;
  const due   = mp.stepDueSimTimeMs   || (start + 1000);
  const dur   = Math.max(1, due - start);
  const elapsed = Math.max(0, Math.min(dur, currentSimTimeMs - start));
  const t = elapsed / dur;

  const ix = mp.fromX + (mp.toX - mp.fromX) * t;
  const iy = mp.fromY + (mp.toY - mp.fromY) * t;
  return { x: ix, y: iy, progress: t };
}

  // --- Module: src/engine/wargameBridge.js ---
// Shared Cross-Engine Handoff Bridge between Macro Wargame (wargame.html) and Tactical Dungeon Engine (index.html)
// Uses a dedicated localStorage envelope so both engines remain 100% standalone-capable with zero regressions.

const BRIDGE_STORAGE_KEY = 'aethelgard_bridge_handoff_v1';

const BRIDGE_DIRECTIONS = {
  TO_DUNGEON: 'wargame_to_dungeon',
  TO_WARGAME: 'dungeon_to_wargame'
};

function createDungeonEntryEnvelope(data) {
  const src = data || {};
  return {
    version: 1,
    direction: BRIDGE_DIRECTIONS.TO_DUNGEON,
    timestamp: Date.now(),
    campaignId: src.campaignId || 'world_prime',
    seedCode: src.seedCode || 'STAR-7777',
    houseName: src.houseName || 'House Vanguard',
    cityId: src.cityId || null,
    cityName: src.cityName || 'Oakhaven Bastion',
    cityCoords: src.cityCoords ? { x: src.cityCoords.x, y: src.cityCoords.y } : null,
    partyUnitId: src.partyUnitId || null,
    hero: src.hero ? {
      id: src.hero.id || null,
      name: src.hero.name || 'Vanguard Hero',
      classId: src.hero.classId || 'bruiser',
      level: typeof src.hero.level === 'number' ? src.hero.level : 1,
      xp: typeof src.hero.xp === 'number' ? src.hero.xp : 0,
      equipment: src.hero.equipment ? JSON.parse(JSON.stringify(src.hero.equipment)) : null,
      cosmetics: src.hero.cosmetics ? JSON.parse(JSON.stringify(src.hero.cosmetics)) : null
    } : null,
    dungeon: src.dungeon ? {
      poiId: src.dungeon.poiId || null,
      dungeonId: src.dungeon.dungeonId || 'dng_starfall',
      profileId: src.dungeon.profileId || 'starfall_vaults',
      name: src.dungeon.name || 'The Starfall Vaults',
      coords: src.dungeon.coords ? { x: src.dungeon.coords.x, y: src.dungeon.coords.y } : null
    } : null
  };
}

function createDungeonReturnEnvelope(data) {
  const src = data || {};
  const loot = src.lootSummary || {};
  return {
    version: 1,
    direction: BRIDGE_DIRECTIONS.TO_WARGAME,
    outcome: src.outcome === 'defeated' ? 'defeated' : 'extracted',
    method: src.method || 'Floor 1 Ascending Stairs (<)',
    timestamp: Date.now(),
    partyUnitId: src.partyUnitId || null,
    heroId: src.heroId || null,
    heroLevel: typeof src.heroLevel === 'number' ? src.heroLevel : 1,
    heroXp: typeof src.heroXp === 'number' ? src.heroXp : 0,
    dungeonId: src.dungeonId || 'dng_starfall',
    dungeonPoiId: src.dungeonPoiId || null,
    killerName: src.killerName || null,
    floorDepth: typeof src.floorDepth === 'number' ? src.floorDepth : 1,
    lootSummary: {
      gold: typeof loot.gold === 'number' ? loot.gold : 0,
      ore: typeof loot.ore === 'number' ? loot.ore : 0,
      gems: typeof loot.gems === 'number' ? loot.gems : 0,
      gearCount: typeof loot.gearCount === 'number' ? loot.gearCount : 0,
      salvagedGold: typeof loot.salvagedGold === 'number' ? loot.salvagedGold : 0
    },
    extractedGear: Array.isArray(src.extractedGear) ? JSON.parse(JSON.stringify(src.extractedGear)) : [],
    heroEquipment: src.heroEquipment ? JSON.parse(JSON.stringify(src.heroEquipment)) : null
  };
}

function writeDungeonEntryHandoff(data) {
  const envelope = createDungeonEntryEnvelope(data);
  if (typeof localStorage !== 'undefined') {
    try {
      localStorage.setItem(BRIDGE_STORAGE_KEY, JSON.stringify(envelope));
    } catch (e) {
      // Ignore storage quota errors in restricted environments
    }
  }
  return envelope;
}

function writeDungeonReturnHandoff(data) {
  const envelope = createDungeonReturnEnvelope(data);
  if (typeof localStorage !== 'undefined') {
    try {
      localStorage.setItem(BRIDGE_STORAGE_KEY, JSON.stringify(envelope));
    } catch (e) {
      // Ignore storage quota errors in restricted environments
    }
  }
  return envelope;
}

function peekBridgeHandoff(expectedDirection) {
  if (typeof localStorage === 'undefined') return null;
  try {
    const raw = localStorage.getItem(BRIDGE_STORAGE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== 'object') return null;
    if (expectedDirection && parsed.direction !== expectedDirection) return null;
    return parsed;
  } catch (e) {
    return null;
  }
}

function clearBridgeHandoff() {
  if (typeof localStorage === 'undefined') return;
  try {
    if (typeof localStorage.removeItem === 'function') {
      localStorage.removeItem(BRIDGE_STORAGE_KEY);
    } else {
      localStorage.setItem(BRIDGE_STORAGE_KEY, '');
    }
  } catch (e) {
    // Ignore storage errors
  }
}

function consumeBridgeHandoff(expectedDirection) {
  const env = peekBridgeHandoff(expectedDirection);
  if (!env) return null;
  clearBridgeHandoff();
  return env;
}

  // --- Module: src/wargame/engine/commandBus.js ---
// Authoritative Command Bus & Simulation Host Engine
// All player actions are dispatched as serializable Command Envelopes, validated, and applied to the World state.






















function dispatchWargameCommand(commandEnvelope, state, scheduler, eventStream) {
  if (!commandEnvelope || !commandEnvelope.type) {
    return { ok: false, reason: 'Malformed command envelope' };
  }

  const cmdType = commandEnvelope.type;
  const payload = commandEnvelope.payload || {};
  const simTimeMs = (state && state.world && state.world.clock) ? state.world.clock.simTimeMs : 0;

  function reject(reason) {
    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.COMMAND_REJECTED, {
        commandType: cmdType,
        reason: reason
      }, simTimeMs);
    }
    return { ok: false, reason: reason };
  }

  function accept(resultPayload) {
    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.COMMAND_ACCEPTED, {
        commandType: cmdType,
        result: resultPayload
      }, simTimeMs);
    }
    return { ok: true, data: resultPayload };
  }

  // ---------------------------------------------------------------------------
  // 1. START NEW CAMPAIGN (Transitions from TITLE -> SETTLER_PIONEER)
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.START_NEW_CAMPAIGN) {
    const fresh = createNewCampaignWorldState(payload);
    Object.keys(state).forEach(function(k) { delete state[k]; });
    Object.assign(state, fresh);
    if (scheduler) scheduler.clear();

    evaluateTaskDAG(state, eventStream);
    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.CAMPAIGN_STARTED, {
        houseName: state.world.player.houseName,
        worldName: state.world.name,
        seedCode: state.world.seedCode,
        settlerId: 'unit_settler_1'
      }, 0);
    }
    return accept({ campaignPhase: state.campaignPhase, worldName: state.world.name });
  }

  // Ensure an active world exists for all subsequent commands
  if (!state || !state.world) {
    return reject('No active campaign world');
  }

  const world = state.world;
  const ow = world.overworld;

  // ---------------------------------------------------------------------------
  // 2. ORDER UNIT MARCH (Real-Time A* Pathfinding & Scheduled Step Queue)
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.ORDER_UNIT_MARCH) {
    const unitId = payload.unitId || ow.selectedUnitId;
    const unit = (ow.units || []).find(function(u) { return u.id === unitId && u.alive; });
    if (!unit) return reject('No active unit selected for march');
    if (unit.status === 'in_dungeon') return reject('Unit is currently delving inside a dungeon');

    const targetX = Number(payload.targetX);
    const targetY = Number(payload.targetY);
    if (isNaN(targetX) || isNaN(targetY)) return reject('Invalid destination coordinates');

    if (unit.x === targetX && unit.y === targetY) {
      return reject('Unit is already at that coordinate');
    }

    if (!isOverworldTilePassable(ow, targetX, targetY)) {
      const tId = (ow.tiles[targetY] && ow.tiles[targetY][targetX]) || 0;
      const tDef = OVERWORLD_TERRAIN_DEFS[tId];
      return reject('Impassable terrain: ' + (tDef ? tDef.name : 'Blocked'));
    }

    const path = findOverworldPath(ow, unit.x, unit.y, targetX, targetY);
    if (!path || path.length === 0) {
      return reject('No passable route to destination');
    }

    // Cancel existing march job if unit was already moving
    if (unit.marchPlan && unit.marchPlan.activeJobId && scheduler) {
      scheduler.cancelJob(unit.marchPlan.activeJobId);
    }

    const totalMs = path.reduce(function(sum, st) { return sum + (st.stepDurationMs || 3000); }, 0);
    unit.marchPlan = {
      intent: payload.intent || 'move',
      targetPoiId: payload.targetPoiId || null,
      targetCityId: payload.targetCityId || null,
      targetX: targetX,
      targetY: targetY,
      remainingPath: path,
      totalDurationMs: totalMs,
      activeJobId: null,
      stepStartSimTimeMs: simTimeMs,
      stepDueSimTimeMs: simTimeMs,
      fromX: unit.x,
      fromY: unit.y,
      toX: path[0].x,
      toY: path[0].y
    };

    scheduleNextMarchStep(unit, state, scheduler);

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.UNIT_MARCH_STARTED, {
        unitId: unit.id,
        unitName: unit.shortName,
        fromX: unit.x,
        fromY: unit.y,
        targetX: targetX,
        targetY: targetY,
        stepsCount: path.length,
        totalDurationMs: totalMs
      }, simTimeMs);
    }

    return accept({
      unitId: unit.id,
      stepsCount: path.length,
      totalDurationMs: totalMs,
      path: path
    });
  }

  // ---------------------------------------------------------------------------
  // 3. STEP UNIT ADJACENT (Hex-validated 6-direction or legacy adjacent wrapper)
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.STEP_UNIT_ADJACENT) {
    const unit = getSelectedOverworldUnit(state);
    if (!unit) return reject('No active unit selected');

    let targetX = null;
    let targetY = null;

    if (payload.hexDir !== undefined && payload.hexDir !== null) {
      const neighbor = getHexNeighborInDirection(unit.x, unit.y, payload.hexDir, ow);
      if (!neighbor) {
        return reject('Invalid or out-of-bounds hex direction');
      }
      targetX = neighbor.x;
      targetY = neighbor.y;
    } else {
      const dx = Number(payload.dx || 0);
      const dy = Number(payload.dy || 0);
      if (isNaN(dx) || isNaN(dy)) {
        return reject('Invalid step offset');
      }
      targetX = unit.x + dx;
      targetY = unit.y + dy;
      if (!isInOverworldBounds(ow, targetX, targetY) || !areHexesAdjacent(unit.x, unit.y, targetX, targetY)) {
        return reject('Target tile is not an adjacent hex');
      }
    }

    return dispatchWargameCommand({
      type: COMMAND_TYPES.ORDER_UNIT_MARCH,
      payload: {
        unitId: unit.id,
        targetX: targetX,
        targetY: targetY
      }
    }, state, scheduler, eventStream);
  }

  // ---------------------------------------------------------------------------
  // 4. CANCEL UNIT MARCH
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.CANCEL_UNIT_MARCH) {
    const unitId = payload.unitId || ow.selectedUnitId;
    const unit = (ow.units || []).find(function(u) { return u.id === unitId && u.alive; });
    if (!unit || unit.status !== 'marching' || !unit.marchPlan) {
      return reject('Unit is not currently marching');
    }
    if (unit.marchPlan.activeJobId && scheduler) {
      scheduler.cancelJob(unit.marchPlan.activeJobId);
    }
    unit.status = 'idle';
    unit.marchPlan = null;
    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.UNIT_MARCH_CANCELLED, {
        unitId: unit.id,
        unitName: unit.shortName,
        x: unit.x,
        y: unit.y
      }, simTimeMs);
    }
    return accept({ unitId: unit.id, x: unit.x, y: unit.y });
  }

  // ---------------------------------------------------------------------------
  // 5. FOUND CITY (Consumes Pioneer Settler & Establishes Primary Bastion)
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.FOUND_CITY) {
    const unitId = payload.unitId || ow.selectedUnitId;
    const unit = (ow.units || []).find(function(u) { return u.id === unitId && u.alive; });
    if (!unit || !unit.canFoundCity) {
      return reject('Selected unit cannot found a city');
    }

    const tId = ow.tiles[unit.y][unit.x];
    const tDef = OVERWORLD_TERRAIN_DEFS[tId];
    if (!tDef || !tDef.buildable) {
      return reject('Cities can only be founded on Sunlit Grasslands or Verdant River Vales');
    }

    // Cancel any active march
    if (unit.marchPlan && unit.marchPlan.activeJobId && scheduler) {
      scheduler.cancelJob(unit.marchPlan.activeJobId);
    }

    // Consume the settler unit
    unit.alive = false;
    unit.status = 'settled';
    unit.marchPlan = null;

    const existingCitiesCount = Object.keys(world.cities || {}).length;
    const cityId = 'city_' + (existingCitiesCount + 1);
    const cityName = String(payload.cityName || (existingCitiesCount === 0 ? 'Oakhaven Bastion' : 'Bastion ' + (existingCitiesCount + 1))).trim();

    // Transfer pioneer realm stockpile into the founded city + grant founding bonus
    const baseStock = world.realmStockpile || { wood: 50, stone: 50, food: 100, gold: 50 };
    const newCity = {
      id: cityId,
      ownerPlayerId: getCanonicalPlayerId(state),
      name: cityName,
      x: unit.x,
      y: unit.y,
      level: 1,
      foundedAtSimMs: simTimeMs,
      stockpile: {
        wood:  (baseStock.wood  || 0) + 40,
        stone: (baseStock.stone || 0) + 40,
        food:  (baseStock.food  || 0) + 50,
        gold:  (baseStock.gold  || 0) + 25,
        water: (baseStock.water || 0) + 30,
        ore:   (baseStock.ore   || 0) + 15,
        ingots: 0
      },
      provisions: {
        potions: 2,
        recalls: 1
      },
      gems: {
        ruby: 1,
        emerald: 1,
        sapphire: 0,
        topaz: 0,
        void_diamond: 0
      },
      // IMPORTANT: Only canonical meeting_hall starts at level 1!
      buildings: {
        meeting_hall: 1
      },
      population: {
        current: 5,
        max: 10,
        growthProgress: 0,
        starving: false,
        starveTicks: 0
      },
      plots: createDefaultCityPlots(),
      selectedPlotIndex: CITY_CENTER_PLOT_INDEX !== undefined ? CITY_CENTER_PLOT_INDEX : 27,
      buildQueue: [],
      maxBuildQueueSlots: BASE_BUILD_QUEUE_LIMIT || 3,
      recruitmentQueue: [],
      maxRecruitQueueSlots: BASE_RECRUIT_QUEUE_LIMIT || 3,
      troopTrainingQueue: [],
      maxTroopQueueSlots: BASE_TROOP_QUEUE_LIMIT || 3,
      storage: createInventoryContainer('city_storage_' + cityId, cityName + ' Vault Storage', CITY_STORAGE_BASE_CAPACITY || 200)
    };

    world.cities[cityId] = newCity;
    world.activeCityId = cityId;
    world.stats.citiesFounded = (world.stats.citiesFounded || 0) + 1;

    if (state.campaignPhase === CAMPAIGN_PHASES.SETTLER_PIONEER) {
      state.campaignPhase = CAMPAIGN_PHASES.CITY_ESTABLISHED;
    }

    revealOverworldVision(ow, newCity.x, newCity.y, 5, { simTimeMs: simTimeMs, eventStream: eventStream });

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.CITY_FOUNDED, {
        cityId: newCity.id,
        cityName: newCity.name,
        x: newCity.x,
        y: newCity.y
      }, simTimeMs);
    }

    evaluateTaskDAG(state, eventStream);

    return accept({
      city: newCity,
      campaignPhase: state.campaignPhase
    });
  }

  // ---------------------------------------------------------------------------
  // 6. RESPAWN SETTLER (Safe Non-Permanent Loss Recovery before City Founding)
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.RESPAWN_SETTLER) {
    if (Object.keys(world.cities || {}).length > 0) {
      return reject('Cannot respawn starter settler after a city has been established');
    }
    const existingAlive = (ow.units || []).find(function(u) { return u.unitType === 'settler' && u.alive; });
    if (existingAlive) {
      return reject('Pioneer Settler is still active on the Overworld');
    }

    const settlerArch = UNIT_ARCHETYPES.settler;
    const revived = {
      id: 'unit_settler_' + (ow.units.length + 1),
      name: settlerArch.name,
      shortName: settlerArch.shortName,
      unitType: 'settler',
      x: ow.spawnX,
      y: ow.spawnY,
      hp: settlerArch.maxHp,
      maxHp: settlerArch.maxHp,
      visionRadius: settlerArch.visionRadius,
      canFoundCity: true,
      canEnterDungeon: false,
      alive: true,
      status: 'idle',
      marchPlan: null
    };

    ow.units.push(revived);
    ow.selectedUnitId = revived.id;
    revealOverworldVision(ow, revived.x, revived.y, revived.visionRadius, { simTimeMs: simTimeMs, eventStream: eventStream });

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.SETTLER_RESPAWNED, {
        unitId: revived.id,
        x: revived.x,
        y: revived.y
      }, simTimeMs);
    }

    return accept({ settler: revived });
  }

  // ---------------------------------------------------------------------------
  // 6B. SELECT CITY PLOT (Focus Inspector on Specific 8x8 Grid Plot)
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.SELECT_CITY_PLOT) {
    const city = (payload.cityId && world.cities[payload.cityId]) || getPrimaryCity(state);
    if (!city) return reject('No city founded yet');
    const plotIndex = typeof payload.plotIndex === 'number' ? payload.plotIndex : -1;
    if (plotIndex < 0 || plotIndex >= (city.plots ? city.plots.length : (CITY_TOTAL_PLOTS || 64))) {
      return reject('Invalid city plot coordinate: ' + plotIndex);
    }
    city.selectedPlotIndex = plotIndex;
    return accept({ selectedPlotIndex: plotIndex });
  }

  // ---------------------------------------------------------------------------
  // 7. QUEUE BUILDING (Real-Time City Construction Queue)
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.QUEUE_BUILDING) {
    const city = (payload.cityId && world.cities[payload.cityId]) || getPrimaryCity(state);
    if (!city) return reject('No city founded yet');

    const buildingId = payload.buildingId;
    const bDef = CITY_BUILDINGS_CATALOG[buildingId];
    if (!bDef) return reject('Unknown building type: ' + buildingId);

    const plotIndex = typeof payload.plotIndex === 'number' ? payload.plotIndex : -1;
    const plot = (city.plots || []).find(function(p) { return p.plotIndex === plotIndex; });
    if (!plot) return reject('Invalid city building plot');

    if (city.buildQueue.length >= (city.maxBuildQueueSlots || 3)) {
      return reject('City construction queue is full');
    }

    if (plot.underConstruction || plot.demolishing || plot.relocating) {
      return reject('That plot already has an active order');
    }

    const isSameBuilding = (plot.buildingId === buildingId);

    if (plot.buildingId && !isSameBuilding) {
      return reject('Plot is already occupied by ' + plot.buildingId);
    }

    // Enforce configurable per-city construction limit on NEW builds (upgrades of existing building remain allowed)
    if (!isSameBuilding) {
      const limitInfo = evaluateCityBuildingLimit(city, buildingId);
      if (limitInfo.atLimit) {
        return reject(limitInfo.reason || (bDef.name + ' is limited to ' + limitInfo.maxPerCity + ' per city'));
      }
    }

    // Check building prerequisites & population requirements
    if (!isBuildingPrerequisiteMet(city, buildingId)) {
      const reason = getBuildingPrerequisiteMissingReason(city, buildingId);
      return reject(reason || 'Prerequisites not met');
    }

    const currentLevel = isSameBuilding ? (plot.level || 0) : 0;
    const targetLevel = currentLevel + 1;
    if (targetLevel > (bDef.maxLevel || 5)) {
      return reject(bDef.name + ' has reached maximum level');
    }

    // Meeting Hall Rule: No building in the city can exceed the level of the Meeting Hall
    if (buildingId !== 'meeting_hall') {
      const meetingHallLevel = Math.max(
        (city.buildings && city.buildings.meeting_hall) || 0,
        1
      );
      if (targetLevel > meetingHallLevel) {
        return reject('Cannot exceed Meeting Hall level (' + meetingHallLevel + ')');
      }
    }

    const cost = computeBuildingUpgradeCost(buildingId, targetLevel);
    const stock = city.stockpile;
    if ((stock.wood  || 0) < (cost.wood  || 0) ||
        (stock.stone || 0) < (cost.stone || 0) ||
        (stock.gold  || 0) < (cost.gold  || 0) ||
        (stock.water || 0) < (cost.water || 0) ||
        (stock.ore   || 0) < (cost.ore   || 0)) {
      return reject('Insufficient city stockpiles (Need ' + cost.wood + ' Wood, ' + cost.stone + ' Stone, ' + cost.gold + ' Gold)');
    }

    // Deduct construction cost upfront
    stock.wood  = (stock.wood  || 0) - (cost.wood  || 0);
    stock.stone = (stock.stone || 0) - (cost.stone || 0);
    stock.gold  = (stock.gold  || 0) - (cost.gold  || 0);
    if (cost.water) stock.water = (stock.water || 0) - cost.water;
    if (cost.ore)   stock.ore   = (stock.ore   || 0) - cost.ore;

    const durationMs = computeBuildingDurationMs(buildingId, targetLevel);
    const queueItem = {
      queueItemId: 'q_' + city.id + '_' + Date.now() + '_' + Math.floor(Math.random() * 1000),
      cityId: city.id,
      plotIndex: plot.plotIndex,
      buildingId: buildingId,
      buildingName: bDef.name,
      targetLevel: targetLevel,
      previousLevel: currentLevel,
      cost: cost,
      durationMs: durationMs,
      status: 'queued', // 'queued' | 'building'
      jobId: null,
      startSimTimeMs: null,
      dueSimTimeMs: null
    };

    plot.underConstruction = true;
    city.selectedPlotIndex = plot.plotIndex;
    city.buildQueue.push(queueItem);

    // If this is the front of the queue, schedule the completion timer immediately
    activateNextCityBuildQueueItem(city, state, scheduler);

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.BUILDING_QUEUED, {
        cityId: city.id,
        cityName: city.name,
        buildingId: buildingId,
        buildingName: bDef.name,
        targetLevel: targetLevel,
        plotIndex: plot.plotIndex,
        durationMs: durationMs
      }, simTimeMs);
    }

    return accept({
      queueItem: queueItem,
      stockpile: city.stockpile
    });
  }

  // ---------------------------------------------------------------------------
  // 7B. MOVE BUILDING (Timed Relocation to an Empty 8x8 Grid Plot)
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.MOVE_BUILDING) {
    const city = (payload.cityId && world.cities[payload.cityId]) || getPrimaryCity(state);
    if (!city) return reject('No city founded yet');

    const fromIdx = typeof payload.fromPlotIndex === 'number' ? payload.fromPlotIndex : -1;
    const toIdx   = typeof payload.toPlotIndex === 'number' ? payload.toPlotIndex : -1;

    const fromPlot = (city.plots || []).find(function(p) { return p.plotIndex === fromIdx; });
    const toPlot   = (city.plots || []).find(function(p) { return p.plotIndex === toIdx; });

    if (!fromPlot) return reject('Invalid source plot: ' + fromIdx);
    if (!toPlot)   return reject('Invalid destination plot: ' + toIdx);
    if (fromIdx === toIdx) return reject('Destination plot must be different from source');

    if (!fromPlot.buildingId || (fromPlot.level || 0) <= 0) {
      return reject('No building exists on source plot');
    }

    if (fromPlot.underConstruction || fromPlot.demolishing || fromPlot.relocating) {
      return reject('Source plot is currently undergoing an active order');
    }

    if (toPlot.buildingId || toPlot.underConstruction || toPlot.demolishing || toPlot.relocating) {
      return reject('Destination plot is already occupied or undergoing an order');
    }

    if (city.buildQueue.length >= (city.maxBuildQueueSlots || BASE_BUILD_QUEUE_LIMIT || 3)) {
      return reject('City construction queue is full');
    }

    const bId = fromPlot.buildingId;
    const bDef = CITY_BUILDINGS_CATALOG[bId];
    const lvl = fromPlot.level || 1;
    const durMs = BASE_MOVE_BUILDING_DURATION_MS || 2500;

    const queueItem = {
      queueItemId: 'move_' + city.id + '_p' + fromIdx + '_to_p' + toIdx + '_' + Date.now(),
      cityId: city.id,
      fromPlotIndex: fromIdx,
      toPlotIndex: toIdx,
      buildingId: bId,
      buildingName: bDef ? bDef.name : bId,
      level: lvl,
      type: 'move',
      durationMs: durMs,
      status: 'queued',
      jobId: null,
      startSimTimeMs: null,
      dueSimTimeMs: null
    };

    fromPlot.relocating = true;
    toPlot.relocating = true;
    city.selectedPlotIndex = toIdx;
    city.buildQueue.push(queueItem);
    activateNextCityBuildQueueItem(city, state, scheduler);

    return accept({ queueItem: queueItem });
  }

  // ---------------------------------------------------------------------------
  // 8. CANCEL BUILDING IN QUEUE (Prorated Refund + 50% Time Spent Cleanup Job)
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.CANCEL_BUILDING) {
    const city = (payload.cityId && world.cities[payload.cityId]) || getPrimaryCity(state);
    if (!city || !Array.isArray(city.buildQueue) || city.buildQueue.length === 0) {
      return reject('No queued construction to cancel');
    }

    const qId = payload.queueItemId;
    const idx = qId
      ? city.buildQueue.findIndex(function(q) { return q.queueItemId === qId; })
      : (typeof payload.plotIndex === 'number'
          ? city.buildQueue.findIndex(function(q) { return q.plotIndex === payload.plotIndex; })
          : city.buildQueue.length - 1);

    if (idx === -1) return reject('Construction item not found');
    const targetItem = city.buildQueue[idx];

    if (targetItem.type === 'cleanup') {
      return reject('Site cleanup cannot be cancelled');
    }

    if (targetItem.type === 'move') {
      city.buildQueue.splice(idx, 1);
      if (targetItem.jobId && scheduler) {
        scheduler.cancelJob(targetItem.jobId);
      }
      const fromPlot = (city.plots || []).find(function(p) { return p.plotIndex === targetItem.fromPlotIndex; });
      const toPlot   = (city.plots || []).find(function(p) { return p.plotIndex === targetItem.toPlotIndex; });
      if (fromPlot) { fromPlot.relocating = false; fromPlot.activeJobId = null; }
      if (toPlot)   { toPlot.relocating = false; toPlot.activeJobId = null; }
      activateNextCityBuildQueueItem(city, state, scheduler);
      return accept({ cancelled: targetItem });
    }

    if (targetItem.status === 'queued') {
      // Pending item: 100% full refund
      city.buildQueue.splice(idx, 1);
      if (targetItem.cost) {
        city.stockpile.wood  = (city.stockpile.wood  || 0) + (targetItem.cost.wood  || 0);
        city.stockpile.stone = (city.stockpile.stone || 0) + (targetItem.cost.stone || 0);
        city.stockpile.gold  = (city.stockpile.gold  || 0) + (targetItem.cost.gold  || 0);
        if (targetItem.cost.water) city.stockpile.water = (city.stockpile.water || 0) + targetItem.cost.water;
        if (targetItem.cost.ore)   city.stockpile.ore   = (city.stockpile.ore   || 0) + targetItem.cost.ore;
      }
      const plot = (city.plots || []).find(function(p) { return p.plotIndex === targetItem.plotIndex; });
      if (plot) {
        plot.underConstruction = false;
        plot.demolishing = false;
        plot.activeJobId = null;
      }
      if (eventStream) {
        eventStream.publish(STREAM_TOPICS.BUILDING_CANCELLED, {
          cityId: city.id,
          buildingId: targetItem.buildingId,
          buildingName: targetItem.buildingName,
          refundRatio: 1.0
        }, simTimeMs);
      }
      return accept({ cancelled: targetItem, stockpile: city.stockpile });
    }

    // Active item (status === 'building'):
    // Calculate elapsed time & prorated refund based on remaining time ratio (1.0 - elapsed / dur)
    if (targetItem.jobId && scheduler) {
      scheduler.cancelJob(targetItem.jobId);
    }
    const elapsed = Math.max(0, simTimeMs - (targetItem.startSimTimeMs || simTimeMs));
    const totalDur = Math.max(1, targetItem.durationMs || 4000);
    const unspentRatio = Math.max(0, Math.min(1, 1.0 - (elapsed / totalDur)));

    if (targetItem.cost) {
      city.stockpile.wood  = (city.stockpile.wood  || 0) + Math.floor((targetItem.cost.wood  || 0) * unspentRatio);
      city.stockpile.stone = (city.stockpile.stone || 0) + Math.floor((targetItem.cost.stone || 0) * unspentRatio);
      city.stockpile.gold  = (city.stockpile.gold  || 0) + Math.floor((targetItem.cost.gold  || 0) * unspentRatio);
      if (targetItem.cost.water) city.stockpile.water = (city.stockpile.water || 0) + Math.floor(targetItem.cost.water * unspentRatio);
      if (targetItem.cost.ore)   city.stockpile.ore   = (city.stockpile.ore   || 0) + Math.floor(targetItem.cost.ore * unspentRatio);
    }

    // Replace the active queue item with a cleanup job taking 50% of already spent time (min 1000ms)
    const cleanupDur = Math.max(1000, Math.floor(elapsed * (CANCEL_CLEANUP_TIME_RATIO || 0.50)));
    const cleanupItem = {
      queueItemId: 'cleanup_' + targetItem.queueItemId,
      cityId: city.id,
      plotIndex: targetItem.plotIndex,
      buildingId: targetItem.buildingId,
      buildingName: targetItem.buildingName,
      type: 'cleanup',
      previousLevel: targetItem.previousLevel || 0,
      durationMs: cleanupDur,
      status: 'queued',
      jobId: null,
      startSimTimeMs: null,
      dueSimTimeMs: null
    };

    city.buildQueue.splice(idx, 1, cleanupItem);
    activateNextCityBuildQueueItem(city, state, scheduler);

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.BUILDING_CANCELLED, {
        cityId: city.id,
        buildingId: targetItem.buildingId,
        buildingName: targetItem.buildingName,
        refundRatio: unspentRatio,
        cleanupDurationMs: cleanupDur
      }, simTimeMs);
    }

    return accept({ cancelled: targetItem, cleanup: cleanupItem, stockpile: city.stockpile });
  }

  // ---------------------------------------------------------------------------
  // 8B. DEMOLISH BUILDING (Takes 50% Build Time & Yields 35% Salvage)
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.DEMOLISH_BUILDING) {
    const city = (payload.cityId && world.cities[payload.cityId]) || getPrimaryCity(state);
    if (!city) return reject('No city founded yet');

    const plotIndex = typeof payload.plotIndex === 'number' ? payload.plotIndex : -1;
    const plot = (city.plots || []).find(function(p) { return p.plotIndex === plotIndex; });
    if (!plot || !plot.buildingId || (plot.level || 0) <= 0) {
      return reject('No established building to demolish on this plot');
    }

    if (plot.buildingId === 'meeting_hall') {
      return reject('The Meeting Hall cannot be demolished');
    }

    if (plot.underConstruction || plot.demolishing) {
      return reject('Plot already has an active construction or demolition order');
    }

    if (city.buildQueue.length >= (city.maxBuildQueueSlots || BASE_BUILD_QUEUE_LIMIT || 3)) {
      return reject('City construction queue is full');
    }

    const bId = plot.buildingId;
    const bDef = CITY_BUILDINGS_CATALOG[bId];
    const lvl = plot.level || 1;
    const cost = computeBuildingUpgradeCost(bId, lvl);
    const baseDur = computeBuildingDurationMs(bId, lvl);

    const demolishDur = Math.max(2000, Math.floor(baseDur * (CANCEL_CLEANUP_TIME_RATIO || 0.50)));
    const salvage = {
      wood:  Math.floor((cost.wood  || 0) * (DEMOLISH_SALVAGE_RATIO || 0.35)),
      stone: Math.floor((cost.stone || 0) * (DEMOLISH_SALVAGE_RATIO || 0.35)),
      gold:  Math.floor((cost.gold  || 0) * (DEMOLISH_SALVAGE_RATIO || 0.35)),
      water: Math.floor((cost.water || 0) * (DEMOLISH_SALVAGE_RATIO || 0.35)),
      ore:   Math.floor((cost.ore   || 0) * (DEMOLISH_SALVAGE_RATIO || 0.35))
    };

    const queueItem = {
      queueItemId: 'demolish_' + city.id + '_p' + plot.plotIndex + '_' + Date.now(),
      cityId: city.id,
      plotIndex: plot.plotIndex,
      buildingId: bId,
      buildingName: bDef ? bDef.name : bId,
      type: 'demolish',
      durationMs: demolishDur,
      salvage: salvage,
      status: 'queued',
      jobId: null,
      startSimTimeMs: null,
      dueSimTimeMs: null
    };

    plot.demolishing = true;
    city.buildQueue.push(queueItem);
    activateNextCityBuildQueueItem(city, state, scheduler);

    return accept({ queueItem: queueItem, salvage: salvage });
  }

  // ---------------------------------------------------------------------------
  // 9. RECRUIT HERO (Real-Time 60s Training in Recruitment Queue)
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.RECRUIT_HERO) {
    const city = getPrimaryCity(state);
    const classId = payload.classId || 'adventurer';
    const eligibility = evaluateHeroRecruitmentEligibility(city, world, classId);
    if (!eligibility.eligible) {
      return reject(eligibility.reason);
    }

    if (!Array.isArray(city.recruitmentQueue)) {
      city.recruitmentQueue = [];
    }

    const classDef = eligibility.classDef;
    city.stockpile.gold -= classDef.costGold;
    city.stockpile.food -= classDef.costFood;

    const heroIndex = (world.heroes || []).length + city.recruitmentQueue.length + 1;
    const heroName = String(payload.heroName || (classDef.name + ' #' + heroIndex)).trim();
    const recruitDurMs = classDef.durationMs || BASE_HERO_RECRUIT_DURATION_MS;
    const queueItem = {
      queueItemId: 'rec_' + city.id + '_' + Date.now() + '_' + Math.floor(Math.random() * 1000),
      cityId: city.id,
      classId: classDef.classId,
      className: classDef.name,
      heroName: heroName,
      costGold: classDef.costGold,
      costFood: classDef.costFood,
      durationMs: recruitDurMs,
      status: 'queued',
      jobId: null,
      startSimTimeMs: null,
      dueSimTimeMs: null
    };

    city.recruitmentQueue.push(queueItem);
    activateNextCityRecruitQueueItem(city, state, scheduler);

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.HERO_RECRUIT_STARTED, {
        cityId: city.id,
        classId: classDef.classId,
        heroName: heroName,
        durationMs: recruitDurMs
      }, simTimeMs);
    }

    return accept({
      queueItem: queueItem,
      stockpile: city.stockpile
    });
  }

  // ---------------------------------------------------------------------------
  // 9B. CANCEL HERO RECRUITMENT (Prorated Refund of Gold & Food)
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.CANCEL_RECRUITMENT) {
    const city = (payload.cityId && world.cities[payload.cityId]) || getPrimaryCity(state);
    if (!city || !Array.isArray(city.recruitmentQueue) || city.recruitmentQueue.length === 0) {
      return reject('No queued hero training to cancel');
    }

    const qId = payload.queueItemId;
    const idx = qId
      ? city.recruitmentQueue.findIndex(function(q) { return q.queueItemId === qId; })
      : city.recruitmentQueue.length - 1;

    if (idx === -1) return reject('Recruitment item not found');
    const removed = city.recruitmentQueue.splice(idx, 1)[0];

    let refundRatio = 1.0;
    if (removed.status === 'training') {
      if (removed.jobId && scheduler) {
        scheduler.cancelJob(removed.jobId);
      }
      const elapsed = Math.max(0, simTimeMs - (removed.startSimTimeMs || simTimeMs));
      const totalDur = Math.max(1, removed.durationMs || BASE_HERO_RECRUIT_DURATION_MS);
      refundRatio = Math.max(0, Math.min(1, 1.0 - (elapsed / totalDur)));
    }

    const refGold = Math.floor((removed.costGold || 0) * refundRatio);
    const refFood = Math.floor((removed.costFood || 0) * refundRatio);
    city.stockpile.gold = (city.stockpile.gold || 0) + refGold;
    city.stockpile.food = (city.stockpile.food || 0) + refFood;

    // Start next recruitment item if front was cancelled
    activateNextCityRecruitQueueItem(city, state, scheduler);

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.HERO_RECRUIT_CANCEL, {
        cityId: city.id,
        classId: removed.classId,
        heroName: removed.heroName,
        refundGold: refGold,
        refundFood: refFood,
        refundRatio: refundRatio
      }, simTimeMs);
    }

    return accept({
      cancelled: removed,
      refundGold: refGold,
      refundFood: refFood,
      stockpile: city.stockpile
    });
  }

  // ---------------------------------------------------------------------------
  // 9B1. MILITARY TROOP RECRUITMENT, UPGRADING, CANCELLATION & DISBANDING (Task 05A / C2 / C3)
  // One shared city military queue (city.troopTrainingQueue) for both recruit & upgrade jobs.
  // ---------------------------------------------------------------------------
  function deductBarracksTroopsAtLevel(ownerId, cityId, troopDefId, level, qty) {
    if (!Array.isArray(world.troopGroups)) return false;
    let remaining = qty;
    for (let i = world.troopGroups.length - 1; i >= 0 && remaining > 0; i--) {
      const g = world.troopGroups[i];
      if (!g || g.ownerPlayerId !== ownerId || g.locationType !== TROOP_LOCATION_TYPES.BARRACKS) continue;
      if (g.locationId !== cityId || g.troopDefId !== troopDefId || (g.level || 1) !== level) continue;
      const take = Math.min(g.count || 0, remaining);
      if (take > 0) {
        g.count -= take;
        remaining -= take;
        if (g.count <= 0) {
          world.troopGroups.splice(i, 1);
        }
      }
    }
    return remaining === 0;
  }

  if (cmdType === COMMAND_TYPES.TRAIN_TROOPS) {
    const city = (payload.cityId && world.cities[payload.cityId]) || getPrimaryCity(state);
    if (!city) {
      return reject('You must found a Bastion City before training military troops');
    }
    if (city.ownerPlayerId && city.ownerPlayerId !== getCanonicalPlayerId(state)) {
      return reject('You do not control this city');
    }

    const troopDef = getTroopDefinition(payload.troopDefId);
    if (!troopDef) {
      return reject('Unknown troop type: ' + payload.troopDefId);
    }

    const rawQty = payload.quantity !== undefined ? Number(payload.quantity) : 1;
    if (!isFinite(rawQty) || rawQty < 1 || Math.floor(rawQty) !== rawQty) {
      return reject('Training quantity must be a positive whole number');
    }
    const quantity = Math.floor(rawQty);

    const missingPrereqs = getMissingTroopPrerequisites(city, troopDef);
    if (missingPrereqs.length > 0) {
      const reqText = missingPrereqs.map(function(m) { return m.buildingName + ' Lv ' + m.requiredLevel; }).join(', ');
      return reject('Requires ' + reqText + ' to recruit ' + troopDef.name);
    }

    const maxUnlockedLevel = getTroopMaxUnlockedLevel(city, troopDef);
    const rawLevel = (payload.level !== undefined && payload.level !== null) ? Number(payload.level) : maxUnlockedLevel;
    if (!isFinite(rawLevel) || Math.floor(rawLevel) !== rawLevel || rawLevel < 1 || rawLevel > maxUnlockedLevel) {
      return reject(troopDef.name + ' Lv ' + rawLevel + ' is not unlocked (Max unlocked: Lv ' + maxUnlockedLevel + ')');
    }
    const targetLevel = Math.floor(rawLevel);

    if (!Array.isArray(city.troopTrainingQueue)) {
      city.troopTrainingQueue = [];
    }
    const maxSlots = city.maxTroopQueueSlots || BASE_TROOP_QUEUE_LIMIT || 3;
    if (city.troopTrainingQueue.length >= maxSlots) {
      return reject('Barracks military queue is full (' + city.troopTrainingQueue.length + '/' + maxSlots + ')');
    }

    const usage = getCityTroopCapacityUsage(world, city);
    const neededCap = quantity * (troopDef.capacityWeight || 1);
    if (usage.totalUsed + neededCap > usage.maxCapacity) {
      return reject('Insufficient Barracks troop capacity (' + usage.totalUsed + '/' + usage.maxCapacity + ', need +' + neededCap + ')');
    }

    const unitCostMap = computeTroopCostForLevel(troopDef, targetLevel);
    const costKeys = Object.keys(unitCostMap);
    for (let ck = 0; ck < costKeys.length; ck++) {
      const resKey = costKeys[ck];
      const need = (unitCostMap[resKey] || 0) * quantity;
      if (need > 0 && (city.stockpile[resKey] || 0) < need) {
        return reject('Insufficient ' + resKey + ' to recruit ' + quantity + '× ' + troopDef.name + ' Lv ' + targetLevel + ' (Need ' + need + ')');
      }
    }

    const costPerUnit = {};
    for (let ck = 0; ck < costKeys.length; ck++) {
      const resKey = costKeys[ck];
      const unitAmt = unitCostMap[resKey] || 0;
      if (unitAmt > 0) {
        costPerUnit[resKey] = unitAmt;
        city.stockpile[resKey] = (city.stockpile[resKey] || 0) - (unitAmt * quantity);
      }
    }

    const durPerUnit = computeTroopTrainingDurationMs(city, troopDef, targetLevel);
    const queueItem = {
      queueItemId: 'ttrain_' + city.id + '_' + troopDef.id + '_lv' + targetLevel + '_' + simTimeMs + '_' + Math.floor(Math.random() * 10000),
      cityId: city.id,
      jobKind: 'recruit',
      troopDefId: troopDef.id,
      troopName: troopDef.name,
      level: targetLevel,
      quantity: quantity,
      completedCount: 0,
      costPerUnit: costPerUnit,
      durationMsPerUnit: durPerUnit,
      status: 'queued',
      jobId: null,
      startSimTimeMs: null,
      dueSimTimeMs: null
    };

    city.troopTrainingQueue.push(queueItem);
    activateNextCityTroopQueueItem(city, state, scheduler);

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.TROOP_TRAINING_STARTED, {
        cityId: city.id,
        queueItemId: queueItem.queueItemId,
        troopDefId: troopDef.id,
        troopName: troopDef.name,
        level: targetLevel,
        quantity: quantity,
        durationMsPerUnit: durPerUnit
      }, simTimeMs);
    }

    evaluateTaskDAG(state, eventStream);

    return accept({
      queueItem: queueItem,
      stockpile: city.stockpile
    });
  }

  if (cmdType === COMMAND_TYPES.UPGRADE_TROOPS) {
    const city = (payload.cityId && world.cities[payload.cityId]) || getPrimaryCity(state);
    if (!city) {
      return reject('You must found a Bastion City before upgrading military troops');
    }
    const ownerId = getCanonicalPlayerId(state);
    if (city.ownerPlayerId && city.ownerPlayerId !== ownerId) {
      return reject('You do not control this city');
    }

    const troopDef = getTroopDefinition(payload.troopDefId);
    if (!troopDef) {
      return reject('Unknown troop type: ' + payload.troopDefId);
    }

    const missingPrereqs = getMissingTroopPrerequisites(city, troopDef);
    if (missingPrereqs.length > 0) {
      const reqText = missingPrereqs.map(function(m) { return m.buildingName + ' Lv ' + m.requiredLevel; }).join(', ');
      return reject('Requires ' + reqText + ' to upgrade ' + troopDef.name);
    }

    const maxUnlockedLevel = getTroopMaxUnlockedLevel(city, troopDef);
    const fromLevel = Math.floor(Number(payload.fromLevel || 0));
    const toLevel = (payload.toLevel !== undefined && payload.toLevel !== null)
      ? Math.floor(Number(payload.toLevel))
      : maxUnlockedLevel;
    if (!isFinite(fromLevel) || !isFinite(toLevel) || fromLevel < 1 || toLevel <= fromLevel || toLevel > maxUnlockedLevel) {
      return reject('Invalid upgrade levels (Lv ' + fromLevel + ' -> Lv ' + toLevel + '; max unlocked: Lv ' + maxUnlockedLevel + ')');
    }

    const rawQty = payload.quantity !== undefined ? Number(payload.quantity) : 1;
    if (!isFinite(rawQty) || rawQty < 1 || Math.floor(rawQty) !== rawQty) {
      return reject('Upgrade quantity must be a positive whole number');
    }
    const quantity = Math.floor(rawQty);

    if (!Array.isArray(city.troopTrainingQueue)) {
      city.troopTrainingQueue = [];
    }
    const maxSlots = city.maxTroopQueueSlots || BASE_TROOP_QUEUE_LIMIT || 3;
    if (city.troopTrainingQueue.length >= maxSlots) {
      return reject('Barracks military queue is full (' + city.troopTrainingQueue.length + '/' + maxSlots + ')');
    }

    const availableAtLevel = getCityTroopCountAtLevel(world, city.id, troopDef.id, fromLevel);
    if (availableAtLevel < quantity) {
      return reject('Only ' + availableAtLevel + '× ' + troopDef.name + ' Lv ' + fromLevel + ' available in Barracks');
    }

    const upgCostMap = computeTroopUpgradeCost(troopDef, fromLevel, toLevel);
    const costKeys = Object.keys(upgCostMap);
    for (let ck = 0; ck < costKeys.length; ck++) {
      const resKey = costKeys[ck];
      const need = (upgCostMap[resKey] || 0) * quantity;
      if (need > 0 && (city.stockpile[resKey] || 0) < need) {
        return reject('Insufficient ' + resKey + ' to upgrade ' + quantity + '× ' + troopDef.name + ' (Need ' + need + ')');
      }
    }

    // Atomic reservation: deduct source troops & upgrade resources together
    const deducted = deductBarracksTroopsAtLevel(ownerId, city.id, troopDef.id, fromLevel, quantity);
    if (!deducted) {
      return reject('Unable to reserve source troops for upgrade');
    }

    const costPerUnit = {};
    for (let ck = 0; ck < costKeys.length; ck++) {
      const resKey = costKeys[ck];
      const unitAmt = upgCostMap[resKey] || 0;
      if (unitAmt > 0) {
        costPerUnit[resKey] = unitAmt;
        city.stockpile[resKey] = (city.stockpile[resKey] || 0) - (unitAmt * quantity);
      }
    }

    const durPerUnit = computeTroopUpgradeDurationMs(city, troopDef, fromLevel, toLevel);
    const queueItem = {
      queueItemId: 'tupg_' + city.id + '_' + troopDef.id + '_' + fromLevel + 'to' + toLevel + '_' + simTimeMs + '_' + Math.floor(Math.random() * 10000),
      cityId: city.id,
      jobKind: 'upgrade',
      troopDefId: troopDef.id,
      troopName: troopDef.name,
      fromLevel: fromLevel,
      toLevel: toLevel,
      quantity: quantity,
      completedCount: 0,
      costPerUnit: costPerUnit,
      durationMsPerUnit: durPerUnit,
      status: 'queued',
      jobId: null,
      startSimTimeMs: null,
      dueSimTimeMs: null
    };

    city.troopTrainingQueue.push(queueItem);
    activateNextCityTroopQueueItem(city, state, scheduler);

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.TROOP_UPGRADE_STARTED, {
        cityId: city.id,
        queueItemId: queueItem.queueItemId,
        troopDefId: troopDef.id,
        troopName: troopDef.name,
        fromLevel: fromLevel,
        toLevel: toLevel,
        quantity: quantity,
        durationMsPerUnit: durPerUnit
      }, simTimeMs);
    }

    return accept({
      queueItem: queueItem,
      stockpile: city.stockpile
    });
  }

  if (cmdType === COMMAND_TYPES.CANCEL_TROOP_TRAINING || cmdType === COMMAND_TYPES.CANCEL_TROOP_UPGRADE) {
    const city = (payload.cityId && world.cities[payload.cityId]) || getPrimaryCity(state);
    if (!city || !Array.isArray(city.troopTrainingQueue) || city.troopTrainingQueue.length === 0) {
      return reject('No queued military job to cancel');
    }

    const qId = payload.queueItemId;
    const idx = qId
      ? city.troopTrainingQueue.findIndex(function(q) { return q && q.queueItemId === qId; })
      : city.troopTrainingQueue.length - 1;

    if (idx === -1) return reject('Military queue item not found');
    const removed = city.troopTrainingQueue.splice(idx, 1)[0];
    const isUpgrade = removed.jobKind === 'upgrade';
    const remainingTotal = Math.max(0, (removed.quantity || 0) - (removed.completedCount || 0));

    let unstartedUnits = remainingTotal;
    let activeRefundRatio = 0;
    const isActive = (removed.status === 'training' || removed.status === 'upgrading');
    if (isActive && remainingTotal > 0) {
      if (removed.jobId && scheduler) {
        scheduler.cancelJob(removed.jobId);
      }
      unstartedUnits = Math.max(0, remainingTotal - 1);
      const elapsed = Math.max(0, simTimeMs - (removed.startSimTimeMs || simTimeMs));
      const totalDur = Math.max(1, removed.durationMsPerUnit || 8000);
      activeRefundRatio = Math.max(0, Math.min(1, 1.0 - (elapsed / totalDur)));
    }

    // Conservation rule: if cancelling an upgrade, return remaining un-upgraded troops to fromLevel
    if (isUpgrade && remainingTotal > 0) {
      addBarracksTroopsAtLevel(world, getCanonicalPlayerId(state), city.id, removed.troopDefId, removed.fromLevel || 1, remainingTotal, simTimeMs);
    }

    const refundFactor = unstartedUnits + activeRefundRatio;
    const refunded = {};
    const costKeys = Object.keys(removed.costPerUnit || {});
    for (let ck = 0; ck < costKeys.length; ck++) {
      const resKey = costKeys[ck];
      const refAmt = Math.floor((removed.costPerUnit[resKey] || 0) * refundFactor);
      if (refAmt > 0) {
        city.stockpile[resKey] = (city.stockpile[resKey] || 0) + refAmt;
        refunded[resKey] = refAmt;
      }
    }

    activateNextCityTroopQueueItem(city, state, scheduler);

    if (eventStream) {
      eventStream.publish(isUpgrade ? STREAM_TOPICS.TROOP_UPGRADE_CANCELLED : STREAM_TOPICS.TROOP_TRAINING_CANCELLED, {
        cityId: city.id,
        troopDefId: removed.troopDefId,
        troopName: removed.troopName,
        fromLevel: removed.fromLevel || null,
        toLevel: removed.toLevel || null,
        level: removed.level || null,
        completedCount: removed.completedCount || 0,
        cancelledCount: remainingTotal,
        refunded: refunded
      }, simTimeMs);
    }

    return accept({
      cancelled: removed,
      cancelledCount: remainingTotal,
      refunded: refunded,
      stockpile: city.stockpile
    });
  }

  if (cmdType === COMMAND_TYPES.DISBAND_TROOPS) {
    if (!Array.isArray(world.troopGroups)) {
      return reject('No Barracks troop groups exist');
    }
    const ownerId = getCanonicalPlayerId(state);

    // Support disbanding by (troopDefId, level, quantity) across multiple groups OR by explicit troopGroupId
    if (payload.troopDefId && payload.level !== undefined) {
      const city = (payload.cityId && world.cities[payload.cityId]) || getPrimaryCity(state);
      if (!city) return reject('City not found');
      const lvl = Math.floor(Number(payload.level || 1));
      const available = getCityTroopCountAtLevel(world, city.id, payload.troopDefId, lvl);
      if (available <= 0) return reject('No matching Barracks troops found at Lv ' + lvl);
      const reqQty = payload.quantity !== undefined ? Math.floor(Number(payload.quantity)) : available;
      if (isNaN(reqQty) || reqQty < 1 || reqQty > available) {
        return reject('Invalid disband quantity (must be between 1 and ' + available + ')');
      }
      deductBarracksTroopsAtLevel(ownerId, city.id, payload.troopDefId, lvl, reqQty);
      const remaining = getCityTroopCountAtLevel(world, city.id, payload.troopDefId, lvl);
      if (eventStream) {
        eventStream.publish(STREAM_TOPICS.TROOPS_DISBANDED, {
          troopDefId: payload.troopDefId,
          level: lvl,
          cityId: city.id,
          disbandedCount: reqQty,
          remainingCount: remaining
        }, simTimeMs);
      }
      return accept({
        troopDefId: payload.troopDefId,
        level: lvl,
        disbandedCount: reqQty,
        remainingCount: remaining
      });
    }

    const gIdx = world.troopGroups.findIndex(function(g) { return g && g.id === payload.troopGroupId; });
    if (gIdx === -1) return reject('Troop group not found');

    const group = world.troopGroups[gIdx];
    if (group.ownerPlayerId && group.ownerPlayerId !== ownerId) {
      return reject('You do not own this troop group');
    }
    if (group.locationType !== TROOP_LOCATION_TYPES.BARRACKS) {
      return reject('Only Barracks troops can be disbanded from the Barracks');
    }

    const reqQty = payload.quantity !== undefined ? Math.floor(Number(payload.quantity)) : group.count;
    if (isNaN(reqQty) || reqQty < 1 || reqQty > group.count) {
      return reject('Invalid disband quantity (must be between 1 and ' + group.count + ')');
    }

    group.count -= reqQty;
    const removedGroup = group.count <= 0;
    if (removedGroup) {
      world.troopGroups.splice(gIdx, 1);
    }

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.TROOPS_DISBANDED, {
        troopGroupId: group.id,
        troopDefId: group.troopDefId,
        level: group.level || 1,
        cityId: group.locationId,
        disbandedCount: reqQty,
        remainingCount: removedGroup ? 0 : group.count
      }, simTimeMs);
    }

    return accept({
      troopGroupId: group.id,
      troopDefId: group.troopDefId,
      level: group.level || 1,
      disbandedCount: reqQty,
      remainingCount: removedGroup ? 0 : group.count
    });
  }

  // ---------------------------------------------------------------------------
  // 9B1b. FIELD ARMY DEPLOYMENT, REDIRECTION & RETURN POLICY (Task 05B-1)
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.DEPLOY_ARMY) {
    const city = (payload.homeCityId && world.cities[payload.homeCityId]) || getPrimaryCity(state);
    if (!city) {
      return reject('You must found a Bastion City before deploying a Field Army');
    }
    const ownerId = getCanonicalPlayerId(state);
    if (city.ownerPlayerId && city.ownerPlayerId !== ownerId) {
      return reject('You do not control this city');
    }

    // Optional military target assignment (Task 05B-2)
    let militaryTarget = null;
    if (payload.targetId) {
      militaryTarget = getMilitaryTargetById(ow, payload.targetId);
      if (!militaryTarget) {
        return reject('Military target not found on Overworld');
      }
      const isTargetDiscovered = Boolean(
        militaryTarget.discovered ||
        (ow.explored && ow.explored[militaryTarget.y] && ow.explored[militaryTarget.y][militaryTarget.x])
      );
      if (!isTargetDiscovered) {
        return reject('Explore the Overworld to discover ' + militaryTarget.name + ' before deploying an army there');
      }
      if (militaryTarget.status === MILITARY_TARGET_STATUS.CLEARED) {
        return reject(militaryTarget.name + ' has already been cleared');
      }
    }

    const targetX = militaryTarget ? militaryTarget.x : Number(payload.targetX);
    const targetY = militaryTarget ? militaryTarget.y : Number(payload.targetY);
    if (!isFinite(targetX) || !isFinite(targetY) || Math.floor(targetX) !== targetX || Math.floor(targetY) !== targetY) {
      return reject('Invalid target coordinates for deployment');
    }
    if (!isInOverworldBounds(ow, targetX, targetY) || !isOverworldTilePassable(ow, targetX, targetY)) {
      return reject('Target hex (' + targetX + ', ' + targetY + ') is impassable or out of bounds');
    }
    if (targetX === city.x && targetY === city.y) {
      return reject('Select a destination outside the home city to deploy a Field Army');
    }

    const path = findOverworldPath(ow, city.x, city.y, targetX, targetY);
    if (!path || path.length === 0) {
      return reject('No passable hex route from ' + city.name + ' to (' + targetX + ', ' + targetY + ')');
    }

    const rawTroops = Array.isArray(payload.troops) ? payload.troops : [];
    if (rawTroops.length === 0) {
      return reject('Select at least one troop to deploy');
    }

    // Aggregate & validate all requested (troopDefId, level) quantities BEFORE mutating any state
    const aggregatedMap = {};
    const aggregatedList = [];
    let totalTroops = 0;
    for (let i = 0; i < rawTroops.length; i++) {
      const entry = rawTroops[i];
      if (!entry) continue;
      const td = getTroopDefinition(entry.troopDefId);
      if (!td) return reject('Unknown troop type in deployment: ' + entry.troopDefId);
      const lvl = Math.floor(Number(entry.level || 1));
      const qty = Number(entry.quantity);
      if (!isFinite(lvl) || lvl < 1 || !isFinite(qty) || qty < 1 || Math.floor(qty) !== qty) {
        return reject('Invalid troop level or quantity in deployment');
      }
      const key = td.id + ':' + lvl;
      if (!aggregatedMap[key]) {
        aggregatedMap[key] = { troopDefId: td.id, level: lvl, quantity: 0 };
        aggregatedList.push(aggregatedMap[key]);
      }
      aggregatedMap[key].quantity += Math.floor(qty);
      totalTroops += Math.floor(qty);
    }

    if (totalTroops <= 0) {
      return reject('Select at least one troop to deploy');
    }

    for (let i = 0; i < aggregatedList.length; i++) {
      const req = aggregatedList[i];
      const available = getCityTroopCountAtLevel(world, city.id, req.troopDefId, req.level);
      if (available < req.quantity) {
        return reject('Insufficient Barracks troops for ' + req.troopDefId + ' Lv ' + req.level + ' (need ' + req.quantity + ', have ' + available + ')');
      }
    }

    // Atomic transfer: deduct from Barracks & create Army-located troopGroups
    // Internal armyId is strictly monotonic & unique (never reused); displayNumber is the lowest
    // available positive integer among currently active deployed armies (Task 05B-1-C1).
    const existingArmies = (ow.units || []).filter(function(u) { return u && u.unitType === 'army'; }).length;
    const armySeq = existingArmies + 1;
    let armyId = 'army_' + armySeq + '_' + simTimeMs + '_' + Math.floor(Math.random() * 10000);
    let idSalt = 0;
    while ((ow.units || []).some(function(u) { return u && u.id === armyId; })) {
      idSalt++;
      armyId = 'army_' + armySeq + '_' + simTimeMs + '_' + Math.floor(Math.random() * 10000) + '_' + idSalt;
    }
    const displayNumber = allocateLowestArmyDisplayNumber(ow.units);
    if (!Array.isArray(world.troopGroups)) world.troopGroups = [];

    for (let i = 0; i < aggregatedList.length; i++) {
      const req = aggregatedList[i];
      deductBarracksTroopsAtLevel(ownerId, city.id, req.troopDefId, req.level, req.quantity);
      world.troopGroups.push({
        id: 'tg_' + armyId + '_' + req.troopDefId + '_lv' + req.level,
        ownerPlayerId: ownerId,
        troopDefId: req.troopDefId,
        count: req.quantity,
        level: req.level,
        xp: 0,
        condition: 100,
        locationType: TROOP_LOCATION_TYPES.ARMY,
        locationId: armyId,
        createdAtSimMs: simTimeMs
      });
    }

    const armyArch = UNIT_ARCHETYPES.army || { visionRadius: 4, maxHp: 100 };
    const stayDeployed = Boolean(payload.stayDeployed);
    const totalMs = path.reduce(function(sum, st) { return sum + (st.stepDurationMs || 3000); }, 0);
    const armyUnit = {
      id: armyId,
      ownerPlayerId: ownerId,
      unitType: 'army',
      displayNumber: displayNumber,
      name: 'Field Army #' + displayNumber,
      shortName: 'Army #' + displayNumber,
      homeCityId: city.id,
      x: city.x,
      y: city.y,
      hp: armyArch.maxHp || 100,
      maxHp: armyArch.maxHp || 100,
      visionRadius: armyArch.visionRadius || 4,
      canFoundCity: false,
      canEnterDungeon: false,
      alive: true,
      reintegrated: false,
      status: 'marching',
      stayDeployed: stayDeployed,
      objective: {
        id: 'obj_' + armyId + '_' + simTimeMs,
        type: militaryTarget ? ARMY_OBJECTIVE_TYPES.ENGAGE_TARGET : ARMY_OBJECTIVE_TYPES.PATROL_HEX,
        status: ARMY_OBJECTIVE_STATUS.TRAVELING,
        targetId: militaryTarget ? militaryTarget.id : null,
        targetName: militaryTarget ? militaryTarget.name : null,
        targetX: targetX,
        targetY: targetY,
        jobId: null,
        startSimTimeMs: simTimeMs,
        dueSimTimeMs: null
      },
      lastCombatResult: null,
      cargo: null,
      marchPlan: {
        intent: militaryTarget ? 'engage_target' : 'patrol_hex',
        targetId: militaryTarget ? militaryTarget.id : null,
        targetX: targetX,
        targetY: targetY,
        remainingPath: path,
        totalDurationMs: totalMs,
        activeJobId: null,
        stepStartSimTimeMs: simTimeMs,
        stepDueSimTimeMs: simTimeMs,
        fromX: city.x,
        fromY: city.y,
        toX: path[0].x,
        toY: path[0].y
      },
      createdAtSimMs: simTimeMs
    };

    if (!ow.units) ow.units = [];
    ow.units.push(armyUnit);
    ow.selectedUnitId = armyUnit.id;
    revealOverworldVision(ow, armyUnit.x, armyUnit.y, armyUnit.visionRadius, { simTimeMs: simTimeMs, eventStream: eventStream });
    scheduleNextMarchStep(armyUnit, state, scheduler);

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.ARMY_DEPLOYED, {
        armyId: armyUnit.id,
        displayNumber: armyUnit.displayNumber,
        armyName: armyUnit.shortName,
        homeCityId: city.id,
        homeCityName: city.name,
        targetId: militaryTarget ? militaryTarget.id : null,
        targetName: militaryTarget ? militaryTarget.name : null,
        objectiveType: armyUnit.objective.type,
        targetX: targetX,
        targetY: targetY,
        totalTroops: totalTroops,
        stayDeployed: stayDeployed
      }, simTimeMs);
    }

    return accept({
      armyId: armyUnit.id,
      displayNumber: armyUnit.displayNumber,
      army: armyUnit,
      targetId: militaryTarget ? militaryTarget.id : null,
      totalTroops: totalTroops,
      stepsCount: path.length
    });
  }

  if (cmdType === COMMAND_TYPES.REDIRECT_ARMY) {
    const ownerId = getCanonicalPlayerId(state);
    const army = (ow.units || []).find(function(u) {
      return u && u.alive && !u.reintegrated && u.unitType === 'army' && u.id === payload.armyId;
    });
    if (!army) return reject('Deployed Field Army not found');
    if (army.ownerPlayerId && army.ownerPlayerId !== ownerId) {
      return reject('You do not control this Field Army');
    }

    let militaryTarget = null;
    if (payload.targetId) {
      militaryTarget = getMilitaryTargetById(ow, payload.targetId);
      if (!militaryTarget) {
        return reject('Military target not found on Overworld');
      }
      const isTargetDiscovered = Boolean(
        militaryTarget.discovered ||
        (ow.explored && ow.explored[militaryTarget.y] && ow.explored[militaryTarget.y][militaryTarget.x])
      );
      if (!isTargetDiscovered) {
        return reject('Explore the Overworld to discover ' + militaryTarget.name + ' before assigning an army there');
      }
      if (militaryTarget.status === MILITARY_TARGET_STATUS.CLEARED) {
        return reject(militaryTarget.name + ' has already been cleared');
      }
    }

    const targetX = militaryTarget ? militaryTarget.x : Number(payload.targetX);
    const targetY = militaryTarget ? militaryTarget.y : Number(payload.targetY);
    if (!isFinite(targetX) || !isFinite(targetY) || Math.floor(targetX) !== targetX || Math.floor(targetY) !== targetY) {
      return reject('Invalid target coordinates for redirection');
    }
    if (!isInOverworldBounds(ow, targetX, targetY) || !isOverworldTilePassable(ow, targetX, targetY)) {
      return reject('Target hex (' + targetX + ', ' + targetY + ') is impassable or out of bounds');
    }

    const homeCity = (world.cities && army.homeCityId) ? world.cities[army.homeCityId] : null;
    if (!militaryTarget && homeCity && targetX === homeCity.x && targetY === homeCity.y) {
      const retRes = startArmyReturnHome(army, state, scheduler, simTimeMs, eventStream);
      if (!retRes || !retRes.ok) return reject((retRes && retRes.reason) || 'Unable to return home');
      return accept({ armyId: army.id, redirectedToReturnHome: true });
    }

    let path = [];
    if (army.x !== targetX || army.y !== targetY) {
      path = findOverworldPath(ow, army.x, army.y, targetX, targetY);
      if (!path || path.length === 0) {
        return reject('No passable hex route to (' + targetX + ', ' + targetY + ')');
      }
    }

    // Cancel active march or objective job and mark previous objective interrupted
    if (army.marchPlan && army.marchPlan.activeJobId && scheduler) {
      scheduler.cancelJob(army.marchPlan.activeJobId);
    }
    if (army.objective) {
      if (army.objective.jobId && scheduler) {
        scheduler.cancelJob(army.objective.jobId);
      }
      army.objective.status = ARMY_OBJECTIVE_STATUS.INTERRUPTED;
      army.objective.jobId = null;
    }

    if (typeof payload.stayDeployed === 'boolean') {
      army.stayDeployed = payload.stayDeployed;
    }

    army.objective = {
      id: 'obj_' + army.id + '_' + simTimeMs + '_' + Math.floor(Math.random() * 1000),
      type: militaryTarget ? ARMY_OBJECTIVE_TYPES.ENGAGE_TARGET : ARMY_OBJECTIVE_TYPES.PATROL_HEX,
      status: ARMY_OBJECTIVE_STATUS.ACCEPTED,
      targetId: militaryTarget ? militaryTarget.id : null,
      targetName: militaryTarget ? militaryTarget.name : null,
      targetX: targetX,
      targetY: targetY,
      jobId: null,
      startSimTimeMs: simTimeMs,
      dueSimTimeMs: null
    };

    if (path.length === 0) {
      army.marchPlan = null;
      handleArmyArrival(army, state, scheduler, simTimeMs, eventStream);
    } else {
      const totalMs = path.reduce(function(sum, st) { return sum + (st.stepDurationMs || 3000); }, 0);
      army.objective.status = ARMY_OBJECTIVE_STATUS.TRAVELING;
      army.marchPlan = {
        intent: militaryTarget ? 'engage_target' : 'patrol_hex',
        targetId: militaryTarget ? militaryTarget.id : null,
        targetX: targetX,
        targetY: targetY,
        remainingPath: path,
        totalDurationMs: totalMs,
        activeJobId: null,
        stepStartSimTimeMs: simTimeMs,
        stepDueSimTimeMs: simTimeMs,
        fromX: army.x,
        fromY: army.y,
        toX: path[0].x,
        toY: path[0].y
      };
      scheduleNextMarchStep(army, state, scheduler);
    }

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.ARMY_REDIRECTED, {
        armyId: army.id,
        armyName: army.shortName || army.name,
        targetId: militaryTarget ? militaryTarget.id : null,
        targetName: militaryTarget ? militaryTarget.name : null,
        objectiveType: army.objective.type,
        targetX: targetX,
        targetY: targetY,
        stayDeployed: Boolean(army.stayDeployed)
      }, simTimeMs);
    }

    return accept({
      armyId: army.id,
      targetId: militaryTarget ? militaryTarget.id : null,
      targetX: targetX,
      targetY: targetY,
      stayDeployed: Boolean(army.stayDeployed),
      stepsCount: path.length
    });
  }

  if (cmdType === COMMAND_TYPES.RETURN_ARMY_HOME) {
    const ownerId = getCanonicalPlayerId(state);
    const army = (ow.units || []).find(function(u) {
      return u && u.alive && !u.reintegrated && u.unitType === 'army' && u.id === payload.armyId;
    });
    if (!army) return reject('Deployed Field Army not found');
    if (army.ownerPlayerId && army.ownerPlayerId !== ownerId) {
      return reject('You do not control this Field Army');
    }
    const retRes = startArmyReturnHome(army, state, scheduler, simTimeMs, eventStream);
    if (!retRes || !retRes.ok) {
      return reject((retRes && retRes.reason) || 'Unable to begin return home');
    }
    return accept({ armyId: army.id, homeCityId: army.homeCityId, stepsCount: retRes.stepsCount || 0 });
  }

  if (cmdType === COMMAND_TYPES.SET_ARMY_RETURN_POLICY) {
    const ownerId = getCanonicalPlayerId(state);
    const army = (ow.units || []).find(function(u) {
      return u && u.alive && !u.reintegrated && u.unitType === 'army' && u.id === payload.armyId;
    });
    if (!army) return reject('Deployed Field Army not found');
    if (army.ownerPlayerId && army.ownerPlayerId !== ownerId) {
      return reject('You do not control this Field Army');
    }
    if (typeof payload.stayDeployed !== 'boolean') {
      return reject('stayDeployed must be a boolean');
    }
    army.stayDeployed = payload.stayDeployed;
    return accept({ armyId: army.id, stayDeployed: army.stayDeployed });
  }

  // ---------------------------------------------------------------------------
  // 9B2. EQUIP / UNEQUIP HERO EQUIPMENT (Shared Character Sheet Operations)
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.EQUIP_HERO_ITEM) {
    const hero = (world.heroes || []).find(function(h) { return h.id === payload.heroId; });
    if (!hero) return reject('Hero not found');
    if (!Array.isArray(hero.bagGear)) hero.bagGear = [];
    if (!hero.equipment) hero.equipment = { weapon: null, armor: null, helm: null, boots: null, accessory: null, pickaxe: null };

    const itemIdx = hero.bagGear.findIndex(function(it) { return it.uid === payload.itemUid; });
    if (itemIdx === -1) return reject('Item not found in hero pack');
    const item = normalizeEquipmentItem(hero.bagGear.splice(itemIdx, 1)[0]);
    const slot = item.slot;
    if (!slot || !(slot in hero.equipment)) {
      hero.bagGear.push(item);
      return reject('Unsupported equipment slot: ' + slot);
    }

    const prev = hero.equipment[slot];
    if (prev) {
      hero.bagGear.push(prev);
    }
    hero.equipment[slot] = item;
    refreshHeroDerivedStats(hero);
    return accept({ heroId: hero.id, slot: slot, equipped: item, swappedOut: prev || null });
  }

  if (cmdType === COMMAND_TYPES.UNEQUIP_HERO_ITEM) {
    const hero = (world.heroes || []).find(function(h) { return h.id === payload.heroId; });
    if (!hero) return reject('Hero not found');
    const slot = payload.slot;
    if (slot === 'pickaxe') return reject('Pickaxe cannot be unequipped directly');
    if (!hero.equipment || !hero.equipment[slot]) return reject('No item equipped in ' + slot);
    if (!Array.isArray(hero.bagGear)) hero.bagGear = [];

    const removed = hero.equipment[slot];
    hero.equipment[slot] = null;
    hero.bagGear.push(removed);
    refreshHeroDerivedStats(hero);
    return accept({ heroId: hero.id, slot: slot, unequipped: removed });
  }

  if (cmdType === COMMAND_TYPES.AUTO_EQUIP_HERO) {
    const hero = (world.heroes || []).find(function(h) { return h.id === payload.heroId; });
    if (!hero) return reject('Hero not found');
    if (!Array.isArray(hero.bagGear)) hero.bagGear = [];
    if (!hero.equipment) hero.equipment = { weapon: null, armor: null, helm: null, boots: null, accessory: null, pickaxe: null };

    function scoreGear(it) {
      if (!it) return -1;
      normalizeEquipmentItem(it);
      return computeClassItemPreferenceScore(it, hero.classId);
    }

    const slots = ['weapon', 'armor', 'helm', 'boots', 'accessory', 'pickaxe'];
    let equippedCount = 0;
    for (let s = 0; s < slots.length; s++) {
      const sl = slots[s];
      const candidates = hero.bagGear.filter(function(g) { return g && g.slot === sl; });
      if (candidates.length === 0) continue;
      candidates.sort(function(a, b) { return scoreGear(b) - scoreGear(a); });
      const best = candidates[0];
      const cur = hero.equipment[sl];
      if (scoreGear(best) > scoreGear(cur)) {
        const idx = hero.bagGear.indexOf(best);
        if (idx !== -1) hero.bagGear.splice(idx, 1);
        hero.equipment[sl] = best;
        if (cur) hero.bagGear.push(cur);
        equippedCount++;
      }
    }
    refreshHeroDerivedStats(hero);
    return accept({ heroId: hero.id, equippedCount: equippedCount });
  }

  // ---------------------------------------------------------------------------
  // 9B3. HERO ROSTER MANAGEMENT (Dismiss Hero, Overall Leader, Garrison Party)
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.DISMISS_HERO) {
    const heroIdx = (world.heroes || []).findIndex(function(h) { return h.id === payload.heroId; });
    if (heroIdx === -1) return reject('Hero not found in roster');
    const hero = world.heroes[heroIdx];
    const city = getPrimaryCity(state);

    // Safely deposit all hero equipment & bag gear into City Vault Storage!
    if (city) {
      if (!city.storage || !Array.isArray(city.storage.items)) {
        city.storage = createInventoryContainer('city_storage_' + city.id, city.name + ' Vault Storage', CITY_STORAGE_BASE_CAPACITY || 200);
      }
      if (hero.equipment) {
        const eqKeys = Object.keys(hero.equipment);
        for (let i = 0; i < eqKeys.length; i++) {
          const it = hero.equipment[eqKeys[i]];
          if (it) city.storage.items.push(it);
        }
      }
      if (Array.isArray(hero.bagGear)) {
        for (let i = 0; i < hero.bagGear.length; i++) {
          if (hero.bagGear[i]) city.storage.items.push(hero.bagGear[i]);
        }
      }
    }

    world.heroes.splice(heroIdx, 1);

    // Remove Overworld unit led by this dismissed hero and reassign selection safely (HR-14 Issue A)
    if (ow && Array.isArray(ow.units)) {
      let dismissedSelected = false;
      const keptUnits = [];
      for (let u = 0; u < ow.units.length; u++) {
        const unit = ow.units[u];
        if (unit && unit.leaderHeroId === hero.id) {
          if (unit.marchPlan && unit.marchPlan.activeJobId && scheduler) {
            scheduler.cancelJob(unit.marchPlan.activeJobId);
          }
          if (ow.selectedUnitId === unit.id) {
            dismissedSelected = true;
          }
          continue;
        }
        keptUnits.push(unit);
      }
      ow.units = keptUnits;
      if (dismissedSelected) {
        const nextAlive = ow.units.find(function(u) { return u && u.alive; });
        ow.selectedUnitId = nextAlive ? nextAlive.id : null;
      }
    }

    // Remove from any party
    if (Array.isArray(world.parties)) {
      world.parties = world.parties.filter(function(pt) {
        if (Array.isArray(pt.memberHeroIds)) {
          pt.memberHeroIds = pt.memberHeroIds.filter(function(mid) { return mid !== hero.id; });
        }
        if (Array.isArray(pt.memberIds)) {
          pt.memberIds = pt.memberIds.filter(function(mid) { return mid !== hero.id; });
        }
        return pt.leaderHeroId !== hero.id;
      });
    }

    // Reassign Overall Leader if the dismissed hero was leader
    if (world.roster && world.roster.overallLeaderHeroId === hero.id) {
      world.roster.overallLeaderHeroId = world.heroes.length > 0 ? world.heroes[0].id : null;
    }

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.HERO_DISMISSED, {
        heroId: hero.id,
        heroName: hero.name
      }, simTimeMs);
    }
    return accept({ dismissedHeroId: hero.id, remainingHeroes: world.heroes.length });
  }

  if (cmdType === COMMAND_TYPES.SET_OVERALL_LEADER) {
    const hero = (world.heroes || []).find(function(h) { return h.id === payload.heroId; });
    if (!hero) return reject('Hero not found in roster');
    if (!world.roster) world.roster = { maxHeroes: BASE_MAX_HERO_ROSTER || 3, overallLeaderHeroId: null };
    world.roster.overallLeaderHeroId = hero.id;
    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.LEADER_CHANGED, {
        heroId: hero.id,
        heroName: hero.name
      }, simTimeMs);
    }
    return accept({ overallLeaderHeroId: hero.id });
  }

  if (cmdType === COMMAND_TYPES.ASSIGN_HERO_TO_PARTY) {
    const city = getPrimaryCity(state);
    if (!city) return reject('Requires an established City');
    const maxSize = computeMaxPartySize(city);
    const party = (world.parties || []).find(function(pt) { return pt.id === payload.partyId; });
    if (!party) return reject('Party not found');
    const hero = (world.heroes || []).find(function(h) { return h.id === payload.heroId; });
    if (!hero) return reject('Hero not found');
    if (!Array.isArray(party.memberIds)) party.memberIds = [];
    if (party.memberIds.indexOf(hero.id) !== -1) return reject('Hero is already in this party');
    if (party.memberIds.length >= maxSize) {
      return reject('Party is at maximum capacity (' + maxSize + '). Build or upgrade the City Garrison to add more Heroes to a Party.');
    }
    party.memberIds.push(hero.id);
    return accept({ partyId: party.id, memberIds: party.memberIds.slice(), maxPartySize: maxSize });
  }

  // ---------------------------------------------------------------------------
  // 9B4. CITY VAULT STORAGE CONTAINER (Deposit, Withdraw, Dump Bag — ADR-0012)
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.DEPOSIT_TO_CITY_STORAGE) {
    const city = getPrimaryCity(state);
    if (!city) return reject('No City founded');
    if (!city.storage || !Array.isArray(city.storage.items)) {
      city.storage = createInventoryContainer('city_storage_' + city.id, city.name + ' Vault Storage', CITY_STORAGE_BASE_CAPACITY || 200);
    }
    const hero = (world.heroes || []).find(function(h) { return h.id === payload.heroId; });
    if (!hero || !Array.isArray(hero.bagGear)) return reject('Hero not found');
    if (city.storage.items.length >= (city.storage.capacity || 200)) {
      return reject('City Vault Storage is full');
    }
    const idx = hero.bagGear.findIndex(function(it) { return it.uid === payload.itemUid; });
    if (idx === -1) return reject('Item not found in hero pack');
    const item = hero.bagGear.splice(idx, 1)[0];
    city.storage.items.push(item);
    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.STORAGE_UPDATED, { cityId: city.id, action: 'deposit', itemName: item.name }, simTimeMs);
    }
    return accept({ item: item, storageCount: city.storage.items.length });
  }

  if (cmdType === COMMAND_TYPES.WITHDRAW_FROM_CITY_STORAGE) {
    const city = getPrimaryCity(state);
    if (!city || !city.storage || !Array.isArray(city.storage.items)) return reject('City Vault Storage unavailable');
    const hero = (world.heroes || []).find(function(h) { return h.id === payload.heroId; });
    if (!hero) return reject('Hero not found');
    if (!Array.isArray(hero.bagGear)) hero.bagGear = [];
    const idx = city.storage.items.findIndex(function(it) { return it.uid === payload.itemUid; });
    if (idx === -1) return reject('Item not found in City Vault Storage');
    const item = city.storage.items.splice(idx, 1)[0];
    hero.bagGear.push(item);
    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.STORAGE_UPDATED, { cityId: city.id, action: 'withdraw', itemName: item.name }, simTimeMs);
    }
    return accept({ item: item, storageCount: city.storage.items.length });
  }

  if (cmdType === COMMAND_TYPES.DUMP_HERO_BAG_TO_CITY) {
    const city = getPrimaryCity(state);
    if (!city) return reject('No City founded');
    if (!city.storage || !Array.isArray(city.storage.items)) {
      city.storage = createInventoryContainer('city_storage_' + city.id, city.name + ' Vault Storage', CITY_STORAGE_BASE_CAPACITY || 200);
    }
    const hero = (world.heroes || []).find(function(h) { return h.id === payload.heroId; });
    if (!hero || !Array.isArray(hero.bagGear) || hero.bagGear.length === 0) {
      return reject('Hero pack is already empty');
    }
    const cap = city.storage.capacity || 200;
    let movedCount = 0;
    while (hero.bagGear.length > 0 && city.storage.items.length < cap) {
      city.storage.items.push(hero.bagGear.shift());
      movedCount++;
    }
    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.STORAGE_UPDATED, { cityId: city.id, action: 'dump', count: movedCount }, simTimeMs);
    }
    return accept({ movedCount: movedCount, storageCount: city.storage.items.length });
  }

  // ---------------------------------------------------------------------------
  // 9B5. TIER 2 CITY INDUSTRY (Smeltery Ingots & Apothecary Provisions — Inc 9.6)
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.SMELT_INGOTS) {
    const city = getPrimaryCity(state);
    if (!city) return reject('No City founded');
    const smelteryLvl = (city.buildings && city.buildings.smeltery) || 0;
    if (smelteryLvl < 1) return reject('Construct a Dwarven Smeltery before smelting ingots');

    const batches = Math.max(1, Math.min(10, Math.round(Number(payload.batches) || 1)));
    const oreCost = 5 * batches;
    const woodCost = 5 * batches;
    const yieldIngots = 2 * batches;

    if ((city.stockpile.ore || 0) < oreCost || (city.stockpile.wood || 0) < woodCost) {
      return reject('Insufficient materials (Need ' + oreCost + ' Ore and ' + woodCost + ' Wood)');
    }
    city.stockpile.ore -= oreCost;
    city.stockpile.wood -= woodCost;
    city.stockpile.ingots = (city.stockpile.ingots || 0) + yieldIngots;

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.CRAFTING_COMPLETED, {
        cityId: city.id,
        facility: 'smeltery',
        itemName: 'Forged Ingots',
        qty: yieldIngots
      }, simTimeMs);
    }
    return accept({ ingotsAdded: yieldIngots, totalIngots: city.stockpile.ingots });
  }

  if (cmdType === COMMAND_TYPES.BREW_PROVISION) {
    const city = getPrimaryCity(state);
    if (!city) return reject('No City founded');
    const apothLvl = (city.buildings && city.buildings.apothecary) || 0;
    if (apothLvl < 1) return reject('Construct an Alchemist Apothecary before brewing provisions');
    if (!city.provisions) city.provisions = { potions: 0, recalls: 0 };

    const kind = payload.kind === 'recalls' ? 'recalls' : 'potions';
    if (kind === 'potions') {
      if ((city.stockpile.food || 0) < 10 || (city.stockpile.water || 0) < 10 || (city.stockpile.gold || 0) < 10) {
        return reject('Need 10 Food, 10 Water, and 10 Gold to brew a Healing Tonic');
      }
      city.stockpile.food -= 10;
      city.stockpile.water -= 10;
      city.stockpile.gold -= 10;
      city.provisions.potions = (city.provisions.potions || 0) + 1;
    } else {
      if ((city.stockpile.gold || 0) < 25 || (city.stockpile.ore || 0) < 5) {
        return reject('Need 25 Gold and 5 Ore to scribe an Astral Recall Scroll');
      }
      city.stockpile.gold -= 25;
      city.stockpile.ore -= 5;
      city.provisions.recalls = (city.provisions.recalls || 0) + 1;
    }

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.CRAFTING_COMPLETED, {
        cityId: city.id,
        facility: 'apothecary',
        itemName: kind === 'potions' ? 'Healing Tonic' : 'Astral Recall Scroll',
        qty: 1
      }, simTimeMs);
    }
    return accept({ kind: kind, provisions: Object.assign({}, city.provisions) });
  }

  // ---------------------------------------------------------------------------
  // 9B6. CITY BLACKSMITH (Star-Forge) & LAPIDARY WORKSHOP (Inc 9.7)
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.FORGE_EQUIPMENT) {
    const city = getPrimaryCity(state);
    if (!city) return reject('No City founded');
    const bsLvl = (city.buildings && city.buildings.blacksmith) || 0;
    if (bsLvl < 1) return reject('Construct a Blacksmith & Star-Forge before forging equipment');
    if (!city.storage || !Array.isArray(city.storage.items)) {
      city.storage = createInventoryContainer('city_storage_' + city.id, city.name + ' Vault Storage', CITY_STORAGE_BASE_CAPACITY || 200);
    }

    const slot = payload.slot || 'weapon';
    if (BLACKSMITH_FORGE_SLOTS.indexOf(slot) === -1) return reject('Invalid equipment slot: ' + slot);

    const recipe = getBlacksmithForgeRecipePreview(slot, bsLvl);
    if ((city.stockpile.ingots || 0) < recipe.ingotCost || (city.stockpile.gold || 0) < recipe.goldCost) {
      return reject('Need ' + recipe.ingotCost + ' Forged Ingots and ' + recipe.goldCost + ' Gold to forge ' + recipe.name);
    }
    city.stockpile.ingots -= recipe.ingotCost;
    city.stockpile.gold -= recipe.goldCost;

    const forged = normalizeEquipmentItem({
      uid: 'forge_' + slot + '_' + Date.now() + '_' + Math.floor(Math.random() * 10000),
      slot: recipe.slot,
      name: recipe.name,
      rarity: recipe.rarity,
      atk: recipe.atk,
      def: recipe.def,
      maxHp: recipe.maxHp,
      tier: recipe.tier,
      maxDur: recipe.maxDur,
      curDur: recipe.curDur,
      maxSockets: recipe.maxSockets,
      sockets: [],
      affixes: [],
      temperRank: 0,
      value: recipe.value
    });

    city.storage.items.push(forged);
    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.CRAFTING_COMPLETED, {
        cityId: city.id,
        facility: 'blacksmith',
        itemName: forged.name,
        qty: 1
      }, simTimeMs);
    }
    return accept({ item: forged, recipe: recipe, storageCount: city.storage.items.length });
  }

  if (cmdType === COMMAND_TYPES.TEMPER_EQUIPMENT) {
    const city = getPrimaryCity(state);
    if (!city) return reject('No City founded');
    const bsLvl = (city.buildings && city.buildings.blacksmith) || 0;
    if (bsLvl < 1) return reject('Requires Blacksmith & Star-Forge');

    const source = payload.source || 'vault';
    const itemUid = payload.itemUid;
    let item = null;
    let targetHero = null;

    if (source === 'vault') {
      if (!city.storage || !Array.isArray(city.storage.items)) return reject('City Vault Storage unavailable');
      item = city.storage.items.find(function(it) { return it && it.uid === itemUid; }) || null;
      if (!item) return reject('Item not found in City Vault Storage');
    } else if (source === 'carried' || source === 'equipped') {
      targetHero = (world.heroes || []).find(function(h) { return h && h.id === payload.heroId; }) || null;
      if (!targetHero) return reject('Hero not found');
      if (!isHeroPresentAtCity(world, city, targetHero)) {
        return reject(targetHero.name + ' must be at ' + city.name + ' to temper gear');
      }
      if (source === 'carried') {
        const bag = Array.isArray(targetHero.bagGear) ? targetHero.bagGear : [];
        item = bag.find(function(it) { return it && it.uid === itemUid; }) || null;
        if (!item) return reject('Item not found in ' + targetHero.name + '\'s carried pack');
      } else {
        const eq = targetHero.equipment || {};
        const eqSlots = ['weapon', 'armor', 'helm', 'boots', 'accessory', 'pickaxe'];
        for (let si = 0; si < eqSlots.length; si++) {
          const cand = eq[eqSlots[si]];
          if (cand && cand.uid === itemUid) {
            item = cand;
            break;
          }
        }
        if (!item) return reject('Item not found in ' + targetHero.name + '\'s equipped loadout');
      }
    } else {
      return reject('Invalid temper source: ' + source);
    }

    normalizeEquipmentItem(item);
    const preview = getBlacksmithTemperPreview(item);
    if (!preview.eligible) {
      return reject(preview.reason || 'Item cannot be tempered');
    }

    if ((city.stockpile.ingots || 0) < preview.ingotCost || (city.stockpile.gold || 0) < preview.goldCost) {
      return reject('Need ' + preview.ingotCost + ' Forged Ingots and ' + preview.goldCost + ' Gold to temper equipment');
    }
    city.stockpile.ingots -= preview.ingotCost;
    city.stockpile.gold -= preview.goldCost;

    item.temperRank = preview.nextRank;
    item[preview.statKey] = preview.nextStat;
    item.value = (item.value || 30) + preview.valueDelta;

    if (source === 'equipped' && targetHero) {
      refreshHeroDerivedStats(targetHero);
    }

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.CRAFTING_COMPLETED, {
        cityId: city.id,
        facility: 'blacksmith',
        itemName: item.name + ' (+' + item.temperRank + ')',
        qty: 1
      }, simTimeMs);
    }
    return accept({
      item: item,
      source: source,
      heroId: targetHero ? targetHero.id : null,
      temperRank: item.temperRank,
      statKey: preview.statKey,
      statLabel: preview.statLabel,
      prevStat: preview.currentStat,
      nextStat: preview.nextStat
    });
  }

  if (cmdType === COMMAND_TYPES.PUNCH_SOCKET) {
    const city = getPrimaryCity(state);
    if (!city || !city.storage || !Array.isArray(city.storage.items)) return reject('City Vault Storage unavailable');
    const lapLvl = (city.buildings && city.buildings.lapidary) || 0;
    if (lapLvl < 1) return reject('Construct a Lapidary Workshop before punching gem sockets');

    const item = city.storage.items.find(function(it) { return it.uid === payload.itemUid; });
    if (!item) return reject('Item not found in City Vault Storage');
    normalizeEquipmentItem(item);
    if (item.slot === 'pickaxe') return reject('Pickaxes cannot hold Gem Sockets');
    const curMaxSockets = item.maxSockets || 0;
    if (curMaxSockets >= 2) return reject(item.name + ' already has the maximum 2 Gem Sockets');

    if ((city.stockpile.ingots || 0) < 2 || (city.stockpile.gold || 0) < 35) {
      return reject('Need 2 Forged Ingots and 35 Gold to punch a Gem Socket');
    }
    city.stockpile.ingots -= 2;
    city.stockpile.gold -= 35;

    item.maxSockets = curMaxSockets + 1;
    if (!Array.isArray(item.sockets)) item.sockets = [];
    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.CRAFTING_COMPLETED, {
        cityId: city.id,
        facility: 'lapidary',
        itemName: 'Gem Socket on ' + item.name,
        qty: 1
      }, simTimeMs);
    }
    return accept({ item: item, maxSockets: item.maxSockets });
  }

  if (cmdType === COMMAND_TYPES.SOCKET_CITY_GEM) {
    const city = getPrimaryCity(state);
    if (!city || !city.storage || !Array.isArray(city.storage.items)) return reject('City Vault Storage unavailable');
    const lapLvl = (city.buildings && city.buildings.lapidary) || 0;
    if (lapLvl < 1) return reject('Construct a Lapidary Workshop before socketing Astral Gems');
    if (!city.gems) city.gems = { ruby: 0, emerald: 0, sapphire: 0, topaz: 0, void_diamond: 0 };

    const item = city.storage.items.find(function(it) { return it.uid === payload.itemUid; });
    if (!item) return reject('Item not found in City Vault Storage');
    normalizeEquipmentItem(item);
    if (item.slot === 'pickaxe') return reject('Pickaxes cannot hold Astral Gems');
    if (item.sockets.length >= (item.maxSockets || 0)) return reject('No open Gem Sockets on ' + item.name);

    const gemId = payload.gemId || 'ruby';
    const gDef = GEM_CATALOG[gemId];
    if (!gDef) return reject('Unknown gem type: ' + gemId);
    if ((city.gems[gemId] || 0) < 1) return reject('No ' + gDef.name + ' available in City Gems');

    city.gems[gemId] -= 1;
    item.sockets.push(gemId);

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.CRAFTING_COMPLETED, {
        cityId: city.id,
        facility: 'lapidary',
        itemName: gDef.name + ' into ' + item.name,
        qty: 1
      }, simTimeMs);
    }
    return accept({ item: item, gemId: gemId, remainingGems: city.gems[gemId] });
  }

  if (cmdType === COMMAND_TYPES.UNSOCKET_CITY_GEM) {
    const city = getPrimaryCity(state);
    if (!city || !city.storage || !Array.isArray(city.storage.items)) return reject('City Vault Storage unavailable');
    const lapLvl = (city.buildings && city.buildings.lapidary) || 0;
    if (lapLvl < 1) return reject('Construct a Lapidary Workshop before extracting gems');
    if (!city.gems) city.gems = { ruby: 0, emerald: 0, sapphire: 0, topaz: 0, void_diamond: 0 };

    const item = city.storage.items.find(function(it) { return it.uid === payload.itemUid; });
    if (!item) return reject('Item not found in City Vault Storage');
    normalizeEquipmentItem(item);
    if (!Array.isArray(item.sockets) || item.sockets.length === 0) return reject('No socketed gems to extract');
    if ((city.stockpile.gold || 0) < 20) return reject('Need 20 Gold to safely extract a gem');

    city.stockpile.gold -= 20;
    const removedGemId = item.sockets.pop();
    city.gems[removedGemId] = (city.gems[removedGemId] || 0) + 1;

    return accept({ item: item, extractedGemId: removedGemId, cityGemCount: city.gems[removedGemId] });
  }

  // ---------------------------------------------------------------------------
  // 9B7. ARCANE ACADEMY & MARKET TRADE POST (Inc 9.8 — Consumes Track F Engines)
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.MARKET_TRADE) {
    const city = getPrimaryCity(state);
    if (!city) return reject('No City founded');
    const mktLvl = (city.buildings && city.buildings.market_post) || 0;
    if (mktLvl < 1) return reject('Construct a Market & Trade Post before trading resources');

    const resId = String(payload.resourceId || '');
    const rate = MARKET_EXCHANGE_RATES[resId];
    if (!rate) return reject('Unsupported market resource: ' + resId);

    const side = payload.side === 'buy' ? 'buy' : 'sell';
    const prog = ensureProgressionState(world);
    const pid = getCanonicalPlayerId(state);

    if (side === 'sell') {
      const payRes = executeAtomicPayment(prog.currencyLedger, [
        { kind: 'stockpile', resourceId: resId, amount: rate.lotSize }
      ], {
        ownerId: pid,
        ownerType: OWNER_TYPES.PLAYER,
        stockpile: city.stockpile,
        nowMs: simTimeMs,
        source: 'market_sell:' + resId,
        referenceId: city.id
      });
      if (!payRes.ok) {
        return reject('Need at least ' + rate.lotSize + ' ' + rate.label + ' to sell at the Market');
      }
      const levelMult = 1 + (Math.max(0, mktLvl - 1) * 0.05);
      const goldEarned = Math.round(rate.sellGold * levelMult);
      city.stockpile.gold = (city.stockpile.gold || 0) + goldEarned;
      recordCurrencyTransaction(prog.currencyLedger, {
        ownerId: pid,
        ownerType: OWNER_TYPES.PLAYER,
        currencyId: 'gold',
        amount: goldEarned,
        transactionType: TRANSACTION_TYPES.AWARD,
        source: 'market_sell:' + resId,
        referenceId: city.id,
        nowMs: simTimeMs
      });
      if (eventStream) {
        eventStream.publish(STREAM_TOPICS.MARKET_TRADE, {
          cityId: city.id,
          side: 'sell',
          resourceId: resId,
          qty: rate.lotSize,
          goldDelta: goldEarned
        }, simTimeMs);
      }
      return accept({ side: 'sell', resourceId: resId, qty: rate.lotSize, goldEarned: goldEarned });
    }

    // Buy resource lot with City Gold through atomic payment validation
    const buyPayRes = executeAtomicPayment(prog.currencyLedger, [
      { kind: 'stockpile', resourceId: 'gold', amount: rate.buyGold }
    ], {
      ownerId: pid,
      ownerType: OWNER_TYPES.PLAYER,
      stockpile: city.stockpile,
      nowMs: simTimeMs,
      source: 'market_buy:' + resId,
      referenceId: city.id
    });
    if (!buyPayRes.ok) {
      return reject('Need ' + rate.buyGold + ' Gold to purchase ' + rate.lotSize + ' ' + rate.label);
    }
    city.stockpile[resId] = (city.stockpile[resId] || 0) + rate.lotSize;
    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.MARKET_TRADE, {
        cityId: city.id,
        side: 'buy',
        resourceId: resId,
        qty: rate.lotSize,
        goldDelta: -rate.buyGold
      }, simTimeMs);
    }
    return accept({ side: 'buy', resourceId: resId, qty: rate.lotSize, goldSpent: rate.buyGold });
  }

  if (cmdType === COMMAND_TYPES.MARKET_LIQUIDATE_ITEM) {
    const city = getPrimaryCity(state);
    if (!city || !city.storage || !Array.isArray(city.storage.items)) return reject('City Vault Storage unavailable');
    const mktLvl = (city.buildings && city.buildings.market_post) || 0;
    if (mktLvl < 1) return reject('Construct a Market & Trade Post before appraising relics');

    const idx = city.storage.items.findIndex(function(it) { return it.uid === payload.itemUid; });
    if (idx === -1) return reject('Item not found in City Vault Storage');
    const item = city.storage.items.splice(idx, 1)[0];

    const prog = ensureProgressionState(world);
    const pid = getCanonicalPlayerId(state);
    const baseVal = MARKET_RARITY_BASE_VALUES[item.rarity || 'common'] || 25;
    const temperBonus = (item.temperRank || 0) * 20;
    const gemBonus = Array.isArray(item.sockets) ? item.sockets.length * 30 : (Array.isArray(item.gems) ? item.gems.length * 30 : 0);

    // Consume Track F BenefitService relic_gold_mult (e.g. ADV_TREASURE_001) + Market level bonus
    const activeEffs = collectActiveEffects(prog, { playerId: pid });
    const appraisalMult = resolveNumericStat(1 + (Math.max(0, mktLvl - 1) * 0.05), 'relic_gold_mult', activeEffs.modifiers).finalValue;
    const payoutGold = Math.max(1, Math.round((baseVal + temperBonus + gemBonus) * appraisalMult));

    city.stockpile.gold = (city.stockpile.gold || 0) + payoutGold;
    recordCurrencyTransaction(prog.currencyLedger, {
      ownerId: pid,
      ownerType: OWNER_TYPES.PLAYER,
      currencyId: 'gold',
      amount: payoutGold,
      transactionType: TRANSACTION_TYPES.AWARD,
      source: 'market_liquidate:' + item.uid,
      referenceId: item.name,
      nowMs: simTimeMs
    });

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.MARKET_TRADE, {
        cityId: city.id,
        side: 'liquidate',
        itemName: item.name,
        goldDelta: payoutGold,
        appraisalMult: appraisalMult
      }, simTimeMs);
    }
    return accept({ item: item, payoutGold: payoutGold, appraisalMult: appraisalMult });
  }

  if (cmdType === COMMAND_TYPES.ACADEMY_STUDY_SESSION) {
    const city = getPrimaryCity(state);
    if (!city) return reject('No City founded');
    const acadLvl = (city.buildings && city.buildings.arcane_academy) || 0;
    if (acadLvl < 1) return reject('Construct an Arcane Academy & Library before funding study sessions');

    const prog = ensureProgressionState(world);
    const pid = getCanonicalPlayerId(state);
    const payRes = executeAtomicPayment(prog.currencyLedger, [
      { kind: 'stockpile', resourceId: 'gold', amount: 25 },
      { kind: 'stockpile', resourceId: 'food', amount: 10 }
    ], {
      ownerId: pid,
      ownerType: OWNER_TYPES.PLAYER,
      stockpile: city.stockpile,
      nowMs: simTimeMs,
      source: 'academy_study_session',
      referenceId: city.id
    });
    if (!payRes.ok) {
      return reject('Need 25 Gold and 10 Food to fund an Arcane Academy Study Session');
    }

    const rpAward = Math.round((0.05 * acadLvl) * 100000) / 100000;
    recordCurrencyTransaction(prog.currencyLedger, {
      ownerId: pid,
      ownerType: OWNER_TYPES.PLAYER,
      currencyId: 'rp_general',
      amount: rpAward,
      transactionType: TRANSACTION_TYPES.AWARD,
      source: 'academy_study_session',
      referenceId: city.id + ':L' + acadLvl,
      nowMs: simTimeMs
    });

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.ACADEMY_STUDY, {
        cityId: city.id,
        academyLevel: acadLvl,
        rpAwarded: rpAward
      }, simTimeMs);
    }
    return accept({ academyLevel: acadLvl, rpAwarded: rpAward });
  }

  // ---------------------------------------------------------------------------
  // 9C. MARCH TO DUNGEON (Quick-Order Hero Party to a Discovered Vault POI)
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.MARCH_TO_DUNGEON) {
    const unitId = payload.unitId || ow.selectedUnitId;
    const unit = (ow.units || []).find(function(u) { return u.id === unitId && u.alive; });
    if (!unit || unit.canEnterDungeon !== true) {
      return reject('Select a Hero-led Vanguard Party to march on a Dungeon');
    }
    const marchLeaderHero = (world.heroes || []).find(function(h) { return h.id === unit.leaderHeroId; }) || null;
    if (marchLeaderHero ? !isHeroDungeonEligible(marchLeaderHero) : !isClassDungeonEligible(unit.heroClassId)) {
      return reject('Selected unit leader is not eligible to enter a Dungeon');
    }
    if (unit.status === 'in_dungeon') {
      return reject('Party is already delving inside a dungeon');
    }

    const poi = (ow.pois || []).find(function(p) {
      return p.type === 'dungeon_entrance' && (payload.poiId ? p.id === payload.poiId : true);
    });
    if (!poi) return reject('Dungeon entrance not found on Overworld');
    if (!poi.discovered && !(ow.explored[poi.y] && ow.explored[poi.y][poi.x])) {
      return reject('Scout the Overworld to discover ' + poi.name + ' before marching there');
    }
    const blockingTarget = getBlockingMilitaryTargetForAccess(ow, 'overworld_poi', poi.id);
    if (blockingTarget) {
      return reject('Access to ' + poi.name + ' is blocked by ' + blockingTarget.name + ' — clear it with a Field Army first');
    }

    if (unit.x === poi.x && unit.y === poi.y) {
      return accept({ alreadyAtEntrance: true, poiId: poi.id, dungeonId: poi.dungeonId });
    }

    return dispatchWargameCommand({
      type: COMMAND_TYPES.ORDER_UNIT_MARCH,
      payload: {
        unitId: unit.id,
        targetX: poi.x,
        targetY: poi.y,
        intent: 'enter_dungeon',
        targetPoiId: poi.id
      }
    }, state, scheduler, eventStream);
  }

  // ---------------------------------------------------------------------------
  // 9D. ENTER DUNGEON (Transition Hero Party into Turn-Based Tactical Engine)
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.ENTER_DUNGEON) {
    const unitId = payload.unitId || ow.selectedUnitId;
    const unit = (ow.units || []).find(function(u) { return u.id === unitId && u.alive; });
    if (!unit || unit.canEnterDungeon !== true) {
      return reject('Requires an active Hero-led Vanguard Party to enter a Dungeon');
    }

    // HR-12: Authoritative fail-closed hero/class dungeon admission check before any state mutation
    const hero = (world.heroes || []).find(function(h) { return h.id === unit.leaderHeroId; }) || null;
    if (hero) {
      if (!isHeroDungeonEligible(hero)) {
        return reject('Hero ' + (hero.name || hero.id) + ' (' + (hero.classId || 'unknown') + ') is not eligible to enter a Dungeon');
      }
    } else if (!isClassDungeonEligible(unit.heroClassId)) {
      return reject('Party leader class (' + (unit.heroClassId || 'unknown') + ') is not eligible to enter a Dungeon');
    }

    const poi = (ow.pois || []).find(function(p) {
      if (p.type !== 'dungeon_entrance') return false;
      if (payload.poiId) return p.id === payload.poiId;
      return unit.x === p.x && unit.y === p.y;
    });
    if (!poi) {
      return reject('Party must complete its march onto a Dungeon Entrance before entering');
    }
    if (unit.status === 'marching') {
      return reject('Wait until the party finishes moving into ' + poi.name + ' before entering');
    }
    if (unit.x !== poi.x || unit.y !== poi.y) {
      return reject('Party must stand directly on ' + poi.name + ' before entering');
    }
    const blockingTarget = getBlockingMilitaryTargetForAccess(ow, 'overworld_poi', poi.id);
    if (blockingTarget) {
      return reject('Access to ' + poi.name + ' is blocked by ' + blockingTarget.name + ' — clear it with a Field Army first');
    }

    if (unit.marchPlan && unit.marchPlan.activeJobId && scheduler) {
      scheduler.cancelJob(unit.marchPlan.activeJobId);
    }
    unit.x = poi.x;
    unit.y = poi.y;
    unit.status = 'in_dungeon';
    unit.marchPlan = null;
    unit.activeDungeonPoiId = poi.id;
    unit.activeDungeonId = poi.dungeonId;

    world.stats.dungeonsEntered = (world.stats.dungeonsEntered || 0) + 1;

    const city = getPrimaryCity(state);

    const envelopeData = {
      campaignId: world.campaignId || (world.id + '_' + (world.seedCode || 'STAR')),
      seedCode: world.seedCode || 'STAR-7777',
      houseName: (world.player && world.player.houseName) || 'House Vanguard',
      cityId: city ? city.id : null,
      cityName: city ? city.name : 'Oakhaven Bastion',
      cityCoords: city ? { x: city.x, y: city.y } : null,
      partyUnitId: unit.id,
      hero: hero ? {
        id: hero.id,
        name: hero.name,
        classId: hero.classId,
        canEnterDungeon: hero.canEnterDungeon,
        level: hero.level,
        xp: hero.xp,
        equipment: hero.equipment || null,
        cosmetics: hero.cosmetics || null
      } : {
        id: unit.leaderHeroId || 'hero_1',
        name: unit.shortName,
        classId: unit.heroClassId,
        canEnterDungeon: true,
        level: 1,
        xp: 0
      },
      dungeon: {
        poiId: poi.id,
        dungeonId: poi.dungeonId,
        profileId: poi.profileId || 'starfall_vaults',
        name: poi.name,
        coords: { x: poi.x, y: poi.y }
      }
    };

    const envelope = payload.skipStorageWrite
      ? createDungeonEntryEnvelope(envelopeData)
      : writeDungeonEntryHandoff(envelopeData);

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.DUNGEON_ENTERED, {
        unitId: unit.id,
        unitName: unit.shortName,
        poiId: poi.id,
        dungeonId: poi.dungeonId,
        dungeonName: poi.name
      }, simTimeMs);
    }

    evaluateTaskDAG(state, eventStream);
    return accept({
      unitId: unit.id,
      poiId: poi.id,
      dungeonId: poi.dungeonId,
      envelope: envelope
    });
  }

  // ---------------------------------------------------------------------------
  // 9D2. EXIT DUNGEON TO SURFACE (Safely surface a party marked in_dungeon)
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.EXIT_DUNGEON_TO_SURFACE) {
    const unitId = payload.unitId || ow.selectedUnitId;
    const unit = (ow.units || []).find(function(u) { return u.id === unitId && u.alive; });
    if (!unit) return reject('No active party found');
    unit.status = 'idle';
    unit.marchPlan = null;
    unit.activeDungeonPoiId = null;
    unit.activeDungeonId = null;
    return accept({ unitId: unit.id, x: unit.x, y: unit.y, status: 'idle' });
  }

  // ---------------------------------------------------------------------------
  // 9E. RESOLVE DUNGEON RETURN (Extraction Return March, Recall Scroll, or Defeat)
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.RESOLVE_DUNGEON_RETURN) {
    const outcome = payload.outcome === 'defeated' ? 'defeated' : 'extracted';
    const method = payload.method || 'Floor 1 Ascending Stairs (<)';
    const loot = payload.lootSummary || {};
    const city = getPrimaryCity(state);

    let unit = null;
    if (payload.partyUnitId) {
      unit = (ow.units || []).find(function(u) { return u.id === payload.partyUnitId && u.alive; });
    }
    if (!unit) {
      unit = (ow.units || []).find(function(u) { return u.status === 'in_dungeon' && u.alive; })
          || (ow.units || []).find(function(u) { return u.unitType === 'hero_party' && u.alive; });
    }
    if (!unit) return reject('No Vanguard Party found to resolve dungeon return');

    // Sync hero progression back to Overworld roster
    const hero = (world.heroes || []).find(function(h) {
      return h.id === (payload.heroId || unit.leaderHeroId);
    });
    if (hero) {
      if (typeof payload.heroLevel === 'number' && payload.heroLevel > hero.level) {
        hero.level = payload.heroLevel;
      }
      if (typeof payload.heroXp === 'number' && payload.heroXp >= 0) {
        hero.xp = payload.heroXp;
      }
      if (typeof payload.heroMaxXp === 'number' && payload.heroMaxXp > 0) {
        hero.maxXp = payload.heroMaxXp;
      }
      if (payload.heroBonusStats && typeof payload.heroBonusStats === 'object') {
        hero.bonusStats = normalizeHeroBonusStats(payload.heroBonusStats);
      }
      if (payload.heroKnowledge && typeof payload.heroKnowledge === 'object') {
        hero.knowledge = normalizeHeroKnowledge(payload.heroKnowledge);
      }
      if (typeof payload.heroStatPoints === 'number' && payload.heroStatPoints >= 0) {
        hero.statPoints = payload.heroStatPoints;
      }
      if (typeof payload.heroTalentPoints === 'number' && payload.heroTalentPoints >= 0) {
        hero.talentPoints = payload.heroTalentPoints;
      }
      if (payload.heroTalentsAllocated && typeof payload.heroTalentsAllocated === 'object') {
        hero.talentsAllocated = Object.assign({}, payload.heroTalentsAllocated);
      }
      if (payload.heroEquipment && typeof payload.heroEquipment === 'object') {
        hero.equipment = Object.assign({}, hero.equipment || {}, payload.heroEquipment);
      }
      refreshHeroDerivedStats(hero);
    }

    const poiId = payload.dungeonPoiId || unit.activeDungeonPoiId;
    const poi = (ow.pois || []).find(function(p) { return p.id === poiId; })
             || (ow.pois || []).find(function(p) { return p.type === 'dungeon_entrance'; });

    unit.activeDungeonPoiId = null;
    unit.activeDungeonId = null;
    ow.selectedUnitId = unit.id;

    if (outcome === 'defeated') {
      // Non-Permanent Defeat (Golden Rule #2): Express-return directly to City Adventurers Guild Hall
      if (unit.marchPlan && unit.marchPlan.activeJobId && scheduler) {
        scheduler.cancelJob(unit.marchPlan.activeJobId);
      }
      if (city) {
        unit.x = city.x;
        unit.y = city.y;
        if (loot.salvagedGold > 0) {
          city.stockpile.gold = (city.stockpile.gold || 0) + loot.salvagedGold;
        }
      }
      unit.status = 'idle';
      unit.marchPlan = null;
      unit.hp = unit.maxHp;
      unit.cargo = null;

      if (eventStream) {
        eventStream.publish(STREAM_TOPICS.DUNGEON_RETURNED, {
          outcome: 'defeated',
          method: 'Guild Scout Rescue',
          unitId: unit.id,
          unitName: unit.shortName,
          killerName: payload.killerName || 'Abyssal Guardian',
          floorDepth: payload.floorDepth || 1,
          salvagedGold: loot.salvagedGold || 0,
          cityName: city ? city.name : 'Bastion'
        }, simTimeMs);
      }

      evaluateTaskDAG(state, eventStream);
      return accept({ outcome: 'defeated', unitId: unit.id, x: unit.x, y: unit.y, salvagedGold: loot.salvagedGold || 0 });
    }

    // Outcome: 'extracted'
    unit.hp = unit.maxHp;
    unit.status = 'idle';
    unit.marchPlan = null;

    if (!unit.cargo) {
      unit.cargo = { gold: 0, ore: 0, gems: 0, gearCount: 0, gearItems: [] };
    }
    if (!Array.isArray(unit.cargo.gearItems)) unit.cargo.gearItems = [];
    const incomingGear = Array.isArray(payload.extractedGear) ? payload.extractedGear : [];
    for (let gi = 0; gi < incomingGear.length; gi++) {
      unit.cargo.gearItems.push(incomingGear[gi]);
    }
    unit.cargo.gold      = (unit.cargo.gold      || 0) + (loot.gold      || 0);
    unit.cargo.ore       = (unit.cargo.ore       || 0) + (loot.ore       || 0);
    unit.cargo.gems      = (unit.cargo.gems      || 0) + (loot.gems      || 0);
    unit.cargo.gearCount = (unit.cargo.gearCount || 0) + Math.max(loot.gearCount || 0, incomingGear.length);

    const isRecallScroll = String(method).indexOf('Recall Scroll') !== -1;
    let returnMarchStarted = false;
    let surfacedAtEntrance = false;

    if (isRecallScroll) {
      // Astral Recall Scroll: Instant exit to the surface at the Dungeon Entrance POI (idle, cargo intact).
      // Player chooses which City or destination to march to next on the Overworld.
      if (poi) {
        unit.x = poi.x;
        unit.y = poi.y;
        revealOverworldVision(ow, unit.x, unit.y, unit.visionRadius || 5, { simTimeMs: simTimeMs, eventStream: eventStream });
      }
      surfacedAtEntrance = true;
    } else {
      // Surface extraction via Floor 1 Stairs or Boss Portal: Exit at Vault POI & begin timed Return March home
      if (poi) {
        unit.x = poi.x;
        unit.y = poi.y;
        revealOverworldVision(ow, unit.x, unit.y, unit.visionRadius || 5, { simTimeMs: simTimeMs, eventStream: eventStream });
      }
      if (city && (unit.x !== city.x || unit.y !== city.y)) {
        const marchRes = dispatchWargameCommand({
          type: COMMAND_TYPES.ORDER_UNIT_MARCH,
          payload: {
            unitId: unit.id,
            targetX: city.x,
            targetY: city.y,
            intent: 'return_city',
            targetCityId: city.id
          }
        }, state, scheduler, eventStream);
        returnMarchStarted = Boolean(marchRes && marchRes.ok);
      } else if (city) {
        depositUnitCargoAtCity(unit, city, state, simTimeMs, eventStream);
      }
    }

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.DUNGEON_RETURNED, {
        outcome: 'extracted',
        method: method,
        unitId: unit.id,
        unitName: unit.shortName,
        expressReturn: false,
        surfacedAtEntrance: surfacedAtEntrance,
        returnMarchStarted: returnMarchStarted,
        lootSummary: loot,
        cityName: city ? city.name : 'Bastion'
      }, simTimeMs);
    }

    evaluateTaskDAG(state, eventStream);
    return accept({
      outcome: 'extracted',
      expressReturn: false,
      surfacedAtEntrance: surfacedAtEntrance,
      returnMarchStarted: returnMarchStarted,
      unitId: unit.id,
      x: unit.x,
      y: unit.y
    });
  }

  // ---------------------------------------------------------------------------
  // 10. CLAIM TASK REWARD
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.CLAIM_TASK_REWARD) {
    const taskId = payload.taskId;
    const tDef = CAMPAIGN_TASKS_DAG.find(function(t) { return t.id === taskId; });
    if (!tDef) return reject('Unknown task ID: ' + taskId);

    evaluateTaskDAG(state, eventStream);
    const entry = world.tasks[taskId];
    if (!entry || entry.status !== 'completed') {
      return reject('Task is not ready to claim');
    }

    entry.status = 'claimed';
    entry.claimedAtSimMs = simTimeMs;

    const city = getPrimaryCity(state);
    const targetStock = city ? city.stockpile : world.realmStockpile;
    const r = tDef.reward || {};

    if (r.wood)  targetStock.wood  = (targetStock.wood  || 0) + r.wood;
    if (r.stone) targetStock.stone = (targetStock.stone || 0) + r.stone;
    if (r.food)  targetStock.food  = (targetStock.food  || 0) + r.food;
    if (r.gold)  targetStock.gold  = (targetStock.gold  || 0) + r.gold;

    if (eventStream) {
      eventStream.publish(STREAM_TOPICS.TASK_CLAIMED, {
        taskId: taskId,
        title: tDef.title,
        rewardLabel: tDef.rewardLabel,
        reward: r
      }, simTimeMs);
    }

    evaluateTaskDAG(state, eventStream);

    return accept({
      taskId: taskId,
      reward: r,
      stockpile: targetStock
    });
  }

  // ---------------------------------------------------------------------------
  // 11. SET SIMULATION SPEED / PAUSE
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.SET_SIM_SPEED) {
    if (typeof payload.paused === 'boolean') {
      world.clock.paused = payload.paused;
      if (eventStream) {
        eventStream.publish(STREAM_TOPICS.CLOCK_PAUSED, { paused: world.clock.paused }, simTimeMs);
      }
    }
    if (typeof payload.speedMultiplier === 'number' && payload.speedMultiplier > 0) {
      world.clock.speedMultiplier = payload.speedMultiplier;
      if (eventStream) {
        eventStream.publish(STREAM_TOPICS.CLOCK_SPEED_CHANGED, { speedMultiplier: world.clock.speedMultiplier }, simTimeMs);
      }
    }
    return accept({
      paused: world.clock.paused,
      speedMultiplier: world.clock.speedMultiplier
    });
  }

  // ---------------------------------------------------------------------------
  // 12. SWITCH ACTIVE VIEWPORT (Respecting Campaign Phase Gating!)
  // ---------------------------------------------------------------------------
  if (cmdType === COMMAND_TYPES.SWITCH_VIEW) {
    const targetView = payload.view;
    if (targetView === WARGAME_VIEWS.CITY && Object.keys(world.cities || {}).length === 0) {
      return reject('You must found your first Bastion City with your Pioneer Settler before entering City View');
    }
    if (targetView === WARGAME_VIEWS.GUILD) {
      const city = getPrimaryCity(state);
      const hasGuildHall = Boolean(city && city.buildings && city.buildings.guild_hall >= 1);
      if (!hasGuildHall) {
        return reject('Construct the Adventurers Guild Hall in your City before opening the Guild Recruitment Hall');
      }
    }
    state.activeView = targetView;
    return accept({ activeView: state.activeView });
  }

  return reject('Unsupported command type: ' + cmdType);
}

// Advance the authoritative simulation clock by deltaRealMs (multiplied by clock.speedMultiplier)
function advanceSimulationClock(deltaRealMs, state, scheduler, eventStream) {
  if (!state || !state.world || !state.world.clock) return 0;
  const clock = state.world.clock;
  if (clock.paused || deltaRealMs <= 0) return 0;

  const mult = clock.speedMultiplier || 1;
  const simDelta = Math.round(deltaRealMs * mult);
  const targetSimTime = clock.simTimeMs + simDelta;

  // Pop and execute all scheduled jobs (including chained jobs) in chronological order up to targetSimTime
  let jobsExecuted = 0;
  if (scheduler) {
    while (jobsExecuted < 500) {
      const dueJobs = scheduler.popDueJobs(targetSimTime);
      if (!dueJobs || dueJobs.length === 0) break;
      for (let i = 0; i < dueJobs.length; i++) {
        const job = dueJobs[i];
        clock.simTimeMs = job.dueSimTimeMs;
        jobsExecuted++;
        if (job.jobType === 'UNIT_MARCH_STEP') {
          resolveMarchStepJob(job, state, scheduler, eventStream);
        } else if (job.jobType === 'CITY_BUILDING_COMPLETE') {
          resolveBuildingCompleteJob(job, state, scheduler, eventStream);
        } else if (job.jobType === 'CITY_BUILDING_MOVE_COMPLETE') {
          resolveBuildingMoveJob(job, state, scheduler, eventStream);
        } else if (job.jobType === 'CITY_BUILDING_DEMOLISH_COMPLETE') {
          resolveBuildingDemolishJob(job, state, scheduler, eventStream);
        } else if (job.jobType === 'HERO_RECRUIT_COMPLETE') {
          resolveRecruitHeroJob(job, state, scheduler, eventStream);
        } else if (job.jobType === 'TROOP_TRAIN_UNIT_COMPLETE') {
          resolveTroopTrainUnitJob(job, state, scheduler, eventStream);
        } else if (job.jobType === 'TROOP_UPGRADE_UNIT_COMPLETE') {
          resolveTroopUpgradeUnitJob(job, state, scheduler, eventStream);
        } else if (job.jobType === 'ARMY_OBJECTIVE_COMPLETE') {
          resolveArmyObjectiveCompleteJob(job, state, scheduler, eventStream);
        }
      }
    }
  }

  clock.simTimeMs = targetSimTime;

  // Process periodic city resource production ticks
  if (typeof clock.nextResourceTickMs !== 'number') {
    clock.nextResourceTickMs = RESOURCE_PRODUCTION_INTERVAL_MS;
  }
  while (clock.simTimeMs >= clock.nextResourceTickMs) {
    processResourceProductionTick(state, eventStream);
    clock.nextResourceTickMs += RESOURCE_PRODUCTION_INTERVAL_MS;
  }

  return jobsExecuted;
}

  // --- Module: src/wargame/engine/simHost.js ---
// Authoritative Wargame Simulation Host (SimHost)
// Encapsulates State Store, Min-Heap Priority Queue Scheduler, Replayable WorldEventStream & CommandBus.
// Provides a clean LocalLoopback / WebSocket-ready boundary for UI clients and deterministic tests.







function createWargameSimHost(initialState = null) {
  const state = initialState || createTitleScreenState();
  const scheduler = createSimulationScheduler();
  const eventStream = createWorldEventStream(500);
  let attachedDungeonState = null;

  function attachDungeonState(dungeonStateRef) {
    attachedDungeonState = dungeonStateRef || null;
  }

  function resetAttachedDungeonState() {
    if (!attachedDungeonState) return;
    const fresh = createDefaultGameState();
    Object.keys(attachedDungeonState).forEach(function(k) { delete attachedDungeonState[k]; });
    Object.assign(attachedDungeonState, fresh);
  }

  function dispatch(commandEnvelope) {
    return dispatchWargameCommand(commandEnvelope, state, scheduler, eventStream);
  }

  function stepClock(deltaRealMs) {
    return advanceSimulationClock(deltaRealMs, state, scheduler, eventStream);
  }

  function save() {
    return saveWargameState(state, scheduler, attachedDungeonState);
  }

  function surfaceUnitsOnWorld(worldObj) {
    if (!worldObj || !worldObj.overworld || !Array.isArray(worldObj.overworld.units)) return;
    const pois = Array.isArray(worldObj.overworld.pois) ? worldObj.overworld.pois : [];
    for (let i = 0; i < worldObj.overworld.units.length; i++) {
      const u = worldObj.overworld.units[i];
      if (!u || !u.alive || u.status !== 'in_dungeon') continue;
      if (u.dungeonPoiId) {
        const poi = pois.find(function(p) { return p && p.id === u.dungeonPoiId; });
        if (poi && typeof poi.x === 'number' && typeof poi.y === 'number') {
          u.x = poi.x;
          u.y = poi.y;
        }
      }
      u.status = 'idle';
      u.movePlan = null;
      u.activeJobId = null;
      u.dungeonPoiId = null;
    }
  }

  function load() {
    // Phase 1: Stage & validate campaign state without mutating live state or scheduler
    const loaded = loadWargameState(null, { deferSchedulerHydrate: true });
    if (!loaded) return false;

    // Phase 2: Stage dungeon-world hydration into an isolated sandbox before committing
    let stagedDungeon = null;
    if (attachedDungeonState) {
      stagedDungeon = createDefaultGameState();
      if (loaded.world && loaded.world.dungeonWorld) {
        const hRes = hydrateDungeonWorldSnapshot(loaded.world.dungeonWorld, stagedDungeon);
        if (!hRes || !hRes.ok) {
          // Deterministic fallback: discard corrupt dungeon slice and safely surface any in_dungeon unit
          stagedDungeon = createDefaultGameState();
          loaded.world.dungeonWorld = null;
          surfaceUnitsOnWorld(loaded.world);
        } else if (stagedDungeon.wargameSession && stagedDungeon.wargameSession.active) {
          // Verify matching in_dungeon unit exists and is alive
          const targetUnitId = stagedDungeon.wargameSession.partyUnitId;
          const units = (loaded.world.overworld && Array.isArray(loaded.world.overworld.units))
            ? loaded.world.overworld.units : [];
          const matchUnit = units.find(function(u) {
            return u && u.alive && u.id === targetUnitId && u.status === 'in_dungeon';
          });
          if (!matchUnit) {
            stagedDungeon.wargameSession.active = false;
            stagedDungeon.inGuild = true;
            surfaceUnitsOnWorld(loaded.world);
          }
        }
      }
    }

    // Phase 3: Atomic commit with rollback guard
    const prevStateBackup = {};
    Object.keys(state).forEach(function(k) { prevStateBackup[k] = state[k]; });
    const prevJobsBackup = scheduler.serializeJobs();
    const prevDungeonBackup = attachedDungeonState ? {} : null;
    if (attachedDungeonState) {
      Object.keys(attachedDungeonState).forEach(function(k) { prevDungeonBackup[k] = attachedDungeonState[k]; });
    }

    try {
      Object.keys(state).forEach(function(k) { delete state[k]; });
      Object.assign(state, loaded);

      const stagedJobs = (loaded.world && Array.isArray(loaded.world.scheduledJobs))
        ? loaded.world.scheduledJobs
        : [];
      scheduler.hydrateJobs(stagedJobs);

      if (attachedDungeonState && stagedDungeon) {
        Object.keys(attachedDungeonState).forEach(function(k) { delete attachedDungeonState[k]; });
        Object.assign(attachedDungeonState, stagedDungeon);
      }

      evaluateTaskDAG(state, eventStream);
      return true;
    } catch (err) {
      // Roll back live state, scheduler, and dungeon state on unexpected commit failure
      Object.keys(state).forEach(function(k) { delete state[k]; });
      Object.assign(state, prevStateBackup);
      scheduler.hydrateJobs(prevJobsBackup);
      if (attachedDungeonState && prevDungeonBackup) {
        Object.keys(attachedDungeonState).forEach(function(k) { delete attachedDungeonState[k]; });
        Object.assign(attachedDungeonState, prevDungeonBackup);
      }
      return false;
    }
  }

  return {
    state: state,
    scheduler: scheduler,
    eventStream: eventStream,
    attachDungeonState: attachDungeonState,
    resetAttachedDungeonState: resetAttachedDungeonState,
    dispatch: dispatch,
    stepClock: stepClock,
    save: save,
    load: load,
    hasSavedCampaign: hasSavedWargameCampaign,
    peekSavedSummary: peekSavedCampaignSummary
  };
}

