  ctx.lineTo(cx + 36, 94);
  ctx.lineTo(cx + 22, 175);
  ctx.lineTo(cx - 22, 175);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = themeColor + '55';
  ctx.lineWidth = 1.5;
