  const disbandRes30 = host30.dispatch({ type: COMMAND_TYPES.DISBAND_TROOPS, payload: { troopDefId: 'infantry', level: 1, quantity: 1 } });
  const invAfterDisband30 = getCityTroopInventorySummary(host30.state.world, city30);
