function handleDungeonSkill() {
  if (appContext.getActiveContext() !== APP_CONTEXTS.DUNGEON) return;
  const qSlots = getHeroQuickAccessBar(gameState);
  const first = qSlots[0] && !qSlots[0].empty ? qSlots[0] : null;
  if (first) {
    handleDungeonAbilityClick(first.id);
    return;
  }
  executeClassSkill(gameState);
  syncIntegratedDungeonHud();
}

function handleToggleDungeonSpellbook(forceOpen) {
  dungeonSpellbookOpen = typeof forceOpen === 'boolean' ? forceOpen : !dungeonSpellbookOpen;
  syncIntegratedDungeonHud();
}

function resolveSpellbookHero() {
  if (appContext.getActiveContext() === APP_CONTEXTS.DUNGEON && gameState && gameState.hero) {
    return gameState.hero;
  }
  const w = simHost && simHost.state && simHost.state.world;
  if (!w || !Array.isArray(w.heroes)) return null;
  if (simHost.state._openHeroSheetId) {
    return w.heroes.find(function(h) { return h && h.id === simHost.state._openHeroSheetId; }) || w.heroes[0] || null;
  }
  return w.heroes[0] || null;
}

function mirrorQuickSlotsToCanonicalHero(hero) {
  if (!hero || !simHost || !simHost.state || !simHost.state.world || !Array.isArray(simHost.state.world.heroes)) return;
  const canonical = simHost.state.world.heroes.find(function(h) { return h && h.id === hero.id; });
  if (canonical && canonical !== hero && hero.quickSlots) {
    canonical.quickSlots = JSON.parse(JSON.stringify(hero.quickSlots));
    canonical._quickSlotsCustomized = Boolean(hero._quickSlotsCustomized);
    canonical._quickSlotsInitialized = hero._quickSlotsInitialized ? Object.assign({}, hero._quickSlotsInitialized) : null;
  }
}

function handleSpellbookFilter(ctxFilter, kindFilter) {
  if (simHost && simHost.state) {
    simHost.state._spellbookContextFilter = ctxFilter || 'all';
    simHost.state._spellbookKindFilter = kindFilter || 'all';
    if (ctxFilter === 'overworld' || ctxFilter === 'tactical_dungeon') {
      simHost.state._spellbookActiveContext = ctxFilter;
    }
    simHost.state._dirty = true;
  }
  if (appContext.getActiveContext() === APP_CONTEXTS.DUNGEON) syncIntegratedDungeonHud();
  else syncWargameUI(simHost);
}

function handleAssignQuickSlot(contextId, slotIndex, abilityId) {
  const hero = resolveSpellbookHero();
  if (!hero) return { ok: false, reason: 'no_hero' };
  const res = assignQuickSlot(hero, contextId, slotIndex, abilityId);
  if (res.ok) {
    mirrorQuickSlotsToCanonicalHero(hero);
    simHost.save();
    if (appContext.getActiveContext() === APP_CONTEXTS.DUNGEON) syncIntegratedDungeonHud();
    else syncWargameUI(simHost);
  }
  return res;
}

function handleClearQuickSlot(contextId, slotIndex) {
  const hero = resolveSpellbookHero();
  if (!hero) return { ok: false, reason: 'no_hero' };
  const res = clearQuickSlot(hero, contextId, slotIndex);
  if (res.ok) {
    mirrorQuickSlotsToCanonicalHero(hero);
    simHost.save();
    if (appContext.getActiveContext() === APP_CONTEXTS.DUNGEON) syncIntegratedDungeonHud();
    else syncWargameUI(simHost);
  }
  return res;
}

function handleSwapQuickSlots(contextId, idxA, idxB) {
  const hero = resolveSpellbookHero();
  if (!hero) return { ok: false, reason: 'no_hero' };
  const res = swapQuickSlots(hero, contextId, idxA, idxB);
  if (res.ok) {
    mirrorQuickSlotsToCanonicalHero(hero);
    simHost.save();
    if (appContext.getActiveContext() === APP_CONTEXTS.DUNGEON) syncIntegratedDungeonHud();
    else syncWargameUI(simHost);
  }
  return res;
}

function handleSpellbookCast(abilityId, contextId) {
  if (contextId === 'overworld') {
    return handleStrategicAbility(abilityId);
  }
  if (appContext.getActiveContext() === APP_CONTEXTS.DUNGEON) {
    dungeonSpellbookOpen = false;
    handleDungeonAbilityClick(abilityId);
    return { ok: true };
  }
  return { ok: false, reason: 'wrong_context' };
}

function handleDungeonAbilityHover(active, abilityId) {
  if (appContext.getActiveContext() !== APP_CONTEXTS.DUNGEON) return;
  setSkillHover(Boolean(active), abilityId || null);
}

function handleCancelDungeonTargeting() {
  setManualTargetingAbility(null);
  setSkillHover(false);
  syncIntegratedDungeonHud();
}

function handleStrategicAbility(abilityId) {
  if (!simHost || !simHost.state || !simHost.state.world) return { ok: false };
  const res = executeStrategicAbility(simHost, abilityId);
  simHost.save();
  syncWargameUI(simHost);
  return res;
}

function handleDungeonQuickSlot(slotIndex) {
  if (appContext.getActiveContext() !== APP_CONTEXTS.DUNGEON || !gameState || !gameState.hero) return { ok: false, reason: 'wrong_context' };
  const qSlots = getHeroQuickAccessBar(gameState);
  const slot = qSlots[slotIndex];
  if (!slot || slot.empty || !slot.id) {
    appendUnifiedDungeonLog('Quick Slot [' + (slotIndex + 1) + '] is empty. Press [Q] to open Spellbook and assign a spell or skill.', 'info');
    syncIntegratedDungeonHud();
    return { ok: false, reason: 'empty_slot' };
  }
  if (!slot.granted) {
    appendUnifiedDungeonLog(slot.name + ' is currently unavailable (no access).', 'bad');
    syncIntegratedDungeonHud();
    return { ok: false, reason: 'not_granted' };
  }
  if (!slot.availableInContext) {
    appendUnifiedDungeonLog(slot.name + ' cannot be used in Tactical Dungeon.', 'bad');
    syncIntegratedDungeonHud();
    return { ok: false, reason: 'invalid_context' };
  }
  if (!slot.ready) {
    const why = slot.silenced ? 'Silenced' : (slot.cooldownRemaining > 0 ? ('Cooldown ' + slot.cooldownRemaining + 't') : (slot.unavailableReason === 'requires_ranged_weapon' ? 'Requires Ranged Weapon' : 'Insufficient MP'));
    appendUnifiedDungeonLog(slot.name + ' cannot be used (' + why + ').', 'bad');
    syncIntegratedDungeonHud();
    return { ok: false, reason: slot.unavailableReason || 'unavailable' };
  }
  return handleDungeonAbilityClick(slot.id);
}

function handleOverworldQuickSlot(slotIndex) {
  if (!simHost || !simHost.state || !simHost.state.world) return { ok: false, reason: 'no_world' };
  const selUnit = getSelectedOverworldUnit(simHost.state);
  if (!selUnit || !selUnit.leaderHeroId) return { ok: false, reason: 'no_hero_unit' };
  const hero = (simHost.state.world.heroes || []).find(function(h) { return h && h.id === selUnit.leaderHeroId; }) || null;
  if (!hero) return { ok: false, reason: 'no_hero' };
  const slots = getHeroQuickSlots(hero, 'overworld');
  const sl = slots[slotIndex];
  if (!sl || !sl.abilityId) return { ok: false, reason: 'empty_slot' };
  if (!sl.granted || !sl.availableInContext) {
    simHost.state._lastStrategicFeedback = 'Quick Slot [' + (slotIndex + 1) + '] is currently unavailable.';
    syncWargameUI(simHost);
    return { ok: false, reason: !sl.granted ? 'not_granted' : 'invalid_context' };
  }
  return handleStrategicAbility(sl.abilityId);
}

function handleToggleBuildingCategory(categoryId) {
  if (!simHost || !simHost.state || !categoryId) return;
  if (!simHost.state._collapsedBuildingCategories || typeof simHost.state._collapsedBuildingCategories !== 'object') {
    simHost.state._collapsedBuildingCategories = {};
  }
  simHost.state._collapsedBuildingCategories[categoryId] = !simHost.state._collapsedBuildingCategories[categoryId];
  simHost.state._dirty = true;
  syncWargameUI(simHost);
}

function handleDungeonAbilityClick(abilityId) {
  if (appContext.getActiveContext() !== APP_CONTEXTS.DUNGEON || !gameState || !gameState.hero) return { ok: false, reason: 'wrong_context' };
  const bar = getHeroAbilityBarState(gameState);
  const entry = bar.find(function(a) { return a.id === abilityId; });
  if (!entry) {
    appendUnifiedDungeonLog('That spell or skill is not currently accessible.', 'bad');
    syncIntegratedDungeonHud();
    return { ok: false, reason: 'not_granted' };
  }
  if (!entry.ready) {
    const why = entry.silenced ? 'Silenced' : (entry.cooldownRemaining > 0 ? ('Cooldown ' + entry.cooldownRemaining + 't') : (entry.unavailableReason === 'requires_ranged_weapon' ? 'Requires Ranged Weapon' : 'Insufficient MP'));
    appendUnifiedDungeonLog(entry.name + ' cannot be used (' + why + ').', 'bad');
    syncIntegratedDungeonHud();
    return { ok: false, reason: entry.unavailableReason || 'unavailable' };
  }
  if (entry.requiresManualTarget) {
    if (getManualTargetingAbility() === abilityId) {
      // Second click cancels targeting
      setManualTargetingAbility(null);
      setSkillHover(false);
    } else {
      setManualTargetingAbility(abilityId);
      setSkillHover(true, abilityId);
    }
    syncIntegratedDungeonHud();
    return { ok: true, targeting: getManualTargetingAbility() };
  }
  setManualTargetingAbility(null);
  setSkillHover(false);
  const res = executeAbility(abilityId, null, gameState);
  syncIntegratedDungeonHud();
  return res;
}

function handleDungeonTonic() {
  if (appContext.getActiveContext() !== APP_CONTEXTS.DUNGEON) return;
  useHealingTonic(gameState);
  syncIntegratedDungeonHud();
}

function handleDungeonRecall() {
  if (appContext.getActiveContext() !== APP_CONTEXTS.DUNGEON) return;
  useRecallScroll(gameState);
}

function handleDungeonSurfaceExit() {
  if (appContext.getActiveContext() !== APP_CONTEXTS.DUNGEON) return;
  if (gameState && gameState.hero && gameState.wargameSession && gameState.wargameSession.active && gameState.wargameSession.inProcess) {
    extractToGuild('Dungeon Surface Exit', gameState);
    return;
  }
  appContext.exitDungeon(null);
}

// ---------------------------------------------------------------------------
// Canvas Mouse & Keyboard Listeners
// ---------------------------------------------------------------------------
function setupWargameListeners() {
  if (typeof document === 'undefined') return;

  const isoCanvas = document.getElementById('wgCityIsoCanvas');
  if (isoCanvas) {
    attachCityIsoControls(isoCanvas, {
      onRepaint: function() {
        renderCityIsoCanvas(simHost);
      },
      onSelectPlot: function(plotIndex) {
        if (typeof simHost.state._moveSourcePlotIndex === 'number') {
          const srcIdx = simHost.state._moveSourcePlotIndex;
          delete simHost.state._moveSourcePlotIndex;
          if (srcIdx !== plotIndex) handleMoveBuilding(srcIdx, plotIndex);
          else syncWargameUI(simHost);
          return;
        }
        const city = getPrimaryCity(simHost.state);
        const plot = city && Array.isArray(city.plots) ? city.plots[plotIndex] : null;
        const alreadySelected = Boolean(city && city.selectedPlotIndex === plotIndex);
        if (alreadySelected && plot && plot.buildingId && !plot.underConstruction && !plot.demolishing && !plot.relocating) {
          handleOpenFacilityModal(plot.buildingId, plotIndex);
          return;
        }
        handleSelectCityPlot(plotIndex);
      }
    });
  }

  const canvas = document.getElementById('wgOverworldCanvas');
  if (canvas) {
    attachOverworldHexControls(canvas, {
      onHoverOffset: function(off, pos) {
        if (!simHost.state.world || !simHost.state.world.overworld || !off) {
          setWargameHoverTile(null, null);
          renderOverworldHoverTooltip(simHost.state, null, null);
          return;
        }
        const ow = simHost.state.world.overworld;
        const selUnit = getSelectedOverworldUnit(simHost.state);
        if (off.x >= 0 && off.x < ow.width && off.y >= 0 && off.y < ow.height) {
          let previewRoute = null;
          if (selUnit && selUnit.alive && isOverworldTilePassable(ow, off.x, off.y)) {
            previewRoute = findOverworldPath(ow, selUnit.x, selUnit.y, off.x, off.y);
          }
          setWargameHoverTile({ x: off.x, y: off.y }, previewRoute);
          renderOverworldHoverTooltip(simHost.state, { x: off.x, y: off.y }, pos);
        } else {
          setWargameHoverTile(null, null);
          renderOverworldHoverTooltip(simHost.state, null, null);
        }
      },
      onTapOffset: function(off) {
        if (!simHost.state.world || !simHost.state.world.overworld || !off) return;
        const ow = simHost.state.world.overworld;
        if (off.x < 0 || off.x >= ow.width || off.y < 0 || off.y >= ow.height) return;

        // PF-05: Picking a map tile for Army/Team Formation destination
        if (simHost.state._pickingDeployHex && simHost.state._deployArmyDraft) {
          simHost.state._pickingDeployHex = false;
          simHost.state._deployArmyDraft.targetX = off.x;
          simHost.state._deployArmyDraft.targetY = off.y;
          simHost.state._deployArmyDraft.targetId = null;
          simHost.state._deployArmyModalOpen = true;
          simHost.state._dirty = true;
          syncWargameUI(simHost);
          return;
        }

        // Task 05B-2 explicit UI contract: tapping a discovered military target ALWAYS selects & inspects it
        // and NEVER auto-redirects an army or marches a unit without explicit Deploy/Assign confirmation.
        const tappedTarget = getMilitaryTargetAtHex(ow, off.x, off.y);
        if (tappedTarget && (tappedTarget.discovered || (ow.explored[tappedTarget.y] && ow.explored[tappedTarget.y][tappedTarget.x]))) {
          simHost.state._selectedMilitaryTargetId = tappedTarget.id;
          simHost.state._dirty = true;
          syncWargameUI(simHost);
          return;
        }

        // Selecting an existing player unit/army on the tapped hex
        const tappedUnit = (ow.units || []).find(function(u) {
          return u && u.alive && u.x === off.x && u.y === off.y;
        });
        const selUnit = getSelectedOverworldUnit(simHost.state);
        if (tappedUnit && (!selUnit || tappedUnit.id !== selUnit.id)) {
          simHost.state._selectedMilitaryTargetId = null;
          ow.selectedUnitId = tappedUnit.id;
          simHost.state._dirty = true;
          syncWargameUI(simHost);
          return;
        }

        simHost.state._selectedMilitaryTargetId = null;
        if (selUnit && selUnit.alive) {
          if (selUnit.unitType === 'army') {
            simHost.dispatch({
              type: COMMAND_TYPES.REDIRECT_ARMY,
              payload: { armyId: selUnit.id, targetX: off.x, targetY: off.y }
            });
          } else {
            simHost.dispatch({
              type: COMMAND_TYPES.ORDER_UNIT_MARCH,
              payload: { unitId: selUnit.id, targetX: off.x, targetY: off.y }
            });
          }
          simHost.state._dirty = true;
          simHost.save();
          syncWargameUI(simHost);
        }
      },
      onRepaint: function() {
        renderWargameOverworldCanvas(simHost);
      }
    });

    canvas.addEventListener('mouseleave', function() {
      setWargameHoverTile(null, null);
      clearOverworldEdgeScrollPointer();
      renderOverworldHoverTooltip(simHost.state, null, null);
    });
  }

  // Delegated Button Click Dispatcher (Guarantees clicks register even across re-renders)
  document.addEventListener('click', function(e) {
    if (!e.target) return;
    const btn = e.target.closest('button[data-action]');
    if (!btn) return;
    // Avoid double-firing buttons that already execute via inline onclick
    if (btn.getAttribute && btn.getAttribute('onclick')) return;
    const action = btn.dataset.action;
    if (action === 'found-city') {
      handleFoundCity();
    } else if (action === 'claim-task') {
      const taskId = btn.dataset.taskId;
      if (taskId) handleClaimTask(taskId);
    } else if (action === 'respawn-settler') {
      handleRespawnSettler();
    } else if (action === 'cancel-march') {
      handleCancelMarch();
    } else if (action === 'enter-dungeon') {
      handleEnterDungeon(btn.dataset.poiId || null);
    } else if (action === 'march-to-dungeon') {
      if (btn.dataset.poiId) handleMarchToDungeon(btn.dataset.poiId);
    } else if (action === 'return-to-city') {
      handleReturnToCity();
    } else if (action === 'queue-building') {
      const pIdx = parseInt(btn.dataset.plotIndex, 10);
      const bId = btn.dataset.buildingId;
      if (!isNaN(pIdx) && bId) handleQueueBuilding(pIdx, bId);
    } else if (action === 'cancel-building') {
      const qId = btn.dataset.queueItemId;
      if (qId) handleCancelBuilding(qId);
    } else if (action === 'demolish-building') {
      const pIdx = parseInt(btn.dataset.plotIndex, 10);
      if (!isNaN(pIdx)) handleDemolishBuilding(pIdx);
    } else if (action === 'recruit-hero') {
      const cId = btn.dataset.classId;
      if (cId) handleRecruitHero(cId);
    } else if (action === 'cancel-recruitment') {
      const qId = btn.dataset.queueItemId;
      if (qId) handleCancelRecruitment(qId);
    } else if (action === 'select-party') {
      const hId = btn.dataset.heroId;
      if (hId) handleSelectPartyByHero(hId);
    } else if (action === 'select-plot') {
      const pIdx = parseInt(btn.dataset.plotIndex, 10);
      if (!isNaN(pIdx)) {
        if (typeof simHost.state._moveSourcePlotIndex === 'number') {
          const srcIdx = simHost.state._moveSourcePlotIndex;
          delete simHost.state._moveSourcePlotIndex;
          if (srcIdx !== pIdx) handleMoveBuilding(srcIdx, pIdx);
          else syncWargameUI(simHost);
        } else {
          handleSelectCityPlot(pIdx);
        }
      }
    } else if (action === 'start-move-mode') {
      const pIdx = parseInt(btn.dataset.plotIndex, 10);
      if (!isNaN(pIdx)) handleStartMoveMode(pIdx);
    } else if (action === 'cancel-move-mode') {
      handleCancelMoveMode();
    } else if (action === 'continue-campaign') {
      handleContinueCampaignClick();
    } else if (action === 'reset-title') {
      handleResetToTitle();
    }
  });

  // Guarantee state preservation when leaving page (navigating to dungeon mode, reload, etc.)
  window.addEventListener('beforeunload', function() {
    if (simHost && simHost.state && simHost.state.world) {
      simHost.save();
    }
  });
  window.addEventListener('pagehide', function() {
    if (simHost && simHost.state && simHost.state.world) {
      simHost.save();
    }
  });

  // Wire visual Developer Control Panel delegated listeners (HR-15)
  attachDevConsolePanelListeners(devConsole, renderDevConsoleDrawer);

  // Global Keyboard shortcuts (context-gated: Strategy vs. Dungeon)
  window.addEventListener('keydown', function(e) {
    const isConsoleInput = Boolean(e.target && e.target.id === 'wgDevConsoleInput');
    if (isConsoleInput) {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleRunDevConsoleCommand();
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        e.target.value = devConsole.getHistoryPrev();
      } else if (e.key === 'ArrowDown') {
        e.preventDefault();
        e.target.value = devConsole.getHistoryNext();
      } else if (e.key === 'Escape') {
        e.preventDefault();
        handleToggleDevConsole(false);
      }
      return;
    }
    // Avoid capturing inputs when typing into input fields
    if (e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA' || e.target.tagName === 'SELECT')) {
      if (e.key === 'Escape' && devConsole.isOpen()) {
        e.preventDefault();
        handleToggleDevConsole(false);
      }
      return;
    }
    if (e.key === '`' || e.key === '~') {
      e.preventDefault();
      handleToggleDevConsole();
      return;
    }
    if (e.key === 'Escape' && devConsole.isOpen()) {
      e.preventDefault();
      handleToggleDevConsole(false);
      return;
    }

    if (!simHost.state.world) return;

    if (appContext.getActiveContext() === APP_CONTEXTS.DUNGEON) {
      if (isAutoWalking()) cancelAutoWalk();
      let dx = 0;
      let dy = 0;
      if (e.key === 'w' || e.key === 'W' || e.key === 'ArrowUp') dy = -1;
      else if (e.key === 's' || e.key === 'S' || e.key === 'ArrowDown') dy = 1;
      else if (e.key === 'a' || e.key === 'A' || e.key === 'ArrowLeft') dx = -1;
      else if (e.key === 'd' || e.key === 'D' || e.key === 'ArrowRight') dx = 1;

      if (dx !== 0 || dy !== 0) {
        e.preventDefault();
        if (e.shiftKey) runCorridor(dx, dy);
        else handlePlayerAction(dx, dy);
        syncIntegratedDungeonHud();
      } else if (e.key === ' ') {
        e.preventDefault();
        waitTurn();
        syncIntegratedDungeonHud();
      } else if (e.key === 'q' || e.key === 'Q') {
        e.preventDefault();
        handleToggleDungeonSpellbook();
      } else if (e.key >= '1' && e.key <= '4') {
        e.preventDefault();
        const slotIdx = parseInt(e.key, 10) - 1;
        handleDungeonQuickSlot(slotIdx);
      } else if (e.key === 'Escape' && getManualTargetingAbility()) {
        e.preventDefault();
        handleCancelDungeonTargeting();
      } else if (e.key === 'Escape' && dungeonSpellbookOpen) {
        e.preventDefault();
        handleToggleDungeonSpellbook(false);
      } else if (e.key === 'h' || e.key === 'H') {
        e.preventDefault();
        handleDungeonTonic();
      } else if (e.key === 'r' || e.key === 'R') {
        e.preventDefault();
        handleDungeonRecall();
      } else if (e.key === 'e' || e.key === 'E') {
        e.preventDefault();
        useStairsAtPlayer();
        syncIntegratedDungeonHud();
      } else if (e.key === 'i' || e.key === 'I' || e.key === 'c' || e.key === 'C') {
        e.preventDefault();
        handleToggleDungeonInventory();
      } else if (e.key === 'Escape' && dungeonInventoryOpen) {
        e.preventDefault();
        handleToggleDungeonInventory(false);
      }
      return;
    }

    if (e.key === 'w' || e.key === 'W' || e.key === 'ArrowUp') {
      handleStepOverworld(0, -1);
    } else if (e.key === 's' || e.key === 'S' || e.key === 'ArrowDown') {
      handleStepOverworld(0, 1);
    } else if (e.key === 'a' || e.key === 'A' || e.key === 'ArrowLeft') {
      handleStepOverworld(-1, 0);
    } else if (e.key === 'd' || e.key === 'D' || e.key === 'ArrowRight') {
      handleStepOverworld(1, 0);
    } else if (e.key === ' ') {
      handleTogglePauseClock();
    } else if (e.key === 'q' || e.key === 'Q') {
      e.preventDefault();
      if (simHost.state._openHeroSheetId) {
        handleCloseHeroSheet();
      } else {
        const selOw = getSelectedOverworldUnit(simHost.state);
        const hId = (selOw && selOw.leaderHeroId) || null;
        if (simHost.state.activeView === WARGAME_VIEWS.OVERWORLD) {
          simHost.state._spellbookActiveContext = 'overworld';
        }
        handleOpenHeroSheet(hId);
      }
    } else if (e.key >= '1' && e.key <= '4' && simHost.state.activeView === WARGAME_VIEWS.OVERWORLD && !simHost.state._openHeroSheetId) {
      const selOw = getSelectedOverworldUnit(simHost.state);
      if (selOw && selOw.leaderHeroId) {
        e.preventDefault();
        handleOverworldQuickSlot(parseInt(e.key, 10) - 1);
      } else if (e.key === '1') {
        handleSetSimSpeed(1);
      } else if (e.key === '2') {
        handleSetSimSpeed(2);
      }
    } else if (e.key === '1') {
      handleSetSimSpeed(1);
    } else if (e.key === '2') {
      handleSetSimSpeed(2);
    } else if (e.key === '5') {
      handleSetSimSpeed(5);
    } else if (e.key === 'i' || e.key === 'I' || e.key === 'c' || e.key === 'C') {
      if (simHost.state._openHeroSheetId) handleCloseHeroSheet();
      else handleOpenHeroSheet();
    } else if (e.key === 'Escape' && simHost.state._openHeroSheetId) {
      handleCloseHeroSheet();
    }
  });
}

// ---------------------------------------------------------------------------
// Main Real-Time Simulation Loop
// ---------------------------------------------------------------------------
let lastUiSyncRealMs = 0;

function wargameMainLoop(timestamp) {
  if (!lastFrameTimestamp) lastFrameTimestamp = timestamp;
  const elapsedRealMs = Math.min(250, timestamp - lastFrameTimestamp);
  lastFrameTimestamp = timestamp;

  if (appContext.getActiveContext() === APP_CONTEXTS.DUNGEON) {
    renderDungeonCanvas();
    autoSaveAccumulatorMs += elapsedRealMs;
    if (autoSaveAccumulatorMs >= 5000) {
      autoSaveAccumulatorMs = 0;
      simHost.save();
    }
  } else if (simHost.state.world && simHost.state.campaignPhase !== CAMPAIGN_PHASES.TITLE) {
    appContext.syncFromCampaignPhase();
    simHost.stepClock(elapsedRealMs);

    autoSaveAccumulatorMs += elapsedRealMs;
    if (autoSaveAccumulatorMs >= 5000) {
      autoSaveAccumulatorMs = 0;
      simHost.save();
    }

    if (simHost.state.activeView === WARGAME_VIEWS.OVERWORLD) {
      stepOverworldEdgeScroll(elapsedRealMs / 1000, simHost.state);
      renderWargameOverworldCanvas(simHost);
    }

    // CB-03 -> CB-04: Transition Victory/Defeat banner (~2s) cleanly into Battle Results Popup
    if (simHost.state._battleOutcomeBanner && Date.now() >= simHost.state._battleOutcomeBanner.expiresAtRealMs) {
      simHost.state._battleResultsPopup = simHost.state._battleOutcomeBanner.report || null;
      simHost.state._battleOutcomeBanner = null;
      simHost.state._dirty = true;
    }

    updateHeaderFastTick(simHost);

    // Throttle DOM rebuilds so buttons don't get destroyed mid-click
    if (simHost.state._dirty || (timestamp - lastUiSyncRealMs >= 400)) {
      lastUiSyncRealMs = timestamp;
      simHost.state._dirty = false;
      tickWorldProgression(simHost);
      syncWargameUI(simHost);
    }
  }

  requestAnimationFrame(wargameMainLoop);
}

