function bootstrapWargame() {
  if (wargameBootstrapped) return;
  wargameBootstrapped = true;

  // CB-02 & CB-03: Subscribe presentation feedback strictly to authoritative combat events
  simHost.eventStream.subscribe(STREAM_TOPICS.ARMY_COMBAT_ROUND_RESOLVED, function(ev) {
    if (ev && ev.payload) {
      spawnOverworldCasualtyFloaters(ev.payload);
      simHost.state._dirty = true;
    }
  });
  simHost.eventStream.subscribe(STREAM_TOPICS.ARMY_COMBAT_RESOLVED, function(ev) {
    if (ev && ev.payload) {
      const rpt = ev.payload;
      simHost.state._battleOutcomeBanner = {
        battleId: rpt.battleId || null,
        victory: Boolean(rpt.victory),
        armyName: rpt.armyName || 'Field Army',
        targetName: rpt.targetName || 'Military Target',
        report: rpt,
        expiresAtRealMs: Date.now() + (BATTLE_OUTCOME_BANNER_DURATION_MS || 2000)
      };
      simHost.state._battleResultsPopup = null;
      simHost.state._dirty = true;
    }
  });

  simHost.eventStream.subscribe(STREAM_TOPICS.OVERWORLD_SKIRMISH, function(ev) {
    if (ev && ev.payload) {
      const sk = ev.payload;
      if (typeof sk.x === 'number' && typeof sk.y === 'number') {
        spawnOverworldCasualtyFloaters({
          x: sk.x,
          y: sk.y,
          attackerLosses: sk.damageTaken || 0,
          defenderLosses: sk.victory ? 1 : 0
        });
      }
      simHost.state._battleOutcomeBanner = {
        battleId: 'skirmish_' + (sk.hostileId || Date.now()),
        isSkirmish: true,
        victory: Boolean(sk.victory),
        armyName: sk.unitName || 'Hero Party',
        targetName: sk.hostileName || 'Wandering Hostile',
        summary: sk.victory
          ? ('Skirmish Victory! Took ' + (sk.damageTaken || 0) + ' dmg • +' + (sk.rewardGold || 0) + 'g, +' + (sk.rewardOre || 0) + ' Ore, +' + (sk.rewardXp || 0) + ' XP')
          : ('Retreated to ' + (sk.retreatedToCity || 'Bastion') + ' after taking ' + (sk.damageTaken || 0) + ' dmg'),
        report: null,
        expiresAtRealMs: Date.now() + (BATTLE_OUTCOME_BANNER_DURATION_MS || 2000) + 1500
      };
      simHost.state._dirty = true;
    }
  });

  setupWargameListeners();
  appContext.syncFromCampaignPhase();
  syncWargameUI(simHost);
  requestAnimationFrame(wargameMainLoop);
}

if (typeof window !== 'undefined') {
  window.WargameApp = WargameApp;
  window.WargameSimHost = simHost;

  if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
      window.addEventListener('DOMContentLoaded', bootstrapWargame);
    } else {
      bootstrapWargame();
    }
  }
}

